-- Built 2026-09-09

-- TOPICS
INSERT OR IGNORE INTO topics (id, unit, category, name, priority, must_know, should_know, nice_to_know, status, updated_at) VALUES
(1, 'Cardiovascular health', 'Presentation', 'Chest pain', 'VH', 'Immediate ACS rule-out: ECG within 10 minutes of arrival; aspirin 300 mg unless contraindicated; 000/ED transfer if suspected ACS. Discriminate GORD, musculoskeletal, PE, pericarditis, aortic dissection.', 'Tropinin pathways and safe rule-out; when CT coronary angiography is appropriate; PE risk scores.', 'Aortic dissection risk scores; pericarditis ECG changes.', 'not started', '2026-09-09'),
(2, 'General', 'Presentation', 'Tiredness / fatigue', 'VH', 'Screen for depression, sleep, alcohol, anaemia, diabetes, hypothyroid, coeliac, meds. Targeted first-line tests: FBE, UEC, LFT, TSH, ferritin, BGL/HbA1c, CRP if inflammatory cause suspected.', 'When to add B12, folate, coeliac serology, EBV/other infective screen; chronic fatigue syndrome criteria and management.', 'Sleep apnoea screening tools (STOP-BANG).', 'not started', '2026-09-09'),
(3, 'Neurological presentations', 'Presentation', 'Headache', 'VH', 'Red flags: thunderclap sudden onset, fever/neck stiffness, papilloedema/focal neurology, new headache >50y, GCA features >50y, medication-overuse. Primary headaches: migraine, tension, cluster.', 'Migraine acute and prophylactic management (Australian choices); GCA workup (ESR/CRP, urgent steroid, temporal artery); benign intracranial hypertension.', 'Cluster treatments (oxygen, sumatriptan).', 'not started', '2026-09-09'),
(4, 'Neurological presentations', 'Presentation', 'Dizziness / vertigo', 'H', 'Separate peripheral (BPPV, vestibular neuronitis) from central (stroke, MS). HINTS exam. Dix-Hallpike for BPPV + Epley. Postural BP in older patients on antihypertensives.', 'Vestibular migraine; Red flags requiring urgent neuroimaging (acute persistent, neuro signs, inability to walk).', 'Vestibular rehabilitation referral.', 'not started', '2026-09-09'),
(5, 'Gastrointestinal health', 'Presentation', 'Abdominal pain', 'VH', 'Surgical abdomen signs; discriminate biliary, appendicitis, diverticulitis, renal colic, gynae (ectopic in women of reproductive age - always consider pregnancy), mesenteric ischaemia in elderly.', 'Chronic: IBS criteria, coeliac, IBD red flags, cancer (change in bowel habit, PR bleeding).', 'Functional abdominal pain management.', 'not started', '2026-09-09'),
(6, 'Respiratory health', 'Presentation', 'Dyspnoea', 'VH', 'Immediate: asthma, COPD exacerbation, heart failure, PE, pneumothorax, pneumonia. Examination triage: respiratory distress, SpO2, accessory muscles. When to send to ED.', 'Chronic causes: interstitial disease, anaemia, deconditioning, anxiety. BNP role.', 'Pulmonary function interpretation subtleties.', 'not started', '2026-09-09'),
(7, 'Respiratory health', 'Presentation', 'Cough', 'H', 'Duration drives workup: acute (URTI, bronchitis, pneumonia, pertussis); chronic >4 weeks (post-infectious, asthma, GORD, upper airway cough syndrome, ACE inhibitor, lung cancer in smokers). Red flags: haemoptysis, weight loss, smoker.', 'Pertussis testing and public health notification; when CXR.', 'Cough hypersensitivity syndrome.', 'not started', '2026-09-09'),
(8, 'General', 'Presentation', 'Weight loss', 'H', 'Malignancy, hyperthyroid, depression/dementia in elderly, diabetes, coeliac, TB. Red flags: >5% body weight in 6 months, dysphagia, PR bleeding, night sweats. Structured workup; consider malignancy review.', 'Elder safe assessment: eat/walk/dementia; sarcopenia vs cachexia.', 'HIV testing in risk groups.', 'not started', '2026-09-09'),
(9, 'Infectious diseases', 'Presentation', 'Fever in adults', 'H', 'Common viral vs bacterial; focal exam; when blood cultures before antibiotics; sepsis recognition (qSOFA); immunosuppressed febrile patient = urgent ED.', 'Q fever/leptospirosis risk occupations (QLD farmers, abbatoir workers); returned traveller fever (malaria risk - urgent if falciparum zone).', 'Notifiable diseases list and mechanisms (QLD).', 'not started', '2026-09-09'),
(10, 'Dermatological presentations', 'Presentation', 'Rash', 'H', 'Life-threatening: meningococcal (petechiae + fever = ED), SJS/TEN, necrotising fasciitis, eczema herpeticum. Common: urticaria, dermatitis, psoriasis, tinea, drug eruption.', 'Describe lesions formally (morphology, distribution); biopsy rules; photosensitivity; melanoma ABCD + ugly duckling.', 'Dermoscopy patterns.', 'not started', '2026-09-09'),
(11, 'Musculoskeletal presentations', 'Presentation', 'Joint pain', 'VH', 'Inflammatory pattern: morning stiffness >60 min, swelling, small joints. Septic arthritis = joint aspiration same day (ED) - do not start antibiotics before aspiration. Gout acute treatment. New RA - early referral.', 'Osteoarthritis non-surgical ladder; safe NSAID use; PMR >50 with shoulder/hip girdle pain + ESR.', 'Seronegative spondyloarthritis features.', 'not started', '2026-09-09'),
(12, 'Musculoskeletal presentations', 'Presentation', 'Back pain', 'VH', 'Red flags: cauda equina (saddle anaesthesia, urinary retention - ED), cancer history, fever (discitis), weight loss, trauma. Most acute low back pain: stay active, no imaging in first 4-6 weeks.', 'Radicular pain and radiculopathy management; when physio; chronic pain pathway.', 'Specific exercises controversial.', 'not started', '2026-09-09'),
(13, 'Haematological presentations', 'Presentation', 'Abnormal blood tests', 'VH', 'Anaemia, high/low platelets, high WCC, high ESR/CRP, abnormal LFTs, eGFR decline: each needs structured interpretation, repeat/confirm, and a clear next step. Do not discharge or ignore persistent unexplained abnormal results - investigate or refer.', 'Incidental thrombocytosis (iron deficiency, inflammation); monoclonal protein/paraprotein - haematology referral.', 'Unexplained high ESR/CRP workups.', 'not started', '2026-09-09'),
(14, 'Gastrointestinal health', 'Presentation', 'Abnormal liver function tests', 'H', 'Pattern: hepatocellular (ALT) vs cholestatic (ALP+GGT). Common: NAFLD, alcohol, drugs. Screen: repeat LFT, viral serology (Hep B/C), ferritin, autoimmune (ANA/ASMA), ultrasound. ALP isolated high: check GGT; bone source.', 'When to refer; fatty liver monitoring; hepatotoxic meds (amoxiclav, statins).', 'Gilbert syndrome; Wilson disease in young.', 'not started', '2026-09-09'),
(15, 'Haematological presentations', 'Presentation', 'Anaemia', 'VH', 'Microcytic (iron deficiency - always find cause in adults: coeliac, malignancy esp. bowel; men and postmenopausal women need GI workup) vs macrocytic (B12/folate, alcohol, hypothyroid) vs normocytic (CKD, anaemia of chronic disease).', 'Ferritin optimal >30 (some use >50 with inflammation); anaemia in pregnancy; reticulocytes.', 'Haemoglobinopathies.', 'not started', '2026-09-09'),
(16, 'Kidney and urinary health', 'Presentation', 'Haematuria', 'VH', 'Visible haematuria in >40s: exclude malignancy - urgent urology/CT urogram; glomerular (dysmorphic RBC/proteinuria) vs urological. UTI treatment before re-testing after infection.', 'IgA nephropathy; thin basement membrane; ACR role.', 'Exercise-induced haematuria.', 'not started', '2026-09-09'),
(17, 'Child and youth health', 'Presentation', 'Child with fever', 'VH', 'Infant <3 months with fever = urgent hospital referral. Traffic light (NICE/RCH): green - manage, amber - review 24h, red - refer. Fever without focus; petechial rash = ED; meningococcal signs in children.', 'Fever duration and urine testing in young children; Kawasaki features (fever >5 days + red eyes, mucositis).', 'Periodic fever syndromes.', 'not started', '2026-09-09'),
(18, 'Pregnancy and reproductive health', 'Presentation', 'Pregnancy-related presentations', 'H', 'First trimester bleeding/pain: ectopic must be excluded (quantitative bhCG, ultrasound). BP >=140/90 in pregnancy = review same day; severe headache/visual symptoms/RUQ pain = urgent obstetric review. Postnatal depression screen (EPDS).', 'Antenatal schedule; medication safety in pregnancy; hyperemesis management.', 'Non-invasive prenatal testing options.', 'not started', '2026-09-09'),
(19, 'Mental health', 'Presentation', 'Behavioural concern', 'H', 'In children: developmental, autism, ADHD, family stress, school issues; in elderly: delirium vs dementia vs depression. Always check safety (self-harm, harm to others, child protection).', 'Autism referral pathways (QLD: NDIS, paediatrician); conduct disorder.', 'Parenting programs.', 'not started', '2026-09-09'),
(20, 'General', 'Presentation', 'Screening consultation', 'VH', 'Australian programs: cervical (25-74, 5-yearly HPV test, self-collection choice), bowel (45-74, 2-yearly iFOBT), breast (50-74 invited 2-yearly, 40+ eligible). Also: Aboriginal and Torres Strait Islander health checks (annual, MBS 715), 75+ health assessment, 45-49 health assessment, STI screening by risk, CVD risk assessment.', 'Preventive activities from Red Book (10th ed 2024); lifestyle: smoking, alcohol, activity, diet, sun; immunisation status; family history of cancer criteria.', 'Unproven screening to avoid (whole-body scans, routine tumour markers) - Red Book lists tests NOT to do.', 'not started', '2026-09-09'),
(21, 'Cardiovascular health', 'System', 'Hypertension', 'VH', 'Diagnosis: confirm with repeat + out-of-office (ABPM/HBPM) before treating. Assess absolute CVD risk (Aus CVD Risk Calculator) not BP alone. Lifestyle first, then pharmacotherapy per risk. 2026 Australian HTN guideline due Q4 2026 (Heart Foundation/Stroke Foundation/Hypertension Australia) - watch for threshold changes.', 'White coat hypertension; resistant HTN; secondary causes screening (young <40, sudden, resistant: renin, aldosterone, renal artery, sleep apnoea, drugs).', 'Home BP meter validation.', 'not started', '2026-09-09'),
(22, 'Cardiovascular health', 'System', 'Ischaemic heart disease and ACS', 'VH', 'Secondary prevention post-ACS per 2025 Australian ACS guideline; angina assessment; stress testing limitations. Primary prevention: absolute risk approach. Statins intensity by risk.', 'Aspirin primary prevention NOT routinely recommended; antiplatelet + DOAC combinations.', 'CAC score role.', 'not started', '2026-09-09'),
(23, 'Cardiovascular health', 'System', 'Atrial fibrillation', 'VH', 'Screen opportunistically by pulse/ECG in >65y. CHA2DS2-VA (Australian 2018 guideline dropped the sex category) for stroke risk. Anticoagulate (DOAC preferred) when score >=2 (>=1 in some); rate vs rhythm control.', 'DOAC selection with renal impairment; bleeding risk discussion; alcohol as precipitant.', 'Catheter ablation indications.', 'not started', '2026-09-09'),
(24, 'Cardiovascular health', 'System', 'Heart failure', 'H', 'Diagnosis: BNP/NT-proBNP + echo. HFrEF quadruple therapy: ACEi/ARB or ARNI, beta blocker, MRA, SGLT2i. Acute decompensation red flags.', 'When MBS-supported chronic disease management plan items apply.', 'Cardiac resynchronisation.', 'not started', '2026-09-09'),
(25, 'Respiratory health', 'System', 'Asthma', 'VH', 'Diagnosis: variable airflow obstruction (spirometry with reversibility). Australian Asthma Handbook (NAC): SABA-only treatment is OUT - every patient with a diagnosis needs ICS-containing therapy; ICS-formoterol as needed (AIR) or maintenance. Written action plan. Reliever overuse = review.', 'FeNO role; inhaler technique checks; exercise-induced bronchoconstriction.', 'Anti-IgE/biologics referral.', 'not started', '2026-09-09'),
(26, 'Respiratory health', 'System', 'COPD', 'VH', 'Diagnosis: spirometry post-bronchodilator FEV1/FVC <0.7. Lung Foundation Australia COPD-X consensus: smoking cessation is the only intervention that changes trajectory; pulmonary rehab; vaccinations; SAMA/SABA then LAMA/LABA + ICS if eosinophils/exacerbations.', 'Oxygen assessment; exacerbation management (steroids, antibiotics when indicated); non-invasive ventilation.', 'Lung volume reduction.', 'not started', '2026-09-09'),
(27, 'Endocrine and metabolic health', 'System', 'Type 2 diabetes', 'VH', 'Diagnosis: HbA1c >=6.5% (confirm if asymptomatic) or fasting BGL >=7.0 or OGTT 2hr >=11.1, or random >=11.1 with symptoms. Management: lifestyle + metformin; ADD-STEP: early comorbidity-based agent choice (SGLT2i/GLP-1 for CVD/CKD/obesity); retinal + foot + ACR screening annually; individualised HbA1c target (generally <=7%).', 'GLP-1 agonist practicalities; insulin initiation; steroid-induced hyperglycaemia; driving standards (Austroads) for insulin-treated drivers.', 'CGM for T2DM.', 'not started', '2026-09-09'),
(28, 'Endocrine and metabolic health', 'System', 'Thyroid disease', 'H', 'TSH-first testing. Overt: treat. Subclinical: repeat 6-8 weeks, TPO antibodies; treat hypothyroidism if TSH >10 or pregnant/infertility. Thyroid nodule: check TSH, ultrasound, FNA per malignancy risk.', 'Amiodarone thyroid effects; post-partum thyroiditis; levothyroxine absorption (iron, calcium).', 'Graves ophthalmopathy referral.', 'not started', '2026-09-09'),
(29, 'Kidney and urinary health', 'System', 'Chronic kidney disease', 'H', 'Staging: eGFR category (G1-G5) + albuminuria (A1-A3). eGFR <60 for >3 months, or ACR >=3 mg/mmol persistently. Kidney Health Australia: BP control, RAAS blockade if albuminuria, SGLT2i, avoid nephrotoxins (NSAIDs, dehydration + contrast). Refer nephrology per criteria (eGFR <30, rapid decline, proteinuria, haematuria).', 'Medication dose adjustment by eGFR; sick day rules.', 'Genetic cystic disease.', 'not started', '2026-09-09'),
(30, 'Musculoskeletal presentations', 'System', 'Osteoporosis', 'H', 'First Fracture Prevention: any low-trauma fracture after 50 = investigate (DEXA) and treat. Calcium (diet) + vitamin D + resistance exercise; bisphosphonate first-line; treat 3-5 years then reassess. Secondary causes screen.', 'Glucocorticoid-induced osteoporosis prevention; denosumab practicalities (must not delay next dose).', 'Anabolic agents.', 'not started', '2026-09-09'),
(31, 'Mental health', 'System', 'Depression and anxiety', 'VH', 'Screen (PHQ-9, GAD-7, K10); suicide risk assessment (thoughts, plan, means, intent, protective factors). Stepped care: psychological therapy first for mild-moderate; add SSRI for moderate-severe. Review 2 weeks then 4-6 weeks. Black dog Institute/RACGP guidance.', 'Perinatal mental health; older persons depression; IPT; medication interactions (SSRI + tramadol = serotonin syndrome).', 'Treatment-resistant pathways; rTMS.', 'not started', '2026-09-09'),
(32, 'Mental health', 'System', 'Suicide risk assessment', 'VH', 'Ask directly. Safety planning (not no-suicide contracts). Means restriction. Lethality: plan/intent/access. Involve mental health service, safety net carers, remove access. Document.', 'QLD pathways: Mental Health Line 1300 642 255; ED vs community options; Mental Health Act QLD involuntary assessment criteria.', 'chronic vs acute risk framing.', 'not started', '2026-09-09'),
(33, 'Women''s health', 'System', 'Contraception', 'VH', 'UKMEC categories; LARC first-line discussion (implant, IUDs); copper IUD = emergency contraception most effective; ulipristal 5 days; levonorgestrel 120h weight caveat (efficacy reduced >70-80 kg). Prescribing: BP, history.', 'IUD insertion pathways; Quick start; missed pill rules; contraception in perimenopause.', 'Permanent options counselling.', 'not started', '2026-09-09'),
(34, 'Women''s Health', 'System', 'Menopause and perimenopause', 'H', 'MHT indications/contraindications; timing hypothesis (window of opportunity <60y or <10y since menopause); vaginal oestrogen for GSM; bone protection.', 'Non-hormonal options; compounded hormones NOT recommended (menopause society position).', 'Testosterone role.', 'not started', '2026-09-09'),
(35, 'Dermatological presentations', 'System', 'Skin cancer', 'VH', 'Australia: highest melanoma incidence. ABCD/E + ugly duckling + change; NMSC (BCC/SCC) common. Biopsy rules: excision 2mm BCC, 2mm + 4mm SCC margins (in practice refer face/large); photography for surveillance; total body skin exam.', 'Melanoma risk factors (naevi, family, colouring); 3 monthly self-check; cryotherapy limits.', 'Dermoscopy; targeted therapy era.', 'not started', '2026-09-09'),
(36, 'Infectious diseases', 'System', 'Antimicrobial stewardship and common infections', 'VH', 'Therapeutic Guidelines (eTG) is the reference. Common: UTI (nitrofurantoin first-line uncomplicated), cellulitis (flucloxacillin), community pneumonia (amoxycillin; doxycycline if atypical cover), impetigo, otitis media (watchful waiting), sinusitis, strep pharyngitis (penicillin). Penicillin allergy de-labelling.', 'Resistance patterns (QLD); when to swab; MRSA coverage; clindamycin resistance for Group A strep pharyngitis in far north QLD (empiric benzylpenicillin safe).', 'Newer agents (ceftaroline).', 'not started', '2026-09-09'),
(37, 'Infectious diseases', 'System', 'Immunisation', 'VH', 'NIP Schedule (current: 21vPCV replacing 13vPCV/23vPPV in adults from mid-2026; RSV program; MenB with paracetamol prophylaxis). AIR checking; catch-up rules; valid contraindications (anaphylaxis, immunosuppression live vaccines); timing with other vaccines.', 'ATAGI statements; vaccine errors management; adverse event reporting; pregnancy vaccination (influenza, pertussis 20-32w, COVID).', 'Clinical trial data details.', 'not started', '2026-09-09'),
(38, 'Infectious diseases', 'System', 'HIV and sexual health', 'H', 'Australian STI Management Guidelines for GPs; ASHM. Screening by risk; contact tracing; test of choice by site (NAAT first void urine etc). HIV: treat all diagnosed (same-day start after confirmatory), PrEP eligibility (gay/bisexual men, trans, heterosexual with risk) - PBS-listed; PEP within 72h.', 'HIV indicator conditions; syphilis interpretation (avoid the prozone); neonatal STI.', 'Doxycycline PEP-STI.', 'not started', '2026-09-09'),
(39, 'Haematological presentations', 'System', 'Anticoagulation', 'VH', 'DOACs first-line for AF/VTE in eligible; renal dosing; perioperative management (stop timing by bleeding risk); reversal agents; warfarin for mechanical valves. VTE treatment duration: provoked 3 months, unprovoked >=3 months then reassess; cancer-associated = indefinite.', 'Bleeding risk scores; aspirin+anticoagulant = avoid unless recent ACS/stent.', 'Tranexamic acid use.', 'not started', '2026-09-09'),
(40, 'Neurological presentations', 'System', 'Stroke and TIA', 'H', 'FAST recognition; call 000 - thrombolysis/thrombectomy windows are time-critical (4.5h/24h). TIA = urgent assessment (same day) - ABCD2 not for triage in Australia; risk of early stroke post-TIA. Post-stroke secondary prevention.', 'Carotid imaging; AF detection post-stroke; aspirin + clopidogrel dual for minor stroke.', 'Patent foramen ovale closure.', 'not started', '2026-09-09'),
(41, 'Neurological presentations', 'System', 'Headache: migraine', 'H', 'Diagnostic criteria (5 attacks, 4-72h, 2 of 4 features, 1 of 2 nausea/photo); triptans acute (not with aura-only? safe), prophylaxis if >=4 days/month (propranolol, amitriptyline, topiramate); contraceptive caveats with aura (avoid oestrogen if migraine with aura).', 'CGRP antagonists (PBS restricted); medication-overuse headache.', 'Neuromodulation.', 'not started', '2026-09-09'),
(42, 'Gastrointestinal health', 'System', 'Inflammatory bowel disease and functional GI', 'H', 'IBD red flags (nocturnal symptoms, weight loss, PR bleeding, family history) - refer; exclude infection (stool MC&S) before steroids. IBS: positive diagnosis (Rome IV), dietary steps, low FODMAP diet with dietitian.', '5-ASA, biologics overview; colonoscopic surveillance.', 'Faecal calprotectin use.', 'not started', '2026-09-09'),
(43, 'Gastrointestinal health', 'System', 'Liver disease', 'H', 'NAFLD/MASLD: commonest chronic liver disease; diagnose by exclusion + fibrosis assessment (FIB-4, elastography). Viral hepatitis B and C: test (estimated undiagnosed cohorts), hepatitis C = curable (direct-acting antivirals, PBS), screen for cirrhosis (all HCV), hepatocellular carcinoma surveillance 6-monthly ultrasound if cirrhotic.', 'Vaccination (Hep A/B in chronic liver disease); alcohol thresholds; fibroscan access.', 'Non-invasive fibrosis markers.', 'not started', '2026-09-09'),
(44, 'Gastrointestinal health', 'System', 'Coeliac disease', 'M', 'Test BEFORE gluten-free diet: tTG-IgA + total IgA. Biopsy confirm (adults). 6-12 monthly review; DEXA, vaccinations (pneumococcal).', 'Dermatitis herpetiformis; family screening.', 'Refractory coeliac.', 'not started', '2026-09-09'),
(45, 'Endocrine and metabolic health', 'System', 'Obesity', 'H', 'BMI class + waist; stigma-free care; 5-10% weight loss goals; GLP-1 pharmacotherapy now PBS for eligible (semaglutide criteria); multidisciplinary referral; bariatric surgery criteria (BMI >=35 with comorbidity).', 'Obesity as chronic disease; weight cycling.', 'Emerging agents.', 'not started', '2026-09-09'),
(46, 'Endocrine and metabolic health', 'System', 'Lipids', 'H', 'Absolute CVD risk drives statin prescribing (2023 Australian Guideline: assess 45-74 from 30 in ATSI, consider >75). Statins: high-intensity for established CVD, high risk, diabetes >=50 (or with risk); familial hypercholesterolaemia red flags (LDL >5 mmol/L, family) - refer.', 'Statin myalgia management (rechallenge/alternate); ezetimibe; PCSK9i access.', 'Lp(a) once in lifetime.', 'not started', '2026-09-09'),
(47, 'Men''s health', 'System', 'Prostate and mens health screening', 'M', 'PSA: shared decision-making, no population screening program (RACGP recommends AGAINST organised screening; discuss harms/benefits from 50, 40 if family history or ATSI). Erectile dysfunction: assess CVS risk (ED = marker). Testicular - no routine screening. Health checks and mental health/suicide risk in men.', 'Lower urinary tract symptoms treatment ladder; active surveillance.', '5-alpha reductase effects.', 'not started', '2026-09-09'),
(48, 'Eye presentations', 'System', 'Ophthalmology in general practice', 'H', 'Red flags: acute vision loss = same-day ED/ophthalmology (GCA, retinal artery occlusion, CRAO), acute angle closure, chemical injury (irrigate first), penetrating injury (shield, nil by mouth, ED), contact lens keratitis. Diabetes retinal screening; glaucoma opportunistic.', 'Red eye triage tree; fluorescein use; trichiasis.', 'OCT use.', 'not started', '2026-09-09'),
(49, 'ENT', 'System', 'ENT and oral health', 'H', 'Otitis media management (watchful waiting; when abx); sore throat (centor criteria); epistaxis first aid; hearing loss patterns (Rinne/Weber); nasal steroids for sinusitis; oral cancer red flags (non-healing ulcer >3 weeks).', 'Tonsillectomy criteria; grommets; vertigo ENT causes.', 'Rhinology advances.', 'not started', '2026-09-09'),
(50, 'Paediatrics', 'System', 'Child development and behavioural problems', 'H', 'Developmental milestones red flags at each age; surveillance vs screening; ASD/ADHD pathways in QLD; school refusal; enuresis (behavioural first, alarms); constipation (disimpaction then maintenance - PEG).', 'FASD; prematurity follow-up; child health nurse partnership.', 'Genetic syndromes.', 'not started', '2026-09-09'),
(51, 'Paediatrics', 'System', 'Common paediatric conditions', 'H', 'Bronchiolitis (supportive, no bronchodilators/steroids/antibiotics per RCH CPG), croup (dexamethasone 0.15 mg/kg), URTI, gastroenteritis (oral rehydration, no routine antiemetics - ondansetron single dose may reduce admission in selected; zinc/rotavirus vaccine), febrile convulsion advice, eczema (steroid ladder, bleach baths).', 'Intussusception; appendingitis in young children; UTI collection methods.', 'Persistent bacterial bronchitis.', 'not started', '2026-09-09'),
(52, 'Older persons health', 'System', 'Older persons comprehensive care', 'VH', '75+ health assessment; polypharmacy review (deprescribing); falls assessment (orthostatic BP, vision, home hazards, vitamin D if deficient); cognition assessment (cognitive screen then...); elder abuse screen; driving (Austroads: dementia standards, on-road assessment); end-of-life planning; RACF and aged care standards; Silver Book (Medical care of older persons in RACFs) as the reference.', 'Aged care GP programs (including 2024+ funding model); delirium prevention; sarcopenia.', 'Anti-aging hype.', 'not started', '2026-09-09'),
(53, 'Palliative care', 'System', 'Palliative care', 'H', 'Terminal care in the home/RACF; symptom control basics (Palliative Care Australia, Therapeutic Guidelines Palliative Care): pain ladder, nausea, breathlessness, secretions, delirium; anticipatory prescribing; Recognising the dying phase (imminent death signs); Carer support; Therapeutic Guidelines: palliative version available free via RACGP.', 'Palliative care referral criteria; MBS items for palliative; MTGP planning (voluntary assisted dying - QLD legal since 2023: eligibility, process, safeguards).', 'Paediatric palliative.', 'not started', '2026-09-09'),
(54, 'Addiction medicine', 'System', 'Alcohol and other drugs', 'H', 'Screening: AUDIT-C; brief intervention; alcohol withdrawal (CIWA-Ar, thiamine before glucose); opioid substitution (buprenorphine-naloxone PBS); methadone; safe opioid prescribing; overdose prevention; smoking cessation: brief intervention, Ask-Advise-Help; pharmacotherapy (varenicline first-line now PBS wide, bupropion, NRT); needle programs.', 'Cannabis legalisation QLD 2025 changes; vaping cessation; synthetic drugs.', 'Mandala/other new agents.', 'not started', '2026-09-09'),
(55, 'Abuse and violence', 'System', 'Family and domestic violence', 'VH', 'Ask directly, privately (never with partner/children present); safety assessment; LIVE-FRISK principles (Western Australia/Australian-adopted framework) or e-ki (for practise); White Book is the RACGP reference; mandatory reporting only for children (and QLD: adults in some contexts).', 'Duluth tools; referral pathways; reproductive coercion; strangulation risk.', 'Restorative programs.', 'not started', '2026-09-09'),
(56, 'Aboriginal and Torres Strait Islander health', 'Population', 'Aboriginal and Torres Strait Islander health', 'VH', 'Closing the Gap; annual 715 health check; cultural safety definition and practice; PBS CTG scripts for medicines; chronic conditions targeted support; specific high-priority conditions (diabetes, CVD from younger ages - risk assessment from 30y, kidney disease, rheumatic heart disease in some regions, otitis media, smoking rates, mental health, suicide); mums and bubs programs; acknowledge Country appropriately.', 'National Agreement on Closing the Gap; First Nations-led services (Community Controlled Health Organisations); CTG scripts bridging the gap with conventional registers.', 'Local MM/Torres Strait context (Minjerribah/North Stradbroke Island community).', 'not started', '2026-09-09');

-- QUESTIONS (chunked)
INSERT OR IGNORE INTO questions (id, type, topic, unit, stem, options, answers, explanation, pearl, trap) VALUES
(1, 'AKT', 'Asthma', 'Respiratory health', 'A 24-year-old woman has used salbutamol 3-4 times/week for nocturnal symptoms over the past 3 months. Spirometry shows reversible obstruction. Asthma was diagnosed a year ago. Which SINGLE management step is MOST appropriate?', '{"options": ["Add a long-acting beta agonist (LABA) alone", "Start ICS-formoterol combination (maintenance and/or reliever) and stop SABA-only use", "Refer for bronchoscopy", "Add oral prednisolone 40 mg daily", "Double the salbutamol dose"]}', '{"answers": [1]}', 'Australian Asthma Handbook: a confirmed diagnosis with symptoms needing reliever >2x/week needs ICS-containing therapy. SABA-only treatment is no longer recommended; ICS-formoterol as maintenance and/or reliever (AIR) is preferred for most.', 'Diagnosis + reliever overuse = ICS-formoterol, not more SABA.', 'LABA alone is unsafe in asthma (increased mortality) - never LABA without ICS.'),
(2, 'AKT', 'Chest pain', 'Cardiovascular health', 'A 58-year-old man presents to your practice with 30 minutes of central chest tightness, sweating and nausea. ECG shows ST elevation in II, III, aVF. The hospital with PCI is 5 minutes away. MOST appropriate immediate management?', '{"options": ["Call 000 for emergency transfer to PCI-capable hospital, give aspirin 300 mg while waiting", "Give aspirin 300 mg and review in 30 minutes", "Organise troponin for tomorrow", "Start sublingual GTN and observe", "Refer non-urgently to cardiology outpatient"]}', '{"answers": [0]}', 'STEMI = time-critical reperfusion. Call 000 immediately; primary PCI preferred over thrombolysis where available. Aspirin 300 mg is given while waiting, but the critical action is emergency transfer.', 'STEMI in general practice: 000 first, aspirin 300, GTN if BP allows, oxygen only if hypoxic.', 'Waiting for troponin or reviewing later = missed reperfusion window.'),
(3, 'AKT', 'Atrial fibrillation', 'Cardiovascular health', 'A 67-year-old woman with newly diagnosed AF, CHA2DS2-VA = 3 (age 65-74, hypertension, diabetes). She had a GI bleed 5 years ago from aspirin. MOST appropriate stroke prevention?', '{"options": ["Aspirin 100 mg daily", "Apixaban 5 mg bd", "Warfarin INR target 2-3", "No anticoagulation", "Clopidogrel 75 mg daily"]}', '{"answers": [1]}', 'CHA2DS2-VA >=2 warrants anticoagulation. DOAC (apixaban) preferred over warfarin for non-valvular AF; a remote GI bleed is not an absolute contraindication (discuss bleeding risk). Aspirin is NOT adequate stroke prevention in AF.', 'Anticoagulate CHA2DS2-VA >=2 with a DOAC; aspirin is not a substitute.', 'Choosing aspirin because of remote bleeding history - antiplatelets do not protect in AF.'),
(4, 'AKT', 'Type 2 diabetes', 'Endocrine and metabolic health', 'A 58-year-old man with T2DM for 6 years, HbA1c 8.2% on maximal metformin, had an NSTEMI 8 months ago. eGFR 68. Which add-on agent is MOST appropriate?', '{"options": ["Sitagliptin", "Dapagliflozin (SGLT2 inhibitor)", "Gliclazide", "Insulin glargine", "Pioglitazone"]}', '{"answers": [1]}', 'SGLT2i have proven cardiovascular and renal benefit in T2DM with established CVD/CKD - comorbidity-driven agent selection (ADD-STEP approach). Sulfonylureas add hypoglycaemia risk; insulin is not the next step at HbA1c 8.2%.', 'T2DM + established CVD or CKD = SGLT2i (or GLP-1 if obesity), regardless of HbA1c.', 'Choosing agent purely by glucose-lowering power rather than comorbidity.'),
(5, 'AKT', 'Hypertension', 'Cardiovascular health', 'A fit 46-year-old man has clinic BP 148/94 mmHg on two occasions, no end-organ damage, absolute CVD risk 8%. Home readings average 135/85. MOST appropriate next step?', '{"options": ["Start amlodipine 5 mg daily", "Recheck BP in 12 months with lifestyle advice", "Commence ramipril", "Refer for renal artery imaging", "Arrange 24-hour ABPM to confirm the diagnosis before treatment decisions"]}', '{"answers": [4]}', 'Clinic 148/94 with home average 135/85 raises the possibility of an elevated clinic reading without confirmed hypertension; out-of-office confirmation (ABPM/HBPM) is the recommended step before committing to pharmacotherapy at low-moderate absolute risk.', 'Confirm hypertension with out-of-office measurement before starting drugs at low-intermediate risk.', 'Starting drugs based on clinic readings alone when home readings suggest white-coat effect.'),
(6, 'AKT', 'Cervical screening', 'Women''s health', 'A 31-year-old woman is 2 years overdue for her Cervical Screening Test. She is asymptomatic but has significant anxiety about speculum examination. MOST appropriate approach?', '{"options": ["Reassure and defer until age 35", "Offer self-collected vaginal swab for HPV testing", "Insist on clinician-collected speculum sample", "Refer for colposcopy", "Do a Pap test"]}', '{"answers": [1]}', 'Self-collection is an equal-accuracy option for all screening participants (expanded from July 2022). If HPV (not 16/18) is detected on a self-collected sample, she returns for clinician-collected LBC.', 'Self-collection = same HPV-PCR accuracy; use it for anxious and under-screened patients.', 'Assuming self-collection is inferior or only for remote settings.'),
(7, 'AKT', 'COPD', 'Respiratory health', 'A 69-year-old man with COPD (FEV1 52% predicted) on LAMA/LABA has had 2 exacerbations in the past year requiring oral corticosteroids. Blood eosinophils 0.4 x10^9/L. Next MOST appropriate step?', '{"options": ["Add roflumilast", "Add ICS to LAMA/LABA (triple therapy)", "Add azithromycin prophylaxis", "Start home oxygen", "Refer for lung volume reduction"]}', '{"answers": [1]}', 'COPD-X: consider ICS addition when eosinophils >=0.3 x10^9/L or >=2 exacerbations in the past year on LAMA/LABA - both criteria overlap here. Triple therapy via a single inhaler improves adherence.', 'Frequent exacerbator + eosinophils >=0.3: step to triple therapy.', 'Azithromycin prophylaxis is for selected patients; oxygen only if hypoxic on assessment.'),
(8, 'AKT', 'Immunisation', 'Infectious diseases', 'A 72-year-old man had 13vPCV 3 years ago and asks about pneumococcal vaccination. MOST appropriate advice per the current Australian Immunisation Handbook?', '{"options": ["No further pneumococcal vaccines needed", "A dose of 21vPCV is recommended (NIP for all adults >=70), at least 12 months after any previous pneumococcal dose", "He needs 23vPPV now", "Annual influenza vaccine replaces pneumococcal", "Refer to an immunisation specialist"]}', '{"answers": [1]}', 'Per the Handbook update (June 2026), 21vPCV replaced 13vPCV and 23vPPV in the adult schedule: all adults >=70 (and >=50 for Aboriginal and Torres Strait Islander adults) are recommended 21vPCV at least 12 months after any previous pneumococcal dose; NIP risk groups expanded to include COPD and chronic liver disease.', 'Adult pneumococcal schedule changed in 2026: 21vPCV is now the adult vaccine; 13v/23v removed from the Handbook.', 'Recommending 23vPPV - a deliberately dated distractor.'),
(9, 'AKT', 'Back pain', 'Musculoskeletal presentations', 'A 34-year-old man presents with acute low back pain after lifting, no red flags. Which approach is MOST evidence-based?', '{"options": ["Bed rest 3-5 days", "Stay active + heat + simple analgesia; review if not improving in 2-4 weeks", "Immediate MRI lumbar spine", "Opioids first-line", "Corset/brace for 6 weeks"]}', '{"answers": [1]}', 'Without red flags, imaging is not indicated acutely. Advice to stay active, heat, NSAIDs or simple analgesia; review at 2-4 weeks if not settling. Early imaging worsens outcomes.', 'Red flags first (cauda equina, cancer, infection, fracture) - then reassure and keep moving.', 'MRI for acute uncomplicated back pain - the classic over-investigation trap.'),
(10, 'AKT', 'Back pain', 'Musculoskeletal presentations', 'A 55-year-old woman with known bone metastases from breast cancer presents with 2 weeks of progressive thoracic back pain, worse at night, and new difficulty walking. Examination: mild bilateral leg weakness. MOST appropriate action?', '{"options": ["Arrange urgent MRI whole spine today - possible malignant spinal cord compression", "Start physiotherapy", "Prescribe paracetamol + codeine and review in 1 week", "Arrange DEXA", "Oral bisphosphonate and review next week"]}', '{"answers": [0]}', 'Cancer + progressive back pain + new neurology = malignant spinal cord compression until proven otherwise. Same-day MRI and urgent oncology/ED referral; dexamethasone may be started on specialist advice.', 'Known malignancy + new neurology = cord compression: MRI today, not next week.', 'Treating as mechanical pain in a patient with a cancer history.'),
(11, 'AKT', 'Haematuria', 'Kidney and urinary health', 'A 58-year-old woman presents with a single episode of painless visible haematuria. UTI excluded. She is otherwise well. MOST appropriate next step?', '{"options": ["Reassure; repeat urinalysis in 3 months", "Refer for assessment of possible urological malignancy (CT urogram + cystoscopy pathway)", "5-day course of trimethoprim empirically", "Renal biopsy", "Observe; only refer if it recurs"]}', '{"answers": [1]}', 'Visible haematuria in an adult, after excluding infection, warrants assessment to exclude urological malignancy - do not wait for recurrence. This is a long-established must-not-miss presentation.', 'Visible haematuria (any adult): exclude infection, then refer - do not observe.', 'Waiting for a second episode or treating with empirical antibiotics.'),
(12, 'AKT', 'Suicide risk', 'Mental health', 'A 24-year-old man with depression presents 3 days after a near-lethal hanging attempt. He declines admission and refuses community follow-up. MOST appropriate next step?', '{"options": ["Discharge home with a letter for the mental health service and review in 1 week", "Arrange urgent same-day psychiatric assessment (ED or QLD Mental Health Line); involuntary assessment if criteria met per QLD Mental Health Act 2016", "Prescribe an SSRI and review in 2 weeks", "Give a crisis line number and ask parents to watch him", "Refer to a private psychiatrist - wait 4-6 weeks"]}', '{"answers": [1]}', 'A recent near-lethal attempt + refusal of follow-up = high imminent risk requiring same-day psychiatric assessment; involuntary assessment criteria under the QLD Mental Health Act 2016 may be met. Never manage imminent risk with routine outpatient pathways.', 'Imminent risk = same-day psychiatric assessment; know your state Mental Health Act pathway.', 'Routine referral speed for acute risk, or relying on family observation alone.'),
(13, 'AKT', 'Stable angina', 'Cardiovascular health', 'A 62-year-old man has typical exertional chest pain relieved by rest and GTN. Investigations confirm stable angina with preserved LV function. Which combination is the MOST appropriate initial medical management?', '{"options": ["Aspirin, statin, beta-blocker and sublingual GTN as required", "Warfarin, statin and calcium-channel blocker", "Aspirin alone with GTN, add statin only if total cholesterol is raised", "ACE inhibitor, diuretic and digoxin", "Ranolazine and nicorandil as first-line therapy"]}', '{"answers": [0]}', 'Stable angina: antiplatelet (aspirin), high-intensity statin, rate-limiting antianginal (beta-blocker first-line if no contraindication) plus GTN PRN for breakthrough.', 'Four pillars: aspirin + statin + beta-blocker + GTN.', 'Forgetting the statin - it is part of angina management, not just for high cholesterol.'),
(14, 'AKT', 'Aortic dissection', 'Cardiovascular health', 'A 68-year-old hypertensive man has sudden severe tearing chest pain radiating to his back. BP is 190/105 in the right arm and 150/90 in the left. ECG is non-diagnostic. What is the MOST appropriate next step?', '{"options": ["CT angiography of the aorta via emergency transfer", "Troponin to exclude myocardial infarction before proceeding", "Transthoracic echocardiogram in the practice", "Oral antihypertensive and review in the morning", "Exercise stress test"]}', '{"answers": [0]}', 'Tearing pain to the back with inter-arm BP differential is classic dissection. Time-critical: emergency transfer for CT angiography (or TOE if unstable). Troponin and stress testing are dangerous delays.', 'BP difference between arms or new aortic regurgitation murmur: think dissection.', 'Anchoring on troponin/ECG because the pain is chest pain.'),
(15, 'AKT', 'Heart failure', 'Cardiovascular health', 'A 70-year-old woman has breathlessness, orthopnoea and ankle oedema. BNP is raised and an echocardiogram shows HFrEF (EF 35%). She is euvolaemic. Which single management plan is MOST appropriate?', '{"options": ["Start an ACE inhibitor (or ARNI), beta-blocker, MRA and SGLT2 inhibitor as tolerated", "Furosemide alone as long-term therapy", "Digoxin first-line to improve ejection fraction", "ACE inhibitor only once symptoms worsen", "Referral for transplant assessment before any medication"]}', '{"answers": [0]}', 'HFrEF quadruple therapy (ACEi/ARNI, beta-blocker, MRA, SGLT2i) reduces mortality and is started early and titrated. Diuretics manage congestion but do not alter prognosis.', 'Four disease-modifying drugs in HFrEF; diuretics are for volume, not mortality.', 'Digoxin - symptom/rate drug, not first-line mortality therapy.'),
(16, 'AKT', 'Hypertension', 'Cardiovascular health', 'A 54-year-old man attends with BP 214/128 on repeated reading. He has a mild headache but no chest pain, no neurological signs, and urinalysis is clear. What is the MOST appropriate management?', '{"options": ["Commence or adjust oral antihypertensives and arrange same-day medical review", "IV antihypertensive in the practice", "Increase his existing amlodipine and review in 2 weeks", "Recheck in 1 week with no medication change", "Observation only as he is asymptomatic"]}', '{"answers": [0]}', 'Severe asymptomatic hypertension (no target-organ damage features) is managed with prompt oral therapy and same-day review. IV therapy and ED are for hypertension emergencies with organ damage.', 'Emergency = high BP plus organ damage (chest pain, neuro signs, pulmonary oedema).', 'IV bolus antihypertensives causing precipitous drops - or waiting weeks unreviewed.'),
(17, 'AKT', 'Hypertension', 'Cardiovascular health', 'A 32-year-old woman has BP 165/100 despite three antihypertensives. Potassium is 3.1, sodium 139, and she is not on a diuretic. Which investigation is MOST likely to reveal the diagnosis?', '{"options": ["Plasma aldosterone-to-renin ratio", "Renal artery angiography", "24-hour urinary metanephrines", "Thyroid function tests", "Echocardiogram"]}', '{"answers": [0]}', 'Young onset resistant hypertension with spontaneous hypokalaemia strongly suggests primary aldosteronism (Conn syndrome). The screening test is the aldosterone:renin ratio (ensure interfering drugs reviewed first).', 'Resistant + young + low K = screen for secondary causes, starting with ARR.', 'Jumping to imaging before biochemical screening.'),
(18, 'AKT', 'Hypertension', 'Cardiovascular health', 'An 83-year-old woman on amlodipine and doxazosin has dizziness on standing and a fall. Lying BP 150/84, standing BP 118/70 with symptoms. What is the MOST useful single intervention?', '{"options": ["Cease or reduce the doxazosin and give standing-up advice", "Add fludrocortisone", "Increase the amlodipine dose", "Add midodrine", "Encourage increased salt and fluid restriction of her evening dose"]}', '{"answers": [0]}', 'Symptomatic postural hypotension: first review culprit drugs (alpha-blockers, vasodilators, diuretics) and give behavioural advice (stand slowly, legs crossed, adequate fluids). Pressor agents are later options.', 'Drug review before drug addition in older fallers.', 'Prescribing a new drug for a drug side-effect.'),
(19, 'AKT', 'Lipids', 'Cardiovascular health', 'A 42-year-old man has LDL 6.1 mmol/L, no other risk factors. His brother had an MI at 44 and his father at 49. What is the MOST appropriate action?', '{"options": ["Refer to a specialist lipid service for suspected familial hypercholesterolaemia and arrange family cascade screening", "Start a statin and review in 12 months", "Reassure - it is only relevant once absolute risk exceeds 15%", "Start ezetimibe alone", "Repeat the lipid profile in 5 years"]}', '{"answers": [0]}', 'LDL >5 mmol/L with a family history of premature CVD suggests familial hypercholesterolaemia: refer for specialist assessment, treat as high risk, and trigger cascade screening of relatives. FH is not risk-calculator-dependent.', 'FH bypasses absolute-risk calculation - it is automatically high risk.', 'Reassuring on the basis of a low calculated 5-year risk score.'),
(20, 'AKT', 'Peripheral arterial disease', 'Cardiovascular health', 'A 66-year-old smoker has calf pain walking 200 metres, relieved by standing still. Ankle-brachial index is 0.62. What is the MOST appropriate initial management?', '{"options": ["Supervised walking-exercise program with smoking-cessation support, antiplatelet and statin", "Immediate referral for lower-limb bypass surgery", "Referral for lumbar sympathectomy", "Compression stockings", "Rest and elevation of the legs"]}', '{"answers": [0]}', 'Intermittent claudication is managed first with supervised exercise, smoking cessation, antiplatelet and statin therapy. Revascularisation is reserved for critical limb ischaemia or lifestyle-limiting claudication refractory to best medical therapy.', 'Supervised exercise + stop smoking beat scalpel for most claudication.', 'Operating before best medical therapy, or compression (harmful in arterial disease).'),
(21, 'AKT', 'Atrial fibrillation', 'Cardiovascular health', 'A 68-year-old man with permanent AF has resting HR 105 despite monotherapy. He has mild asthma. Which is the MOST appropriate rate-control first-line agent?', '{"options": ["A cardioselective beta-blocker (e.g., metoprolol or bisoprolol)", "Digoxin", "Verapamil", "Amiodarone", "Flecainide"]}', '{"answers": [0]}', 'Beta-blockers (cardioselective) are first-line for AF rate control and safe in most mild asthma (monitor). Digoxin is for sedentary patients or add-on; verapamil an alternative if beta-blocker contraindicated (caution asthma is fine for verapamil actually, but beta-blockers remain first choice). Amiodarone/flecainide are rhythm agents.', 'Rate first: beta-blocker; verapamil if beta-blocker truly contraindicated.', 'Amiodarone for simple rate control - long-term toxicity.'),
(22, 'AKT', 'Syncope', 'Cardiovascular health', 'A 19-year-old athlete collapses briefly while sprinting. He reports central chest tightness during training over recent weeks. Examination is normal. What is the MOST appropriate action?', '{"options": ["Urgent cardiology referral with echocardiogram for exertional syncope", "Reassure - vasovagal syncope is common in the young", "Holter monitor organised routinely and review in 6 months", "Electroencephalogram", "Prescribe a beta-blocker and review in 3 months"]}', '{"answers": [0]}', 'Exertional syncope is a red flag suggesting an arrhythmic or structural cause (HOCM, arrhythmogenic cardiomyopathy) and mandates urgent cardiology assessment with echo and ECG before resuming sport.', 'Exertional syncope is never vasovagal until proven otherwise.', 'Reassurance - a common and dangerous reflex in young patients.'),
(23, 'AKT', 'Secondary prevention', 'Cardiovascular health', 'An 80-year-old man survived an MI 3 months ago. He continues to smoke, takes all his medications, and asks what single measure will reduce his future risk most. What do you advise?', '{"options": ["Stopping smoking", "Doubling his statin dose", "Adding a fibrate", "Monthly CPAP for nocturnal snoring", "Low-dose aspirin increase to 300 mg daily"]}', '{"answers": [0]}', 'Smoking cessation is the single most powerful secondary-prevention intervention post-MI, reducing mortality substantially. No pharmacologic adjustment outperforms quitting in a continuing smoker.', 'In a smoker post-MI, quitting beats any tablet change.', 'Escalating drugs while the modifiable driver is ignored.'),
(24, 'AKT', 'Valvular disease', 'Cardiovascular health', 'A 74-year-old woman has exertional breathlessness and one episode of syncope on exertion. She has an ejection systolic murmur radiating to the carotids with a slow-rising pulse. Echo shows severe aortic stenosis. What is the MOST appropriate management?', '{"options": ["Urgent referral for valve intervention assessment (surgical or transcatheter)", "Annual echo monitoring only", "ACE inhibitor and diuretic as for heart failure", "Commence anticoagulation", "Exercise program to improve exertional symptoms"]}', '{"answers": [0]}', 'Symptomatic severe aortic stenosis (angina, syncope, heart failure) has a poor prognosis without valve replacement; refer urgently for intervention. Vasodilators can precipitate collapse.', 'Syncope + AS = urgent; avoid vasodilators.', 'Treating AS as ordinary heart failure with ACE inhibitors.'),
(25, 'AKT', 'Acute coronary syndromes', 'Cardiovascular health', 'A 58-year-old man had a drug-eluting stent inserted after an NSTEMI 2 months ago and takes aspirin plus clopidogrel. He asks how long the clopidogrel must continue. What is the MOST appropriate advice, assuming no high bleeding risk?', '{"options": ["Continue dual antiplatelet therapy for 12 months in total, then aspirin long-term", "Stop the clopidogrel now as the stent is endothelialised", "Lifelong clopidogrel plus aspirin", "3 months in total is sufficient for all stents", "Switch clopidogrel to warfarin at 12 months"]}', '{"answers": [0]}', 'After ACS with DES, standard DAPT duration is around 12 months (individualised for bleeding risk), then lifelong single antiplatelet (aspirin). Premature cessation risks stent thrombosis.', 'DAPT 12 months post-ACS; never stop both agents without cardiology advice.', 'Stopping antiplatelets for minor procedures without coordination.'),
(26, 'AKT', 'Infective endocarditis', 'Cardiovascular health', 'A 55-year-old man with a prosthetic mitral valve has 2 weeks of fever, night sweats and new splinter haemorrhages. What is the MOST appropriate initial management?', '{"options": ["At least three sets of blood cultures before any antibiotics, then inpatient antibiotics", "Immediate oral amoxicillin in the community", "Start empirical IV flucloxacillin today to avoid delay", "Repeat inflammatory markers and review next week", "Transthoracic echo at the practice"]}', '{"answers": [0]}', 'Suspected endocarditis requires multiple blood cultures before antibiotics (to identify the organism and guide weeks of therapy) plus inpatient management; echo follows.', 'Culture first: endocarditis therapy is organism-directed for 4-6 weeks.', 'Empirical antibiotics destroying the diagnostic yield.'),
(27, 'AKT', 'Pericarditis', 'Cardiovascular health', 'A 28-year-old man has sharp pleuritic chest pain improved by leaning forward. ECG shows saddle-shaped ST elevation with PR depression. Troponin is mildly raised. What is the MOST appropriate management?', '{"options": ["NSAID plus colchicine for up to 3 months", "Immediate coronary angiography for the raised troponin", "Antibiotics for presumed myocarditis", "Steroids as first-line therapy", "Aspirin alone for 1 week"]}', '{"answers": [0]}', 'Acute pericarditis (with or without myopericarditis) is treated with NSAIDs plus colchicine, which reduces recurrence. Steroids are second-line (associated with relapse). Mild troponin rise indicates myopericarditis, not automatic angiography, in a clear pericarditis picture.', 'Colchicine halves pericarditis recurrence.', 'Mild troponin elevation reflexively triggering the ACS pathway.'),
(28, 'AKT', 'Obstructive sleep apnoea', 'Respiratory health', 'A 49-year-old man snores heavily, wakes unrefreshed and falls asleep at his desk. BMI 36, BP 152/94, neck 45 cm. Epworth score is 16. What is the MOST appropriate next step?', '{"options": ["Refer for a sleep study", "Trial of mandibular advancement splint", "Start modafinil for daytime sleepiness", "Nasal steroid spray and review in 6 months", "Weight-loss advice alone with no objective testing"]}', '{"answers": [0]}', 'High pre-test probability OSA (STOP-BANG high, Epworth 16, hypertension): confirm severity with a sleep study (home or in-lab) to guide CPAP and cardiovascular risk management. Stimulants treat the symptom, not the disease.', 'Sleepy + snoring + hypertensive + obese = study, not guesswork.', 'Medicating sleepiness without diagnosing the cause.'),
(29, 'AKT', 'Lung cancer', 'Respiratory health', 'A 66-year-old smoker has 3 months of right shoulder pain unresponsive to physiotherapy, now with right arm weakness and drooping eyelid. What is the MOST appropriate initial investigation?', '{"options": ["Chest X-ray today, with urgent respiratory referral if abnormal", "MRI of the cervical spine", "Shoulder ultrasound", "Nerve conduction studies for brachial plexopathy", "Trial of pregabalin and review in 4 weeks"]}', '{"answers": [0]}', 'Shoulder pain plus arm wasting with ptosis and miosis in a smoker is a Pancoast tumour (apical lung cancer invading the brachial plexus and sympathetic chain). CXR is the first test, then urgent respiratory referral.', 'Pancoast = arm symptoms + Horner syndrome; look at the lung apex.', 'Managing chronic shoulder pain without imaging in a high-risk smoker.'),
(30, 'AKT', 'Pulmonary embolism', 'Respiratory health', 'A 45-year-old woman presents with acute pleuritic breathlessness 10 days after a hip replacement. She is haemodynamically stable, HR 98, SpO2 93%. Wells score is moderate probability. What is the MOST appropriate next step?', '{"options": ["CT pulmonary angiogram without waiting for d-dimer", "D-dimer alone, imaging only if positive", "Ventilation-perfusion scan in 3 days", "Lower-limb ultrasound first", "Start therapeutic enoxaparin and observe overnight"]}', '{"answers": [0]}', 'With moderate-to-high pre-test probability, d-dimer cannot rule out PE; go straight to CTPA. D-dimer is only for low probability. She also needs anticoagulation once confirmed (post-operative provoked VTE).', 'D-dimer excludes only in low-probability presentations.', 'A negative d-dimer falsely reassuring in a moderate-probability patient.'),
(31, 'AKT', 'Asthma', 'Respiratory health', 'A 26-year-old woman with well-controlled asthma is 10 weeks pregnant and asks about her preventer. What is the MOST appropriate advice?', '{"options": ["Continue her regular ICS (budesonide preferred in pregnancy) - good control protects mother and baby", "Stop all asthma medication during the first trimester", "Switch the preventer to oral theophylline", "Use salbutamol only, as frequently as needed", "Commence oral corticosteroids prophylactically"]}', '{"answers": [0]}', 'Untreated asthma in pregnancy is riskier than treated asthma. Continue ICS (budesonide has the best pregnancy data) with reliever as needed. Poor control raises hypoxia and preterm risk.', 'Pregnant asthmatics: preventers stay, avoid the trap of stopping inhaled steroids.', 'Withdrawing preventers and treating only symptoms.'),
(32, 'AKT', 'COPD', 'Respiratory health', 'A 70-year-old man with COPD (FEV1 48%) has had two hospital admissions for exacerbations this year. He still smokes. Which intervention is MOST likely to reduce his future admissions and mortality?', '{"options": ["Pulmonary rehabilitation plus smoking-cessation support", "Long-term oral prednisolone", "Home oxygen despite adequate saturations", "Long-term azithromycin for all patients", "Inhaled corticosteroid monotherapy"]}', '{"answers": [0]}', 'Pulmonary rehabilitation improves exercise capacity and reduces admissions; smoking cessation is the only intervention that slows decline and improves survival. Steroid tablets are harmful long-term; prophylactic azithromycin is for selected patients.', 'Rehab + quitting: the two highest-yield COPD interventions.', 'Maintenance oral steroids for COPD - delirium, osteoporosis, diabetes.'),
(33, 'AKT', 'Bronchiectasis', 'Respiratory health', 'A 58-year-old woman has a 10-year history of daily purulent sputum, recurrent chest infections and two hospitalisations. She is a lifelong non-smoker. Which investigation will MOST likely establish the diagnosis?', '{"options": ["High-resolution CT chest", "Spirometry with reversibility", "Bronchoscopy with lavage", "Sputum culture alone", "Chest X-ray"]}', '{"answers": [0]}', 'Chronic productive cough with recurrent infections and possible clubbing suggests bronchiectasis; HRCT is the diagnostic standard. Spirometry is often normal or shows non-specific obstruction; plain films are insensitive.', 'Daily purulent sputum for years = HRCT.', 'Labelling it smoker''s cough or asthma for a non-smoker.'),
(34, 'AKT', 'COPD', 'Respiratory health', 'A 63-year-old smoker has FEV1 58% predicted and FEV1/FVC 0.55, unchanged post-bronchodilator. He has never had respiratory investigations before. What is the MOST appropriate interpretation?', '{"options": [" spirometry confirms airflow limitation not reversed by bronchodilator - consistent with COPD", "Reversible airflow obstruction consistent with asthma", "Restrictive lung disease", "Normal age-related spirometry", "Inconclusive - repeat spirometry in 12 months"]}', '{"answers": [0]}', 'Post-bronchodilator FEV1/FVC below 0.70 confirms persistent airflow limitation, defining COPD; a significant bronchodilator response would instead suggest asthma.', 'COPD = post-BD FEV1/FVC <0.70, persisting.', 'Diagnosing COPD on symptoms alone without spirometry.'),
(35, 'AKT', 'Pertussis', 'Infectious diseases', 'A 45-year-old teacher has 3 weeks of paroxysmal coughing fits ending in vomiting, worse at night, afebrile. Her whooping cough immunity has lapsed. What is the MOST appropriate management?', '{"options": ["Azithromycin and notify the public health unit", "Amoxicillin-clavulanate", "No treatment as the infectious period has passed at 3 weeks", "Chest X-ray before any antibiotic", "Salbutamol and review"]}', '{"answers": [0]}', 'Pertussis is clinical (cough >2 weeks with paroxysms/post-tussive vomiting in an adult): a macrolide within the treatment window reduces transmission, and pertussis is notifiable. Antibiotics rarely change the course at 3 weeks but limit spread.', 'Macrolide + notify; vaccinate household contacts per public health advice.', 'Assuming antibiotics at 3 weeks help the patient - they help the contacts.'),
(36, 'AKT', 'Type 1 diabetes', 'Endocrine and metabolic health', 'A 19-year-old man has 2 weeks of polyuria, polydipsia and 5 kg weight loss. Capillary glucose is 21 mmol/L with urine ketones 2+. He is alert. What is the MOST appropriate action?', '{"options": ["Same-day transfer to hospital for IV fluids and insulin", "Start basal-bolus insulin and review tomorrow in the practice", "Start metformin and dietary review this week", "Oral fluids and repeat glucose in 4 hours", "Refer to a diabetes educator over the next month"]}', '{"answers": [0]}', 'New type 1 diabetes with ketosis risks DKA; same-day hospital assessment with fluids and insulin is mandatory. Oral hypoglycaemics and delays are dangerous.', 'Glucose high + ketones = hospital today.', 'A well-looking young adult masking the urgency of impending DKA.'),
(37, 'AKT', 'Thyroid', 'Endocrine and metabolic health', 'A 68-year-old woman has a TSH of 0.03 with a normal free T4, persisting on repeat over 6 months, plus new atrial fibrillation risk factors. What is the MOST appropriate management?', '{"options": ["Specialist referral for definitive management of subclinical thyrotoxicosis", "Reassure and recheck in 12 months", "Start carbimazole", "Start levothyroxine", "No action ever needed for a low TSH with normal T4"]}', '{"answers": [0]}', 'Persistent subclinical hyperthyroidism in an older patient carries AF and bone-loss risk; endocrine referral for consideration of definitive therapy (radioiodine or surgery) is appropriate, with cardiology input for AF.', 'Subclinical hyper in older bones and hearts is not benign.', 'Dismissing a suppressed TSH as trivial when fT4 is normal.'),
(38, 'AKT', 'Thyroid', 'Endocrine and metabolic health', 'A 52-year-old woman on levothyroxine 100 mcg is started on iron tablets by another doctor and now reports fatigue; her TSH has risen. What is the MOST appropriate advice?', '{"options": ["Separate levothyroxine and iron by at least 4 hours", "Double her levothyroxine dose", "Switch all iron intake to afternoon and take thyroid hormone with it", "Stop the iron permanently", "Take both together with breakfast to improve absorption of each"]}', '{"answers": [0]}', 'Iron (and calcium) markedly reduces levothyroxine absorption, causing rising TSH. Separating doses by 4+ hours (or a different formulation) resolves it without dose escalation.', 'Iron and thyroxine in the same stomach = therapeutic failure.', 'Escalating the dose to overcome an interaction.'),
(39, 'AKT', 'PCOS', 'Endocrine and metabolic health', 'A 24-year-old woman with ultrasound-confirmed PCOS has irregular cycles and acne; she is not seeking pregnancy. What is the MOST appropriate first-line management?', '{"options": ["Combined oral contraceptive pill plus lifestyle changes", "Metformin alone", "Clomiphene immediately", "Anti-androgen cyproterone alone without contraception", "Laparoscopic ovarian drilling"]}', '{"answers": [0]}', 'In women not seeking fertility, the combined OCP regulates cycles, treats acne/hirsutism and provides contraception; lifestyle change addresses the metabolic substrate. Metformin is adjunct for metabolic features, not the primary cycle/acne therapy.', 'Not seeking pregnancy = COCP first.', 'Fertility drugs in a woman not trying to conceive - teratogenic and pointless.'),
(40, 'AKT', 'Type 2 diabetes', 'Endocrine and metabolic health', 'A 61-year-old man attends for his annual diabetes review. Which set of assessments constitutes the recommended annual cycle of care?', '{"options": ["HbA1c, blood pressure, lipids, eGFR and ACR, dilated eye examination, foot risk assessment", "HbA1c alone each year with eyes every 5 years", "Fasting glucose quarterly and nothing else", "Random glucose when symptomatic", "HbA1c and lipids only if he feels unwell"]}', '{"answers": [0]}', 'The annual cycle of care for T2DM covers glycaemia, cardiovascular risk factors (BP, lipids), nephropathy screening (eGFR + ACR), retinopathy screening, and foot assessment, plus vaccination and lifestyle review.', 'Kidneys (ACR), eyes, feet, BP, lipids, HbA1c - every year.', 'Tight HbA1c focus while the complications screens lapse.'),
(41, 'AKT', 'Hypoglycaemia', 'Endocrine and metabolic health', 'A 48-year-old insulin-treated truck driver asks about safe driving. What is the MOST appropriate advice?', '{"options": ["Check glucose before driving; if below 4 mmol/L treat, wait 15 minutes and recheck before driving", "Drive only within 30 minutes of eating, without testing", "Stop driving permanently once on insulin", "Keep sweets in the cab instead of testing", "If hypoglycaemic while driving, continue to the next town then stop"]}', '{"answers": [0]}', 'Austroads and diabetes guidance: SMBG before driving for insulin users; hypo <4 = stop safely, treat, wait and recheck before resuming. Also discuss reporting obligations for specified conditions.', 'Before the key turns, the glucometer reads.', 'Treating through the symptoms without rechecking.'),
(42, 'AKT', 'Steroid-induced hyperglycaemia', 'Endocrine and metabolic health', 'A 62-year-old man starts prednisolone 50 mg daily for polymyalgia rheumatica. Six weeks later he reports thirst and nocturia. What is the MOST appropriate next step?', '{"options": ["Check glucose/HbA1c - corticosteroids commonly unmask diabetes", "Assume it is PMR-related fatigue and increase the prednisolone", "Reassure that steroids cannot raise glucose", "Start metformin empirically without testing", "Reduce steroids to 5 mg to prevent diabetes"]}', '{"answers": [0]}', 'High-dose corticosteroids induce insulin resistance and commonly unmask or worsen diabetes - check BGL/HbA1c when symptoms arise on steroids (usually post-prandial first).', 'Steroid hyperglycaemia is typically worst in the afternoon (dose timing).', 'Blaming the underlying disease instead of its treatment.'),
(43, 'AKT', 'Obesity', 'Endocrine and metabolic health', 'A 44-year-old woman with BMI 38 and type 2 diabetes has not achieved target weight with 12 months of structured lifestyle support. She asks about medication. What is the MOST appropriate advice?', '{"options": ["A GLP-1 receptor agonist may be added to lifestyle therapy for eligible patients, alongside continued diet and activity support", "Orlistat is the only option ever available", "Weight-loss medication replaces the need for lifestyle measures", "Phentermine long-term is standard care", "No medication is appropriate once lifestyle has failed"]}', '{"answers": [0]}', 'For patients with obesity (especially with comorbidities) who have not reached goals with lifestyle alone, adjunct pharmacotherapy - GLP-1 agonists for eligible patients - is appropriate, always continued WITH lifestyle measures.', 'Drugs augment lifestyle; they never replace it.', 'Either/or thinking - medication or lifestyle.'),
(44, 'AKT', 'GORD', 'Gastrointestinal health', 'A 58-year-old man on long-term NSAIDs reports 3 months of worsening dysphagia to solids and 6 kg weight loss. What is the MOST appropriate action?', '{"options": ["Urgent endoscopy for alarm features", "Double the proton-pump inhibitor and review in 8 weeks", "Barium swallow", "Trial of a liquid diet and reassurance", "H. pylori stool antigen testing"]}', '{"answers": [0]}', 'Dysphagia plus weight loss in an older patient on NSAIDs are alarm features mandating urgent endoscopy to exclude malignancy - do not empirically escalate acid suppression.', 'Dysphagia + weight loss + anaemia + new symptoms over 55 = scope.', 'Reassuring a red-flag symptom with a PPI trial.'),
(45, 'AKT', 'IBS', 'Gastrointestinal health', 'A 32-year-old woman has 2 years of recurring abdominal pain relieved by defaecation, bloating and alternating bowel habit, with no weight loss, anaemia or bleeding. What is the MOST appropriate management?', '{"options": ["Positive diagnosis explanation, dietary review including a trial of a low-FODMAP diet with a dietitian", "Colonoscopy to exclude malignancy first", "Long-term codeine for the pain", "Wheat allergy testing", "Repeated courses of antibiotics"]}', '{"answers": [0]}', 'Rome IV criteria with absence of red flags supports a positive IBS diagnosis without invasive testing: explanation, dietary management (low-FODMAP, dietitian), symptom-directed therapy.', 'IBS is diagnosed positively; the colonoscopy is for red flags.', 'Investigating indefinitely while never treating.'),
(46, 'AKT', 'Coeliac disease', 'Gastrointestinal health', 'A 28-year-old woman has iron deficiency and intermittent loose stools. Her sister has coeliac disease. Which testing approach is correct BEFORE any diet change?', '{"options": ["tissue transglutaminase IgA with a total IgA level, on a gluten-containing diet", "tTG IgG alone, sufficient in all cases", "HLA typing first for everyone", "Start a gluten-free diet and test if symptoms persist", "Anti-gliadin antibodies as the screening test of choice"]}', '{"answers": [0]}', 'Screen with tTG-IgA plus total IgA (to detect IgA deficiency causing false negatives), while still eating gluten; diagnosis in adults is confirmed by duodenal biopsy. Anti-gliadin antibodies are obsolete for screening.', 'Test on gluten; a gluten-free diet before testing erases the diagnosis.', 'Empirical gluten-free trial in a first-degree relative - losing the diagnostic window.'),
(47, 'AKT', 'Hepatitis B', 'Gastrointestinal health', 'A 35-year-old man from a high-prevalence country has a positive HBsAg on screening. LFTs are normal. What is the MOST appropriate management?', '{"options": ["Refer for specialist assessment, screen and vaccinate household and sexual contacts, and monitor regularly", "Reassure that a positive surface antigen means past resolved infection", "Start entecavir immediately in all cases", "No follow-up needed while LFTs remain normal", "Isolate him from family meals"]}', '{"answers": [0]}', 'HBsAg positivity indicates chronic infection requiring specialist-linked surveillance (cirrhosis/HCC) and contact management (screening and vaccination of household/sexual contacts). Normal LFTs do not exclude active disease.', 'HBsAg positive = chronic infection until proven otherwise; protect the family.', 'Confusing surface antigen (chronic) with surface antibody (immune).'),
(48, 'AKT', 'Hepatitis C', 'Gastrointestinal health', 'A 46-year-old man with a history of injecting drug use has a positive hepatitis C antibody and detectable RNA. He asks about treatment. What is the MOST appropriate advice?', '{"options": ["Direct-acting antiviral therapy cures over 95% of patients and is PBS-subsidised; assess fibrosis and treat", "Interferon-based therapy remains the standard", "Treatment is only for cirrhosis", "He must abstain from alcohol for 5 years before treatment is permitted", "No treatment exists; monitor LFTs yearly"]}', '{"answers": [0]}', 'All HCV patients should be considered for curative DAAs (>95% sustained virological response, PBS-listed), with fibrosis assessment (and vaccination for hep A/B) beforehand. Injecting-drug history is not an exclusion.', 'Hepatitis C is a curable disease - test, link, treat.', 'Old interferon-era beliefs denying treatment to people who use drugs.'),
(49, 'AKT', 'Bowel cancer screening', 'Gastrointestinal health', 'A 61-year-old asymptomatic man returns a positive National Bowel Cancer Screening Program iFOBT. What is the MOST appropriate next step?', '{"options": ["Refer for colonoscopy", "Repeat the iFOBT in 3 months", "Start a trial of dietary modification", "Faecal occult blood testing on three consecutive days to confirm", "CT abdomen as a less invasive alternative"]}', '{"answers": [0]}', 'A positive iFOBT in the screening program mandates colonoscopy - do not repeat the test or substitute imaging. This is the diagnostic step of the program.', 'Positive FOBT = scope, not re-test.', 'Serial FOBTs delaying a cancer diagnosis.'),
(50, 'AKT', 'Iron deficiency anaemia', 'Gastrointestinal health', 'A 63-year-old man has Hb 102 with ferritin 8 and microcytosis, no obvious blood loss. Colonoscopy and gastroscopy are planned. What is the MOST appropriate iron therapy advice once workup is underway?', '{"options": ["Oral iron continued for 3 months after haemoglobin normalises to replenish stores", "Stop iron once Hb reaches the reference range", "IV iron routinely before endoscopy", "Oral iron only if ferritin remains low after Hb normalises", "No iron needed - treat the cause only"]}', '{"answers": [0]}', 'Treat the cause (bidirectional endoscopy in men/postmenopausal women with IDA) AND replace iron; continue oral iron ~3 months beyond Hb normalisation to replete stores. IV iron if intolerant or severe.', 'Haemoglobin normalised is not iron repleted - keep going 3 months.', 'Stopping at normal Hb, guaranteeing early relapse.');
INSERT OR IGNORE INTO questions (id, type, topic, unit, stem, options, answers, explanation, pearl, trap) VALUES
(51, 'AKT', 'Dysphagia', 'Gastrointestinal health', 'A 66-year-old man has 4 months of progressive dysphagia, first to solids then liquids, with 8 kg weight loss. What is the MOST appropriate action?', '{"options": ["Urgent endoscopy", "Oesophageal manometry", "Trial of a proton-pump inhibitor for 8 weeks", "Barium swallow as the definitive test", "Speech pathology assessment for swallowing therapy"]}', '{"answers": [0]}', 'Progressive dysphagia with weight loss in an older patient is oesophageal cancer until proven otherwise; urgent endoscopy (with biopsy). Manometry is for motility disorders once structural disease is excluded.', 'Progressive + weight loss = scope.', 'PPI trials for an alarm symptom.'),
(52, 'AKT', 'Diverticulitis', 'Gastrointestinal health', 'A 54-year-old woman has left iliac fossa pain, fever 38.2, and tenderness without peritonism. WCC 16, CRP 90. CT shows uncomplicated acute diverticulitis. She is tolerating fluids. What is the MOST appropriate management?', '{"options": ["Oral amoxycillin-clavulanate with clear fluids and early review, ED if worsening", "Oral metronidazole alone", "Hospital admission with IV antibiotics for all diverticulitis", "No antibiotics - resolution is typically uncomplicated without them", "Colonoscopy this week"]}', '{"answers": [0]}', 'Uncomplicated diverticulitis in a systemically unwell patient is treated with oral broad-spectrum antibiotics (amoxycillin-clavulanate per eTG), fluid, and safety-netting; complicated disease (peritonism, abscess, obstruction, sepsis) goes to ED. Colonoscopy follows later to exclude missed neoplasia.', 'Simple diverticulitis: oral antibiotics + early review; reserve ED for complications.', 'Missing peritonism or free air that changes everything.'),
(53, 'AKT', 'Migraine', 'Neurological presentations', 'A 38-year-old woman has migraines on 10 days per month affecting work, with depression and poor sleep. Which prophylactic agent best fits her profile?', '{"options": ["Amitriptyline at night", "Propranolol", "Verapamil", "Pizotifen", "Codeine-based analgesia nightly"]}', '{"answers": [0]}', 'At 10 headache days/month, prophylaxis is indicated. Amitriptyline addresses migraine, insomnia and coexisting depression. Choice is comorbidity-tailored; avoid nightly codeine which guarantees medication-overuse headache.', 'Prophylaxis at ≥4 migraine days/month; pick the drug that treats a second condition.', 'Nightly opioids - the highway to medication-overuse headache.'),
(54, 'AKT', 'TIA', 'Neurological presentations', 'A 70-year-old man describes 20 minutes of left arm weakness and slurred speech yesterday that fully resolved. He feels well today. What is the MOST appropriate action?', '{"options": ["Urgent same-day assessment (stroke/TIA clinic or ED)", "Routine appointment next week", "Reassure as symptoms resolved", "CT brain as an outpatient sometime in the next month", "Start aspirin and review in 3 months"]}', '{"answers": [0]}', 'TIA carries up to ~10% early stroke risk, highest in the first days: Australian guidance is same-day assessment (ED or rapid-access TIA clinic) for workup and secondary prevention, not watchful waiting.', 'Resolved deficit does not mean resolved risk - same-day workup.', 'Waiting days for a scan and aspirin.'),
(55, 'AKT', 'Epilepsy and driving', 'Neurological presentations', 'A 25-year-old man had a first unprovoked seizure yesterday. He asks about driving. What is the MOST appropriate advice?', '{"options": ["Do not drive now; report per the licensing authority''s medical reporting process and Austroads guidelines, with return to driving only once the seizure-free requirement is met", "He may drive as long as someone accompanies him", "Driving is fine because the seizure was a one-off", "A one-week break from driving is sufficient", "No restrictions apply to the first seizure"]}', '{"answers": [0]}', 'After an unprovoked seizure, driving must cease and the licensing process (with its seizure-free interval requirement) applies; the GP''s job is to counsel clearly, document, and fulfil reporting obligations per Austroads and state rules.', 'First seizure = no driving; notify and document the advice.', 'Soft-pedalling the driving conversation - it is a legal and safety duty.'),
(56, 'AKT', 'Dementia', 'Neurological presentations', 'A 74-year-old woman has 18 months of worsening memory reported by her daughter. Which workup approach is MOST appropriate at first presentation?', '{"options": ["Cognitive testing, reversible-cause screen (B12, TSH, FBE, UEC, LFT, calcium), and structural imaging where atypical or onset under 65 years", "CT brain for every patient before any bloods", "Diagnosis on MMSE score alone without bloods", "No workup - dementia is untreatable", "Neuropsychology testing before any other step"]}', '{"answers": [0]}', 'Dementia workup: confirm cognitive impairment (validated screen + collateral), exclude reversible contributors (B12, thyroid, metabolic), and image when presentation is atypical, early-onset or focal signs exist.', 'Always exclude the reversible B12 and thyroid mimics.', 'Skipping bloods - the occasional treatable dementia.'),
(57, 'AKT', 'Movement disorders', 'Neurological presentations', 'A 55-year-old man has a long-standing bilateral hand tremor worse when holding his coffee, a positive family history, and reduced tremor with alcohol. Examination otherwise normal. What is the MOST likely diagnosis?', '{"options": ["Essential tremor", "Parkinson disease", "Functional tremor", "Cerebellar disease", "Hyperthyroidism"]}', '{"answers": [0]}', 'Bilateral action (postural) tremor with family history and alcohol responsiveness typifies essential tremor. Parkinson''s tremor is rest tremor with bradykinesia/rigidity.', 'Action tremor + alcohol responsive + familial = essential.', 'Reading bilateral tremor as early Parkinson''s.'),
(58, 'AKT', 'Bell palsy', 'Neurological presentations', 'A 34-year-old woman has 2 days of unilateral facial droop with incomplete eye closure and no forehead sparing. Ear examination, neurology and BP are normal. What is the MOST appropriate management?', '{"options": ["Oral corticosteroids started now (within 72 hours of onset)", "Aciclovir alone", "No treatment - spontaneous recovery is the rule anyway", "CT facial bones", "Wait 72 hours to confirm it is not improving before steroids"]}', '{"answers": [0]}', 'Bell''s palsy (lower motor neurone facial weakness including forehead) is treated with early oral corticosteroids within 72 hours to improve recovery; antivirals add little in idiopathic cases (add if Ramsay Hunt/zoster). Eye protection is mandatory.', 'Forehead involvement = LMN = Bell''s; steroids early.', 'Waiting to see - the steroid window closes at 72 hours.'),
(59, 'AKT', 'Medication-overuse headache', 'Neurological presentations', 'A 45-year-old woman with migraines now has a daily dull headache; she takes codeine-combination analgesics 20 days per month. What is the MOST appropriate management?', '{"options": ["Withdraw the codeine analgesics with support and optimise migraine prophylaxis", "Increase the codeine dose", "Add a triptan daily", "Switch to oxycodone for cleaner pain control", "CT brain to exclude a new cause"]}', '{"answers": [0]}', 'Analgesic use ≥15 days/month for >3 months produces medication-overuse headache. Treatment is withdrawing the offending drug (with explanation, sometimes a bridging plan) and preventing migraines properly.', '≥15 analgesic days a month = the headache is the treatment.', 'Escalating opioids, imaging the consequence not the cause.'),
(60, 'AKT', 'VTE', 'Haematological presentations', 'A 49-year-old woman develops a proximal DVT 2 weeks after a knee arthroscopy. It is her first VTE. What is the MOST appropriate anticoagulation duration?', '{"options": ["3 months, then stop (provoked by transient surgery)", "Lifelong anticoagulation", "12 months", "Indefinite anticoagulation unless bleeding risk is high", "6 months"]}', '{"answers": [0]}', 'VTE provoked by a major transient surgical risk factor is anticoagulated for 3 months; longer durations are for unprovoked, recurrent, or persistent-risk VTE.', 'Provoked by surgery: 3 months and out.', 'Indefinite therapy for a clearly provoked event.'),
(61, 'AKT', 'VTE', 'Haematological presentations', 'A 58-year-old man has an unprovoked proximal DVT with no bleeding risk factors. What is the MOST appropriate approach to anticoagulation?', '{"options": ["Anticoagulate for at least 3 months, then reassess the risk-benefit of continuing", "3 months then always stop", "Lifelong therapy without reassessment", "Anticoagulate only if a thrombophilia is identified", "No anticoagulation if he declines stockings"]}', '{"answers": [0]}', 'Unprovoked proximal VTE needs at least 3 months of anticoagulation followed by a documented reassessment (bleeding risk, patient preference, residual thrombosis/D-dimer where used) of continuing versus stopping.', 'Unprovoked VTE: 3 months minimum, then a deliberate decision.', 'Automatic stopping at 3 months without the reassessment conversation.'),
(62, 'AKT', 'Haematological malignancy', 'Haematological presentations', 'A routine blood test on a 70-year-old man shows WCC 62 with blasts on the film, Hb 92, platelets 40. He feels mildly tired but is afebrile. What is the MOST appropriate action?', '{"options": ["Same-day haematology referral/hospital assessment", "Repeat the FBE in 6 weeks", "Oral iron and review", "Antibiotics for presumed infection", "Reassure - mild symptoms only"]}', '{"answers": [0]}', 'Leucocytosis with circulating blasts is a haematological emergency presentation requiring same-day haematology; watchful waiting risks leukostasis, bleeding and infection.', 'Blasts on film = today, not tomorrow.', 'The well-looking patient defusing urgency.'),
(63, 'AKT', 'Iron therapy', 'Haematological presentations', 'A 35-year-old vegetarian woman with iron deficiency (Hb 88, ferritin 5) develops nausea and constipation on oral iron despite taking it with food and alternate-day dosing. What is the MOST appropriate next step?', '{"options": ["Intravenous iron infusion", "Continue oral iron indefinitely at the same dose", "Stop all iron and transfuse", "Iron injections daily", "Diet alone given her intolerance"]}', '{"answers": [0]}', 'With failed or intolerant oral iron (and significant deficiency), IV iron (e.g., ferric carboxymaltose) is appropriate and repletes rapidly. Transfusion is reserved for haemodynamic compromise.', 'Oral iron failing or intolerant = IV iron, not willpower.', 'Persisting for months with zero absorption or adherence.'),
(64, 'AKT', 'Thalassaemia', 'Haematological presentations', 'A 26-year-old woman of South-East Asian background has mild microcytosis (MCV 74) with normal haemoglobin and normal ferritin. What is the MOST likely explanation and next test?', '{"options": ["Thalassaemia trait - haemoglobin electrophoresis (HbA2)", "Iron deficiency - start iron", "Anaemia of chronic disease - investigate inflammation", "Lead toxicity", "No testing needed"]}', '{"answers": [0]}', 'Microcytosis with normal Hb and normal ferritin in a high-prevalence ethnicity suggests thalassaemia trait; confirm with haemoglobinopathy studies (raised HbA2 in beta trait). Iron is not indicated.', 'Low MCV + normal ferritin = think thalassaemia before iron.', 'Reflex iron therapy for every microcytosis.'),
(65, 'AKT', 'Osteoarthritis', 'Musculoskeletal presentations', 'A 68-year-old woman has knee osteoarthritis with pain on stairs. Exam shows crepitus and mild effusion; she is overweight. What is the MOST appropriate first-line management?', '{"options": ["Exercise, weight loss and paracetamol/topical NSAID", "Immediate knee replacement", "Long-term oral NSAIDs", "Opioids for chronic pain", "Glucosamine as evidence-based therapy"]}', '{"answers": [0]}', 'Core OA management: exercise (incl. quadriceps strengthening), weight loss, topical NSAIDs and paracetamol; oral NSAIDs add GI/CV risk; surgery after failure of conservative care.', 'Move it, lose it, rub it in - before you swallow anything.', 'Long-term oral NSAIDs in an older overweight patient.'),
(66, 'AKT', 'Gout', 'Musculoskeletal presentations', 'A 58-year-old man with recurrent gout has just had an acute flare in his first MTP joint while taking allopurinol 100 mg daily (started 6 weeks ago). What is the MOST appropriate action?', '{"options": ["Treat the flare (NSAID/colchicine/steroid) and continue allopurinol at the same dose", "Stop allopurinol during the flare and restart after", "Increase allopurinol to 300 mg during the flare", "Cease allopurinol permanently - it is causing flares", "Add a uricosuric agent during the flare"]}', '{"answers": [0]}', 'Flares during initiation are expected: treat the acute attack, continue allopurinol (do not stop), titrate later to urate target, and use prophylaxis for 6 months.', 'Do not stop ULT for a flare - ride it out with flare therapy.', 'Stopping the ULT resets the titration clock and guarantees more flares.'),
(67, 'AKT', 'Rheumatoid arthritis', 'Musculoskeletal presentations', 'A 45-year-old woman has 8 weeks of symmetrical small-joint pain and stiffness lasting 90 minutes. What is the MOST appropriate management?', '{"options": ["Prompt referral for early rheumatology assessment (DMARDs within weeks)", "Trial of NSAIDs and review in 6 months", "Await X-ray changes before referring", "Long-term physiotherapy alone", "Serology first, and refer only if both RF and anti-CCP are positive"]}', '{"answers": [0]}', 'Suspected early RA: urgent rheumatology referral for DMARD initiation (window of opportunity); X-ray changes are late; seronegative RA exists.', 'Refer clinically - early DMARDs prevent deformity.', 'Waiting for erosions on X-ray.'),
(68, 'AKT', ' polymyalgia rheumatica', 'Musculoskeletal presentations', 'A 72-year-old woman has 4 weeks of shoulder and pelvic girdle stiffness, worse in the morning, with an ESR of 62. What is the MOST appropriate initial therapy?', '{"options": ["Prednisolone ~15 mg daily with rapid symptom response expected within days", "NSAIDs first-line", "Paracetamol and physiotherapy", "Methotrexate first-line", "Prednisolone 60 mg daily"]}', '{"answers": [0]}', 'PMR responds dramatically to low-dose prednisolone (10-20 mg) within days; 60 mg suggests GCA dosing; NSAIDs are ineffective.', 'A rapid dramatic response is itself diagnostic support.', 'Giant-cell arteritis dosing for pure PMR.'),
(69, 'AKT', 'Giant cell arteritis', 'Musculoskeletal presentations', 'A 74-year-old woman with PMR develops a new temporal headache, jaw claudication and blurred vision. What is the MOST appropriate immediate action?', '{"options": ["Start high-dose oral corticosteroids immediately and arrange same-day ophthalmology", "Arrange temporal artery biopsy before any treatment", "Book an outpatient neurology appointment", "Reassure - PMR headaches are common", "CT head first, steroids only if positive"]}', '{"answers": [0]}', 'Suspected GCA with visual symptoms: immediate high-dose steroids BEFORE any investigation - biopsy can follow (weeks later and still valid); delay risks permanent blindness.', 'Steroids now, biopsy later.', 'Waiting for biopsy confirmation while the sight is lost.'),
(70, 'AKT', 'Rotator cuff', 'Musculoskeletal presentations', 'A 55-year-old man has 3 months of shoulder pain, painful arc, and weakness of abduction against resistance. What is the MOST appropriate initial management?', '{"options": ["Analgesia and a structured rotator-cuff exercise program (physiotherapy)", "Immediate surgical referral", "Cortisone injection as first step for everyone", "Long-term oral steroids", "MRI before any treatment"]}', '{"answers": [0]}', 'Most rotator cuff pathology responds to a structured exercise program; imaging/injections are selected later, surgery after failed conservative care.', 'Rehab before referral; injection is not the default.', 'MRI-first thinking for a mechanical problem that needs exercise.'),
(71, 'AKT', 'Ankle injury', 'Musculoskeletal presentations', 'A 22-year-old man inverts his ankle playing football. He can bear weight immediately and there is tenderness only over the lateral malleolus with no bone tenderness at the posterior edge or tips. What is the MOST appropriate management?', '{"options": ["RICE and early mobilisation; no X-ray required by Ottawa rules", "X-ray regardless of the rules", "CT ankle", "Immobilisation in a cast for 6 weeks", "Immediate orthopaedic referral"]}', '{"answers": [0]}', 'Ottawa ankle rules: X-ray only if bone tenderness at malleolar tips/posterior edge, or inability to bear weight 4 steps. Otherwise functional management.', 'The rules exist so you do not radiograph every sprain.', 'Reflex X-rays for every twisted ankle.'),
(72, 'AKT', 'Osteoporosis treatment', 'Musculoskeletal presentations', 'A 68-year-old woman on alendronate for 5 years asks how long she must continue. DEXA today: T-score -2.6, no fractures since treatment. What is the MOST appropriate advice?', '{"options": ["Review at 5 years: consider a drug holiday only if fracture risk is now low, otherwise continue", "Stop immediately - 5 years always cures it", "Continue for life without review in every case", "Switch to calcium alone", "Repeat DEXA annually for life"]}', '{"answers": [0]}', 'At 5 years on a bisphosphonate, reassess fracture risk: low-risk patients may take a drug holiday with monitoring; higher-risk patients continue (or switch agents).', 'Five years: re-check risk before renewing the prescription.', 'Automatic lifelong therapy without reassessment.'),
(73, 'AKT', 'Scabies', 'Dermatological presentations', 'A family of four has intense night-time itch with burrows in the finger webs; the 6-month-old baby has palm involvement. What is the MOST appropriate management?', '{"options": ["Permethrin 5% for all members and close contacts simultaneously, with laundering of bedding and clothing", "Treat only symptomatic people", "Topical steroids alone", "Oral antibiotics for all", "Isolate the baby until clear"]}', '{"answers": [0]}', 'Scabies: treat all household/close contacts simultaneously (even asymptomatic - incubation means they carry it), plus hot-wash linens; permethrin is first-line including infants at appropriate dosing intervals.', 'Treat the household the same day, not just the itchy ones.', 'Treating only the index case - instant reinfestation.'),
(74, 'AKT', 'Melanoma', 'Dermatological presentations', 'A 40-year-old man presents with a 7 mm irregular pigmented lesion on his back with varied colours and recent change in size over 3 months. What is the MOST appropriate management?', '{"options": ["Excision biopsy with a 2 mm margin and dermoscopic/histological assessment", "Shave biopsy", "Photograph and review in 6 months", "Cryotherapy", "Topical imiquimod"]}', '{"answers": [0]}', 'Any lesion suspicious for melanoma needs complete excisional biopsy (2 mm clinical margin) - partial sampling (shave) compromises staging; cryotherapy and imiquimod are never for possible melanoma.', 'Cut it out whole - never shave a possible melanoma.', 'Watching a changing pigmented lesion for 6 months.'),
(75, 'AKT', 'Eczema', 'Dermatological presentations', 'A 6-month-old infant has widespread flexural eczema affecting sleep. Parents use emollient twice weekly and fear steroid creams. What is the MOST appropriate advice?', '{"options": ["Daily thick emollients plus an appropriate-strength topical corticosteroid for flares, with explanation that steroids used correctly are safe", "Avoid all steroids - they thin skin permanently", "Oral antihistamines cure eczema", "Bathing avoidance", "Antibiotics for the whole family"]}', '{"answers": [0]}', 'Eczema: liberal daily emollients + adequately strong topical steroids for flares (undertreatment is the main problem); address steroid phobia directly with education.', 'Under-treating with steroid phobia causes more harm than steroids ever will.', 'Homeopathic-strength steroid use for a severe flare.'),
(76, 'AKT', 'Psoriasis', 'Dermatological presentations', 'A 35-year-old man has chronic plaques on elbows and scalp; nail pitting is present. Topical steroids give partial relief. What is the MOST appropriate next step?', '{"options": ["Add a vitamin-D analogue (calcipotriol) in combination with the steroid, and review", "Start methotrexate immediately", "Systemic steroids to clear it", "Long-term oral antibiotics", "UV therapy at a solarium"]}', '{"answers": [0]}', 'First-line for chronic plaque psoriasis: combination topical steroid + calcipotriol; systemic therapy is for severe/refractory disease; solarium is never therapy.', 'Steroid + vitamin D analogue beats either alone.', 'Systemic steroids causing rebound pustular psoriasis.'),
(77, 'AKT', 'Acne', 'Dermatological presentations', 'An 18-year-old woman has moderate papulopustular acne with some nodules, unresponsive to 3 months of topical benzoyl peroxide. She is on a levonorgestrel pill. What is the MOST appropriate next step?', '{"options": ["Add a topical retinoid and consider switching to an anti-androgenic pill; isotretinoin if severe/refractory", "Immediate isotretinoin", "Long-term oral flucloxacillin", "Topical hydrocortisone", "No treatment - she will grow out of it"]}', '{"answers": [0]}', 'Moderate acne failing topical monotherapy: combination topical (retinoid + BPO ± antibiotic) and hormonal options (switching OCP); isotretinoin reserved for severe or refractory disease.', 'Step up combinations before escalating to isotretinoin.', 'Antibiotics for acne as a solo long-term strategy.'),
(78, 'AKT', 'Red eye', 'Eye presentations', 'A 25-year-old contact-lens wearer has 2 days of a painful red right eye with photophobia and tearing; vision is slightly reduced. He sleeps in his lenses. What is the MOST appropriate action?', '{"options": ["Same-day ophthalmology assessment - contact-lens-related keratitis", "Topical antibiotic from the chemist and review tomorrow", "Eye patch and review next week", "Oral antibiotics", "Stop the lenses and observe for a week"]}', '{"answers": [0]}', 'Pain + photophobia + reduced vision + contact lens wear = microbial keratitis until proven otherwise: same-day ophthalmology (scraping/cultures, intensive drops). Delay can mean perforation.', 'Contact lens + painful red eye = cornea, same day.', 'Chemist chloramphenicol for a sight-threatening keratitis.'),
(79, 'AKT', 'Acute angle-closure glaucoma', 'Eye presentations', 'A 66-year-old woman has 6 hours of severe right eye pain, haloes around lights, vomiting, a hazy cornea and a mid-dilated fixed pupil. What is the MOST appropriate action?', '{"options": ["Immediate emergency ophthalmology referral", "Oral paracetamol and review tomorrow", "Topical chloramphenicol", "CT brain", "Miotic drops then wait a week"]}', '{"answers": [0]}', 'Acute angle closure is an ophthalmic emergency (permanent visual loss within days): emergency referral for medical therapy (drops, acetazolamide) and laser iridotomy.', 'Painful red eye + haloes + vomiting = angle closure, today.', 'Mistaking it for migraine or gastroenteritis.'),
(80, 'AKT', 'Retinal detachment', 'Eye presentations', 'A 55-year-old myopic man describes a sudden shower of floaters then a ''curtain'' over the left visual field. What is the MOST appropriate action?', '{"options": ["Same-day ophthalmology assessment", "Routine optometry review in 2 weeks", "Reassurance - floaters are benign", "CT head", "Oral NSAIDs and bed rest at home"]}', '{"answers": [0]}', 'New floater shower + curtain field loss = retinal detachment: same-day assessment. Days matter for macular involvement.', 'A curtain over the vision is an emergency, not a floater.', 'Watchful waiting for acute PVD features.'),
(81, 'AKT', 'Otitis media', 'Ear, nose, throat and oral health', 'A 2-year-old has 48 hours of bilateral ear pain, fever 38.5, and both drums are red and bulging. She is distressed but systemically well. What is the MOST appropriate management?', '{"options": ["Analgesia plus a wait-and-watch approach with a safety-net prescription or review in 48 hours", "Immediate antibiotics in every case", "Amoxicillin for 10 days always", "Grommets", "Antihistamines and decongestants"]}', '{"answers": [0]}', 'Most AOM in children over 6 months is viral or self-limiting: analgesia-first with deferred antibiotics (delayed script/review), reserving immediate antibiotics for systemically unwell children, under-6-months, or specific contexts.', 'Analgesia first; antibiotics on a short leash.', 'Antibiotics reflexively for every red drum.'),
(82, 'AKT', 'Otitis externa', 'Ear, nose, throat and oral health', 'A 32-year-old swimmer has 3 days of an itchy, painful ear canal with debris and pain on touching the tragus; the drum is normal. What is the MOST appropriate management?', '{"options": ["Topical antibiotic-steroid drops (aural toilet if the canal permits)", "Oral amoxycillin", "Ear candling", "Dry mopping alone", "Systemic antifungal"]}', '{"answers": [0]}', 'Otitis externa: topical combination drops (antibiotic + steroid) ± aural toilet; keep the ear dry; oral antibiotics only for cellulitis/immunosuppression.', 'Topical therapy for a topical disease.', 'Oral antibiotics as first-line (and resistance).'),
(83, 'AKT', 'Epistaxis', 'Ear, nose, throat and oral health', 'A 58-year-old man on aspirin has an anterior nosebleed for 15 minutes. He is haemodynamically stable. What is the FIRST step?', '{"options": ["Sit him upright, lean forward, and apply continuous firm pressure to the soft nasal cartilage for 10-20 minutes", "Pack with ribbon gauze immediately", "Lie him down with head back", "Ice to the neck", "Cauterise at once"]}', '{"answers": [0]}', 'First aid first: upright, lean forward, pinch the soft part (Little''s area) without interruption for 10-20 minutes; then assess (and cautery if a visible vessel once bleeding controlled).', 'Pressure before packing; leaning forward not back.', 'Tipping the head back - blood swallowed, airway risk.'),
(84, 'AKT', 'Meningitis', 'Child and youth health', 'A 19-year-old has 12 hours of fever, severe headache, neck stiffness and a new petechial rash. What is the MOST appropriate action?', '{"options": ["Call 000 for immediate hospital transfer", "Oral antibiotics at home then review in 4 hours", "Lumbar puncture at the practice", "Antihistamine for the rash", "Analgesia and review tomorrow"]}', '{"answers": [0]}', 'Fever + meningism + petechiae = meningococcal disease: emergency transfer. In the community, give IV/IM antibiotics (per state guidance, e.g., ceftriaxone) before transfer if it will not delay it.', 'Petechiae plus meningism: ambulance, antibiotics, now.', 'Waiting in a waiting room queue.'),
(85, 'AKT', 'Kawasaki disease', 'Child and youth health', 'A 3-year-old has 6 days of fever despite amoxicillin, red eyes without discharge, cracked red lips, swollen hands, and a unilateral neck node. What is the MOST appropriate action?', '{"options": ["Urgent referral for IV immunoglobulin within 10 days of illness onset", "Continue antibiotics for a further week", "Reassure - viral illness will settle", "Oral steroids", "Antihistamines for the rash"]}', '{"answers": [0]}', 'Fever ≥5 days plus mucositis, conjunctival injection, extremity changes and lymphadenopathy = Kawasaki disease: urgent referral for IVIG (before day 10 to prevent coronary aneurysms).', 'Fever five days plus red everything: think Kawasaki, refer today.', 'A second antibiotic course for a non-bacterial illness.'),
(86, 'AKT', 'Bronchiolitis', 'Child and youth health', 'A 7-month-old has coryza, then 3 days of cough, mild recession and poor feeding. SpO2 94% in air, no apnoea, feeding about 60% of normal. What is the MOST appropriate management?', '{"options": ["Supportive care at home with clear safety-netting", "Admit for bronchodilators", "Oral prednisolone", "Chest X-ray", "Antibiotics"]}', '{"answers": [0]}', 'Bronchiolitis: supportive care; bronchodilators, steroids, antibiotics and CXR are NOT routine. Home care is appropriate if feeding ≥50%, SpO2 adequate and parents confident.', 'Feed them, watch them, bring them back if worse - but no drugs.', 'Salbutamol for a viral infant wheeze.'),
(87, 'AKT', 'UTI in children', 'Child and youth health', 'A 4-year-old girl has dysuria and frequency; a clean-catch urine shows leucocytes and nitrites. She is afebrile and well. What is the MOST appropriate management?', '{"options": ["Treat as a lower UTI (e.g., trimethoprim per local resistance) and arrange a follow-up sample; no routine imaging for a single uncomplicated infection", "Oral antibiotics for 2 weeks", "Immediate renal ultrasound", "Refer to nephrology", "Fluids only, no antibiotics"]}', '{"answers": [0]}', 'Afebrile well child with lower UTI: short-course antibiotics and a follow-up test of cure; imaging is for atypical/recurrent infections or infants.', 'Treat, confirm clearance, image only when the story is not simple.', 'Automatic ultrasound for every first UTI.'),
(88, 'AKT', 'Nocturnal enuresis', 'Child and youth health', 'A 7-year-old still wets the bed most nights, by day he is dry and otherwise well. What is the MOST appropriate first-line management?', '{"options": ["Bedwetting alarm with family support", "Desmopressin first-line", "Fluid restriction all day", "Punishment chart", "Referral to urology"]}', '{"answers": [0]}', 'First-line for uncomplicated nocturnal enuresis (≥7 years): alarm therapy with parental engagement; desmopressin when alarms fail or rapid/short-term control is needed.', 'Alarms first; drugs are the backup.', 'Fluid restriction to the point of dehydration.'),
(89, 'AKT', 'ADHD', 'Child and youth health', 'An 8-year-old boy has pervasive inattention and impulsivity at home AND school for over a year, impairing learning and friendships. What is the MOST appropriate pathway?', '{"options": ["Referral for comprehensive assessment (paediatrics/psychology) using multiple informants", "Start stimulants at the practice", "Diagnose on teacher report alone", "EEG", "Diet elimination trial first"]}', '{"answers": [0]}', 'ADHD requires comprehensive multi-informant assessment (home + school tools, exclusion of mimics) through specialist services before treatment; GPs coordinate and support but assessment comes first.', 'Two settings, two informants, one thorough assessment.', 'Stimulants on a single teacher''s note.'),
(90, 'AKT', 'Depression in the elderly', 'Older persons'' health', 'An 81-year-old man has 6 months of low mood, poor sleep, and reduced function after his wife died. He scored 21/30 on a cognitive screen last week. What is the MOST important next step?', '{"options": ["Distinguish depression from dementia (including pseudodementia) with collateral history and treat depression (psychotherapy/SSRI as appropriate)", "Diagnose dementia and start donepezil", "Reassure - normal ageing", "Benzodiazepine for sleep", "CT brain and cerebrolysin"]}', '{"answers": [0]}', 'Depression in older people often mimics dementia (pseudodementia): collateral history, depression-focused treatment and monitoring cognition over time - it frequently improves with mood treatment.', 'Depressed cognition can look demented - treat the mood and re-test.', 'Locking in a dementia label during bereavement depression.'),
(91, 'AKT', 'Falls prevention', 'Older persons'' health', 'An 85-year-old woman has had 3 falls in 6 months. She takes ramipril, amlodipine, temazepam and doxazosin; lying BP 142/80, standing 110/68 with dizziness. What is the MOST appropriate intervention?', '{"options": ["Deprescribe the temazepam and doxazosin, review antihypertensives, add strength-balance exercise and vision check", "Start a beta-blocker for safety", "Increase antihypertensives", "Walking frame only", "Fear of falling is protective - discourage activity"]}', '{"answers": [0]}', 'Falls: review culprit sedatives/vasodilators FIRST, then exercise (balance/strength), vision, footwear, home hazards; vitamin D if deficient. Avoid over-treating BP in the frail.', 'Stop the drugs that drop her before she drops.', 'Bed rest and further deconditioning.'),
(92, 'AKT', 'Delirium', 'Older persons'' health', 'A family calls about their 84-year-old father in a residential facility: overnight he became acutely confused and agitated. Last week he had a UTI treated. What is the MOST appropriate initial approach?', '{"options": ["Assess for acute causes (infection, drugs, retention, hypoxia, metabolic), manage environment, treat the cause", "Start an antipsychotic immediately and move on", "Diagnose dementia and update the family", "Sedate with benzodiazepine", "Discharge to hospital automatically"]}', '{"answers": [0]}', 'Delirium = acute fluctuating confusion: look hard for the driver (infection, drugs esp. anticholinergics, retention, hypoxia, electrolytes) and use non-pharmacologic management first; antipsychotics only if danger/distress.', 'Confusion that changed overnight is delirium until proven otherwise.', 'Sedation before searching for the cause.'),
(93, 'AKT', 'Elder abuse', 'Older persons'' health', 'An 80-year-old man has repeat ''falls'' with explanations that change each time. His son insists on being present at every appointment and answers for him. Weight is down 4 kg. What is the MOST appropriate next step?', '{"options": ["See him alone, ask directly and sensitively about safety and mistreatment, and know your reporting options", "Accept the son''s explanation", "Confront the son in the room", "Document only and do nothing", "Order more CT scans for the falls"]}', '{"answers": [0]}', 'Red flags for elder abuse: changing explanations, caregiver controlling the consultation, weight loss, delay in care. See the patient alone, ask directly, document, and use state pathways (QLD: adult safeguarding/unit via Elder Abuse Helpline).', 'Get the controller out of the room and ask.', 'Confrontation in the room, endangering the patient.'),
(94, 'AKT', 'Polypharmacy', 'Older persons'' health', 'An 86-year-old woman takes 14 medications including two antihypertensives, an anticholinergic bladder drug, and nighttime temazepam. She is dizzy in the mornings and has had one fall. What is the MOST appropriate approach?', '{"options": ["Structured deprescribing review prioritising fall-risk drugs (sedatives, vasodilators, anticholinergics)", "Continue all - stopping medications is risky", "Add a drug for the dizziness", "Stop everything at once", "Refer to pharmacy only"]}', '{"answers": [0]}', 'Multimorbidity guidelines: prioritise harms over marginal benefits in the frail old; stepwise deprescribing of fall-risk drugs with monitoring.', 'Every new symptom in the elderly is a drug side-effect until proven otherwise.', 'Prescribing for drug-induced illness with another drug.'),
(95, 'AKT', 'Advance care planning', 'Palliative care', 'A 78-year-old man with severe COPD attends with his daughter. He asks about future care planning while well. What is the MOST appropriate approach?', '{"options": ["Facilitate advance care planning discussion: goals, surrogate decision-maker, documented plan and limits of treatment", "Refer to palliative care immediately", "Tell him it is too early to discuss", "Start the forms without conversation", "Focus purely on resuscitation status"]}', '{"answers": [0]}', 'ACP early in chronic serious illness: explore values, appoint a substitute decision-maker (QLD: enduring power of attorney / statutory health attorney), document, share with the team.', 'Plan while stable, not in the crisis.', 'Reducing ACP to a CPR tick-box.'),
(96, 'AKT', 'Breakthrough pain', 'Palliative care', 'A terminally ill patient on 60 mg oral morphine daily has 2-3 breakthrough pain episodes daily. What is the appropriate breakthrough dose?', '{"options": ["Approximately 10-15 mg oral morphine (about 1/6 of the total daily dose)", "60 mg - the same as the daily dose", "5 mg subcutaneous", "Panadeine Forte", "No analgesia - avoid addiction near death"]}', '{"answers": [0]}', 'Breakthrough opioid = about 1/6 of the TOTAL daily dose, adjusted by response. Undertreatment of terminal pain is the greater harm; addiction is not a palliative end-stage concern.', 'One-sixth of the daily dose, every breakthrough.', 'Same-as-daily dosing causing overdose.'),
(97, 'AKT', 'VAD eligibility', 'Palliative care', 'In Queensland, which of the following is required for voluntary assisted dying eligibility?', '{"options": ["Adult Queensland resident with decision-making capacity, intolerable suffering from an advanced progressive condition, and the statutory request process completed", "Any adult with chronic pain wanting to die", "Terminal prognosis under 6 months only", "Diagnosis of cancer only", "Family request on the patient''s behalf"]}', '{"answers": [0]}', 'QLD VAD (since 2023): adult, resident, capacity, suffering intolerably from a qualifying advanced/progressive condition expected to cause death, undergoing the formal request/assessment process with coordinating and independent practitioners.', 'Capacity is a VAD prerequisite throughout the process.', 'Family-initiated requests or losing capacity and still proceeding.'),
(98, 'AKT', 'Alcohol withdrawal', 'Addiction medicine', 'A dependent drinker (100 g/day) is admitted for an unrelated surgery; withdrawal risk is high. What is the MOST appropriate management?', '{"options": ["A benzodiazepine withdrawal regimen (e.g., diazepam per CIWA-Ar) plus thiamine BEFORE any glucose", "Naltrexone immediately", "Chlordiazepoxide with glucose first", "Observation only", "Disulfiram in hospital"]}', '{"answers": [0]}', 'Prevent withdrawal: symptom-triggered benzodiazepines (CIWA-Ar), thiamine BEFORE any glucose-containing fluids, monitor electrolytes; naltrexone/disulfiram are relapse-prevention, not withdrawal drugs.', 'Thiamine before toast, tea or TPN.', 'Glucose before thiamine precipitating Wernicke encephalopathy.'),
(99, 'AKT', 'Smoking cessation', 'Addiction medicine', 'A 50-year-old smoker with COPD wants to quit next month. What is the MOST effective pharmacotherapy approach?', '{"options": ["Varenicline (or combination NRT) plus behavioural support with a quit date", "Nicotine patch alone at half dose", "E-cigarettes as the first-line recommendation", "Hypnotherapy", "Cutting down gradually without support"]}', '{"answers": [0]}', 'Behavioural support + pharmacotherapy doubles quit rates: varenicline most effective for many (or combination NRT patch + PRN); set a quit date and follow-up within a week.', 'Drugs + a date + follow-up - all three or it fizzles.', 'Vaping as a doctor-endorsed first-line stop-smoking medicine.'),
(100, 'AKT', 'Opioid dependence', 'Addiction medicine', 'A 30-year-old man with heroin dependence wants treatment. Which option is the FIRST-LINE maintenance therapy in Australia?', '{"options": ["Buprenorphine (or methadone) via an accredited prescriber, with psychosocial support", "Detoxification alone", "Naltrexone implants", "Benzodiazepines for craving", "Methadone from any GP without accreditation"]}', '{"answers": [0]}', 'Opioid agonist therapy (buprenorphine or methadone) with accredited prescribing and wraparound psychosocial care is the evidence-based maintenance approach; detox alone has high relapse and overdose risk.', 'Maintenance beats detox for staying alive.', 'Unsupported detox - fatal overdose risk post-discharge.');
INSERT OR IGNORE INTO questions (id, type, topic, unit, stem, options, answers, explanation, pearl, trap) VALUES
(101, 'AKT', 'Prostate cancer', 'Men''s health', 'A 68-year-old man asks about PSA testing. He is asymptomatic with no family history. What is the MOST appropriate advice?', '{"options": ["Offer an informed-choice discussion: PSA testing may detect cancer earlier but risks overdiagnosis and overtreatment; if testing, consent to the trade-offs first", "Refuse the test outright", "Test annually without discussion from 50 years", "Start PSA at 40 in all men", "PSA is a yes/no cancer test"]}', '{"answers": [0]}', 'PSA: no population screening programme; RACGP advises informed decision-making (benefits vs overdiagnosis/overtreatment harms) for men from 50 (45 with family history). Testing only after consent to the conversation.', 'Consent to the test includes consent to its consequences.', 'Reflexive annual PSA from 45 without any discussion.'),
(102, 'AKT', 'Erectile dysfunction', 'Men''s health', 'A 56-year-old man has 12 months of erectile dysfunction. He smokes and has borderline hypertension. What is the MOST appropriate initial evaluation?', '{"options": ["Cardiovascular risk assessment (ED is a marker of endothelial disease), plus focused exam, testosterone if libido low, then PDE5 inhibitor if suitable", "Straight to sildenafil without assessment", "Testosterone for everyone", "Penile implant", "Psychotherapy alone"]}', '{"answers": [0]}', 'ED is often the first sign of CVD: assess risk factors, screen for depression, check testosterone if low libido, then PDE5 inhibitors as first-line therapy with contraindication checks (nitrates).', 'The penis is a cardiovascular stress test.', 'Sildenafil without asking about nitrates or the heart.'),
(103, 'AKT', 'Testicular torsion', 'Men''s health', 'A 15-year-old has 3 hours of sudden severe right testicular pain with vomiting; the testis is high-lying and exquisitely tender. What is the MOST appropriate action?', '{"options": ["Immediate surgical referral (ED) - torsion is a time-critical emergency", "Ultrasound to confirm before referral", "Antibiotics for epididymo-orchitis", "Analgesia and review tomorrow", "Orchidectomy in the practice"]}', '{"answers": [0]}', 'Torsion: sudden pain + vomiting + high-riding testis = theatre within hours; imaging must not delay surgery (perfusion lost within 6-8 hours).', 'Suspected torsion: straight to theatre, no detours.', 'Waiting for an ultrasound while the testis dies.'),
(104, 'AKT', 'STI screening', 'Sexual health and gender diversity', 'A 22-year-old asymptomatic man who has sex with men requests a sexual health check. What is the MOST appropriate testing set (per Australian STI guidelines)?', '{"options": ["NAAT for chlamydia and gonorrhoea at relevant sites (urine/rectal/pharyngeal per exposure), HIV and syphilis serology", "Chlamydia urine only", "HIV only", "Full-body skin examination", "Hepatitis C PCR routinely"]}', '{"answers": [0]}', 'Asymptomatic MSM screen: site-specific NAATs for chlamydia/gonorrhoea (urine, pharyngeal, anal as exposure dictates), HIV serology (4th-gen), and syphilis serology, at least 6-12 monthly depending on risk.', 'Test the sites that were exposed - not just the urine.', 'Urine-only testing missing rectal and pharyngeal infection.'),
(105, 'AKT', 'Syphilis', 'Sexual health and gender diversity', 'A 30-year-old pregnant woman''s syphilis screen (EIA) is reactive. What is the MOST appropriate next step?', '{"options": ["Confirm with a second different serological test and treponemal-specific testing, and refer for treatment urgently - congenital syphilis risk", "Reassure as EIA often false positive", "Repeat the same EIA in 6 months", "Treat with a single doxycycline", "No treatment if she has no symptoms"]}', '{"answers": [0]}', 'Reactive screening syphilis: confirm with different assays (treponemal + non-treponemal e.g., RPR for activity) and treat promptly in pregnancy - congenital syphilis is rising in Australia and penicillin is the treatment.', 'Screen positive in pregnancy: confirm, stage, treat, fast.', 'Reassurance during a rising congenital syphilis era.'),
(106, 'AKT', 'Cellulitis', 'Infectious diseases', 'A 55-year-old woman has a 3-day spreading red hot swollen left calf, afebrile, no systemic upset, no portal visible. WCC normal. What is the MOST appropriate management?', '{"options": ["Flucloxacillin 500 mg qid for 5-7 days with clear escalation advice", "Amoxycillin-clavulanate for all cellulitis", "IV antibiotics in the practice", "Antifungal cream", "No antibiotics - it is erysipelas"]}', '{"answers": [0]}', 'Non-severe cellulitis without systemic features: oral flucloxacillin (anti-staphylococcal penicillin) with a defined review; escalate for rapid spread, systemic signs or failed therapy.', 'Red leg = flucloxacillin unless the story says otherwise.', 'Broad-spectrum co-amoxiclav as the reflex choice.'),
(107, 'AKT', 'Bites', 'Infectious diseases', 'A 30-year-old was bitten on the hand by a dog 2 hours ago; puncture wounds, no tendon/neuro compromise, wound cleaned. What is the MOST appropriate management?', '{"options": ["Amoxycillin-clavulanate prophylaxis, tetanus review, and wound care advice", "Flucloxacillin", "No antibiotics for all bites", "Metronidazole alone", "Suture the puncture wounds tightly"]}', '{"answers": [0]}', 'Animal bites (esp. hands): prophylaxis with amoxycillin-clavulanate (Pasteurella cover) plus tetanus check; puncture wounds are not closed primarily.', 'Hand bites get antibiotics; punctures stay open.', 'Primary closure of a puncture wound.'),
(108, 'AKT', 'Q fever', 'Infectious diseases', 'A 46-year-old abattoir worker in rural Queensland has 5 days of high fever, severe headache and myalgia with a mild dry cough. What is the MOST likely diagnosis to consider and the treatment?', '{"options": ["Q fever - doxycycline, and notify", "Influenza - oseltamivir", "Malaria", "Legionella", "Kawasaki disease"]}', '{"answers": [0]}', 'Q fever (Coxiella burnetii) in QLD: abattoir/farm exposure, fever + headache ± atypical pneumonia; treat with doxycycline; it is notifiable, and vaccination exists for at-risk workers.', 'QLD + abattoir + fever + headache = Q fever.', 'Missing the occupational history that makes the diagnosis.'),
(109, 'AKT', 'Malaria', 'Infectious diseases', 'A 28-year-old returns from Papua New Guinea with 2 days of high fever and rigors. What is the MOST appropriate action?', '{"options": ["Same-day hospital assessment with urgent malaria bloods (thick and thin films) - falciparum until excluded", "Start empirical doxycycline at home", "Reassure - it is a viral illness", "Repeat films next week if unwell", "Chloroquine at home"]}', '{"answers": [0]}', 'Fever in a returned traveller from a falciparum zone is a medical emergency: same-day films (or rapid antigen) and hospital-level management; falciparum malaria can kill within 48 hours.', 'Returned + fever = malaria today, not Tuesday.', 'Waiting for the third-day fever pattern.'),
(110, 'AKT', 'Tuberculosis', 'Infectious diseases', 'A 35-year-old arrived from the Philippines 3 months ago with 6 weeks of cough, night sweats and 5 kg weight loss. What is the MOST appropriate initial investigations?', '{"options": ["Chest X-ray and sputum (3 specimens) for AFB microscopy and culture, plus notify public health", "Serology for TB", "Trial of antibiotics", "CT abdomen", "Mantoux test alone"]}', '{"answers": [0]}', 'Suspected pulmonary TB: CXR + sputum for acid-fast bacilli (3 specimens) and cultures; TB is notifiable and public health manages contacts; serology is not a TB test.', 'Cough + weight loss + migration from a high-prevalence country = TB screen.', 'Empirical antibiotics erasing the diagnostic yield.'),
(111, 'AKT', 'Influenza vaccination', 'Infectious diseases', 'A 35-year-old at 30 weeks gestation asks about influenza vaccination. What is the MOST appropriate advice?', '{"options": ["Influenza vaccination is recommended and funded at any stage of pregnancy", "Wait until after delivery", "Contraindicated in the third trimester", "Only the partner needs vaccination", "Half dose only"]}', '{"answers": [0]}', 'Pregnant women are a funded priority group for influenza vaccination at any trimester (and pertussis from 20-32 weeks): maternal immunisation protects mother and neonate.', 'Pregnant = funded flu vaccine, any stage.', 'Deferring the vaccine to ''after the baby comes''.'),
(112, 'AKT', 'Pertussis vaccination', 'Infectious diseases', 'A woman at 28 weeks gestation asks about pertussis protection for the baby. What is the MOST appropriate advice?', '{"options": ["She should receive dTpa ideally between 20 and 32 weeks of every pregnancy", "Only the first pregnancy needs vaccination", "Wait until after birth", "The baby is protected by maternal antibodies alone until vaccination at 2 months", "Grandparents cannot be vaccinated"]}', '{"answers": [0]}', 'dTpa in every pregnancy at 20-32 weeks maximises placental antibody transfer; partners and household contacts are also recommended (cocooning).', 'Every pregnancy, 20-32 weeks, no exceptions.', 'One-time vaccination for a lifetime of pregnancies.'),
(113, 'AKT', 'Vaccine contraindications', 'Infectious diseases', 'Which of the following is a TRUE contraindication to a live attenuated vaccine (e.g., MMR)?', '{"options": ["Significant immunosuppression or pregnancy", "Mild coryza", "Current antibiotics", "Family history of adverse events", "Egg allergy (for MMR in modern practice)"]}', '{"answers": [0]}', 'Live vaccines (MMR, varicella, zoster live, yellow fever) are contraindicated in pregnancy and significant immunosuppression; minor illness, antibiotics, egg allergy (MMR) are not.', 'Live vaccine + immunosuppression or pregnancy = the real contraindication.', 'Deferring vaccination for a runny nose.'),
(114, 'AKT', 'Vaccine error', 'Infectious diseases', 'A nurse gives an MMR vaccine subcutaneously instead of intramuscularly. What is the MOST appropriate action?', '{"options": ["Record the error, report to the vaccination program/pharmacovigilance; the dose does NOT need repeating for route deviation alone", "Repeat the dose immediately", "Discard all records", "No documentation needed", "Referral to ED"]}', '{"answers": [0]}', 'Vaccine administration errors: document, report (state program), assess - most route errors are not repeated doses; the Australian Immunisation Handbook has a vaccine error table.', 'Document and report - do not reflexively re-vaccinate.', 'Silent errors that corrupt immunisation records.'),
(115, 'AKT', 'Immunisation catch-up', 'Infectious diseases', 'A 5-year-old newly arrived child has no documented vaccines. What is the MOST appropriate approach?', '{"options": ["Construct a catch-up schedule using the Handbook rules - valid doses count, spacing rules apply, and record all on the AIR", "Restart every vaccine course from zero", "One dose of everything today", "No catch-up needed if the child is well", "Serology for every antigen first"]}', '{"answers": [0]}', 'Catch-up: use documented doses where valid, apply minimum spacing/intervals per the Handbook, catch up the essential antigens promptly, and record everything on the AIR.', 'Documented doses count; spacing rules are the law of catch-up.', 'Restarting all courses - unnecessary over-vaccination.'),
(116, 'AKT', 'Aboriginal health checks', 'Aboriginal and Torres Strait Islander health', 'Which is TRUE about health checks for Aboriginal and Torres Strait Islander patients in general practice?', '{"options": ["An annual comprehensive health check (MBS 715) is recommended, with follow-up of identified issues", "Health checks are only for those over 50", "A referral letter is sufficient", "They must be done in hospital", "They cannot be done alongside other visits"]}', '{"answers": [0]}', 'ATSI adults and children are eligible for annual comprehensive health assessments (MBS item 715) covering chronic disease, CVD risk from younger ages, and preventive care.', 'Annual 715: the anchor of ATSI preventive care.', 'Once-only or age-gated checks.'),
(117, 'AKT', 'ATSI cardiovascular risk', 'Aboriginal and Torres Strait Islander health', 'At what age should absolute CVD risk assessment typically begin for Aboriginal and Torres Strait Islander patients?', '{"options": ["From 35 years (earlier than the general population''s 45)", "Only from 55", "At 45 like everyone else", "Only once diabetes develops", "CVD risk tools do not apply"]}', '{"answers": [0]}', 'CVD risk assessment starts from age 35 for Aboriginal and Torres Strait Islander adults (vs 45 general population) - part of a younger, high-priority prevention strategy.', 'Ten years earlier: 35 not 45.', 'Same-age screening missing a decade of prevention.'),
(118, 'AKT', 'ATSI prescribing', 'Aboriginal and Torres Strait Islander health', 'A patient with close-the-gap eligibility needs a medication usually outside her budget. What is the MOST appropriate approach?', '{"options": ["Check her CTG PBS entitlement so she receives the medicine with reduced or no co-payment", "Prescribe a cheaper, less effective alternative", "No medicines can be subsidised", "Refer to ED for the prescription", "Wait until hospital admission"]}', '{"answers": [0]}', 'Closing the Gap PBS co-payment arrangements give CTG-eligible patients access to most PBS medicines at reduced cost, supporting adherence and equity.', 'The right drug at the right price: CTG scripts exist - use them.', 'Therapeutic compromise for cost reasons.'),
(119, 'AKT', 'Anxiety disorders', 'Mental health', 'A 30-year-old has months of excessive worry, restlessness and sleep disturbance; she has been managing work but distress is growing. What is the MOST appropriate initial management?', '{"options": ["Guided CBT-based psychological therapy (low-intensity CBT first-line for GAD)", "Immediate long-term benzodiazepine", "Start an SSRI at maximal dose", "Antipsychotic", "Reassurance with no follow-up"]}', '{"answers": [0]}', 'GAD: stepped care - psychological therapy (e.g., CBT) is first-line; medication if psychological is insufficient or severe; benzodiazepines only very short-term if at all.', 'CBT before SSRI, SSRI before benzo.', 'Long-term benzodiazepines for worry - dependence within weeks.'),
(120, 'AKT', 'Bipolar disorder', 'Mental health', 'A 26-year-old presents with 5 days of reduced sleep, racing thoughts, big spending and grandiosity. What is the MOST appropriate action?', '{"options": ["Urgent mental health assessment - suspected mania (screen for bipolar before treating as depression)", "Start an antidepressant today", "Diagnose anxiety", "Sleep hygiene handout", "No action - youthful high spirits"]}', '{"answers": [0]}', 'Mania features (decreased need for sleep, grandiosity, spending) = urgent assessment; antidepressant monotherapy can flip mania. Diagnosis and mood-stabiliser decisions are specialist-led.', 'Sleepless + grandiose + spending: mana until proven otherwise; never an SSRI alone.', 'Antidepressants into an undiagnosed bipolar patient.'),
(121, 'AKT', 'Perinatal mental health', 'Mental health', 'At a 6-week postnatal check the EPDS is 15; the mother is tearful and the baby is well. What is the MOST appropriate management?', '{"options": ["Assess risk, engage supports, refer for perinatal mental health care (psychological therapy; medication if moderate-severe with informed choice)", "Reassure - baby blues only", "Delay all treatment until weaning", "Benzodiazepine for sleep", "Separate mother and baby"]}', '{"answers": [0]}', 'EPDS ≥13 (or clinical concern): assess severity/risk, involve partner/family, perinatal-specific psychological therapy; SSRIs with an individualised risk-benefit discussion when needed (several are compatible with breastfeeding).', 'Screen, then treat - postnatal depression is common, serious, treatable.', 'Writing it off as baby blues at 6 weeks.'),
(122, 'AKT', 'Psychosis', 'Mental health', 'A 21-year-old is brought in by family: 3 weeks of social withdrawal, odd beliefs, and hearing voices. What is the MOST appropriate action?', '{"options": ["Urgent mental health assessment (early psychosis pathway)", "Antidepressant trial", "Sleep study", "Benign observation for a year", "Antipsychotics started casually without assessment"]}', '{"answers": [0]}', 'First-episode psychosis: early assessment via a youth/early psychosis service improves outcomes; medication decisions belong with the assessing team.', 'Duration and function decline matter: refer early psychosis.', 'Writing it off as adolescence.'),
(123, 'AKT', 'Bulimia nervosa', 'Mental health', 'A 24-year-old has episodes of binge eating with self-induced vomiting twice weekly for 6 months, BMI 23. What is the MOST appropriate management?', '{"options": ["Guided CBT for eating disorders with monitoring of electrolytes/dental damage", "Admission for refeeding", "Orlistat", "Weight-loss program", "No action - weight is normal"]}', '{"answers": [0]}', 'Bulimia: CBT-based eating-disorder therapy; monitor potassium (vomiting), dental erosion; admission is for medical instability; weight is often normal.', 'Normal weight does not mean normal eating - check the K+.', 'Refeeding protocols for a normal-BMI binge-purge patient.'),
(124, 'AKT', 'Grief', 'Mental health', 'A man whose wife died 4 weeks ago has weeping, poor sleep and reduced appetite but no suicidal ideation, and functions at work. What is the MOST appropriate response?', '{"options": ["Normalise grief, support coping and social connection, review in a few weeks", "Start an SSRI immediately", "Bereavement is a disorder needing treatment", "Refer to a psychiatrist", "Admit"]}', '{"answers": [0]}', 'Acute grief is normal: validate, support, watch for depression or prolonged grief disorder developing (persistent impairment beyond ~6-12 months) - not medicated away in the first weeks.', 'Grief is care, not a prescription.', 'Medicalising the first weeks of loss.'),
(125, 'AKT', 'Confidentiality', 'Ethics and law', 'A 16-year-old asks for contraception, requesting her parents not be told; she is Gillick competent. What is the MOST appropriate approach?', '{"options": ["Assess competence and manage confidentially within her best interests, with confidentiality limits explained", "Refuse without parental consent", "Inform her parents regardless", "Only provide condoms", "Refer to court"]}', '{"answers": [0]}', 'A competent minor can consent to treatment; maintain confidentiality unless risk of serious harm; document competence assessment (understanding, retention, weighing, communication).', 'Competence is decision-specific and assessed, not assumed by age.', 'Automatic parental notification breaching trust.'),
(126, 'AKT', 'Mandatory reporting QLD', 'Ethics and law', 'In Queensland, a doctor suspects significant harm risk to a child from physical abuse. What is the correct action?', '{"options": ["Report the suspicion to Child Safety (mandatory for doctors) - suspicion, not proof, is the threshold", "Only report if the child confirms abuse", "Wait for absolute certainty", "Tell the parents first", "Refer to police only"]}', '{"answers": [0]}', 'QLD: doctors must report a reasonable suspicion of a child suffering, or at risk of, significant harm. Report to Child Safety; verbatim documentation; do not confront the family.', 'Reasonable suspicion is the threshold, not proof.', 'Certainty paralysis while risk persists.'),
(127, 'AKT', 'Medical certificate', 'Ethics and law', 'A patient asks for a backdated medical certificate for three days last week when he was unwell but did not attend. What is the MOST appropriate response?', '{"options": ["Explain certificates must be accurate: you can only certify what you can verify or reasonably attest, and backdating is not acceptable", "Provide it - patient honesty is assumed", "Refuse and end the consultation", "Issue for 7 days to be safe", "Charge extra for the certificate"]}', '{"answers": [0]}', 'Certificates are legal documents; write only what is truthful and verifiable (a certificate can reflect your assessment of the illness period if clearly framed and honest, but not fabricated); backdating to deceive is improper.', 'The certificate protects the truth, not the patient''s roster.', 'Kind-hearted backdating = fraud.'),
(128, 'AKT', 'AHPRA notifications', 'Ethics and law', 'You are treating a doctor for opioid dependence. Are you obliged to report them to AHPRA?', '{"options": ["Generally no - treating practitioners have protection from the impairment mandatory-notification obligation, provided the patient is managed safely", "Yes - all dependent doctors must be reported", "Only if they work in the same practice", "Yes, anonymously", "Only if they agree"]}', '{"answers": [0]}', 'Mandatory notification for impairment generally does NOT apply to treating practitioners; the focus is on supporting treatment and safe practice; notification duties centre on risk to the public (e.g., practising while intoxicated, sexual misconduct, substantial departure).', 'Treat the doctor as a patient - the notification rules are narrower than people fear.', 'Reporting your own patient and destroying their treatment.'),
(129, 'AKT', 'Antibiotic allergy', 'Medication safety', 'A patient labelled ''penicillin allergy - rash as a child'' needs flucloxacillin for cellulitis. What is the BEST approach?', '{"options": ["Take a careful allergy history (reaction, timing, severity) - childhood rash alone often is not true allergy; consider delabelling pathways if low risk", "Avoid all beta-lactams forever", "Use vancomycin", "Prescribe cephalexin without any history", "Oral clindamycin for everyone"]}', '{"answers": [0]}', 'Most ''penicillin allergy'' labels are childhood viral rashes: a structured history (what, when, how severe, immediate vs delayed) and direct antibiotic guidelines (with allergy tools/delabelling where appropriate) restore first-line therapy.', 'The label is often wrong - take the history, then treat.', 'Life-long broad-spectrum avoidance of a mislabel.'),
(130, 'AKT', 'Warfarin interactions', 'Medication safety', 'A patient on warfarin (INR stable) is prescribed a 5-day course of clarithromycin. What is the MOST appropriate action?', '{"options": ["Warn about interaction, increase INR monitoring, and anticipate dose reduction", "Nothing - antibiotics do not affect warfarin", "Stop warfarin completely", "Double the warfarin", "Switch to aspirin"]}', '{"answers": [0]}', 'Clarithromycin inhibits warfarin metabolism (CYP3A4): anticipate INR rise, monitor early (day 3-4), reduce dose as needed; do not stop anticoagulation.', 'New drug on warfarin = new INR check.', 'Discovering the interaction via a bleeding event.'),
(131, 'AKT', 'Renal dosing', 'Medication safety', 'An 82-year-old man (eGFR 32) is prescribed doxycycline. Which statement is MOST correct?', '{"options": ["Doxycycline generally requires no renal dose adjustment", "Halve all doses in CKD", "Doxycycline is contraindicated in CKD", "Double the dose", "Use IV only"]}', '{"answers": [0]}', 'Doxycycline (and azithromycin, rifampicin, linezolid) need no adjustment in renal impairment; commonly misadjusted drugs include DOACs, gabapentinoids, metformin, digoxin, allopurinol.', 'Know the no-adjust list - and the must-adjust list.', 'Blanket dose reduction assumptions causing undertreatment.'),
(132, 'AKT', 'Anaphylaxis', 'Emergency medicine', 'A patient develops urticaria, wheeze and hypotension 10 minutes after an antibiotic in your practice. What is the FIRST-line treatment?', '{"options": ["Intramuscular adrenaline 0.5 mg (0.5 mL of 1:1000) into the outer thigh, repeated every 5 minutes as needed", "IV hydrocortisone first", "Oral antihistamine", "IV adrenaline bolus", "Watchful waiting for 30 minutes"]}', '{"answers": [0]}', 'Anaphylaxis: IM adrenaline into the anterolateral thigh is first-line, dose 0.5 mg adult (repeat 5-minute), lie flat, call 000; steroids and antihistamines are adjuncts that never come first.', 'Adrenaline IM, thigh, now - everything else waits.', 'Corticosteroid-first reflex, wasting the golden minutes.'),
(133, 'AKT', 'Asthma emergency', 'Emergency medicine', 'A 19-year-old with acute severe asthma can only speak in words, SpO2 90%, PEFR <50% predicted, and is getting tired. What is the MOST appropriate immediate action?', '{"options": ["Call 000, continuous salbutamol nebs with ipratropium, systemic corticosteroids, sit upright", "Send home with a new inhaler", "Oral theophylline", "Physiotherapy", "Watch and wait 1 hour"]}', '{"answers": [0]}', 'Severe/life-threatening asthma (speech-in-words, exhaustion): 000, high-flow oxygen, continuous salbutamol + ipratropium, steroids early, prepare for escalation.', 'Speech length is the severity meter.', 'Underestimating the silent, tiring asthmatic.'),
(134, 'AKT', 'Ankle brachial index', 'Emergency medicine', 'A 60-year-old diabetic has a non-healing foot ulcer for 6 weeks. Pulses are barely palpable. What is the MOST appropriate initial vascular assessment?', '{"options": ["Ankle-brachial index (with caution in calcified vessels) and urgent podiatry/diabetes foot-clinic referral", "Compression bandaging", "Hot water soaks", "Gentle debridement by practice nurse alone", "Nothing - diabetic ulcers heal slowly"]}', '{"answers": [0]}', 'Diabetic foot ulcer: assess perfusion (ABI ± toe pressures given calcification risk), offload, urgent multidisciplinary foot-clinic referral; compression without arterial assessment is dangerous.', 'Healing needs perfusion, offloading, and the right clinic - all three.', 'Compressing an ischaemic limb.'),
(135, 'AKT', 'Results follow-up', 'General practice systems', 'Which of the following reflects safe results-management practice in general practice?', '{"options": ["Every result is reviewed, acknowledged and acted on by the ordering clinician with a tracking system", "Reception communicates all results", "No news is good news", "Patients chase their own results", "Results are filed without being seen"]}', '{"answers": [0]}', 'Safe results handling: all results tracked, viewed, and actioned by the clinician; critical results communicated directly; documentation of the plan and the notification.', 'Tracking systems stop balls dropping.', '''No news is good news'' - the classic systemic failure.'),
(136, 'AKT', 'Referral letters', 'General practice systems', 'What makes a referral letter clinically MOST useful?', '{"options": ["A concise structured letter with the question, relevant history/examination/investigations, medication list and what the patient knows", "Copying all notes verbatim", "Length equals thoroughness", "Sending without patient context", "No question, just the diagnosis"]}', '{"answers": [0]}', 'Good referrals ask a clear question with a concise synthesis, and include meds, allergies, and the patient''s understanding (which frames the reply and triage).', 'Ask the question; the specialist will answer it.', 'Ten pages of pasted notes and no actual question.'),
(137, 'KFP', 'Chest pain', 'Cardiovascular health', 'A 62-year-old man presents with 2 hours of central chest pain radiating to his jaw, sweating and nausea. He is a smoker with hypertension. Pain is 7/10. Obs: BP 155/95, HR 96, RR 20, SpO2 97%, afebrile.', '{"parts": [{"q": "List the FOUR most important immediate actions in the practice.", "options": ["Call 000 for emergency transfer", "ECG (already done - review) + continuous monitoring if available", "Aspirin 300 mg chewed (unless contraindicated)", "GTN sublingual if BP allows / relief of pain", "Troponin at the practice", "Oral beta blocker immediately", "Start enoxaparin", "Allow him to drive himself to hospital"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Emergency transfer, ECG review, aspirin, GTN if tolerated. Troponin at GP practice delays transfer; he must not drive."}, {"q": "The ECG shows ST elevation in V2-V4. What is the diagnosis and what happens next?", "options": ["Anterior STEMI - 000, PCI-capable hospital", "NSTEMI - admit under cardiology", "Unstable angina - serial troponin", "Pericarditis - NSAIDs", "Costochondritis - analgesia"], "correct": [0], "marks": "Anterior STEMI = emergency reperfusion. Call 000; primary PCI within 90 minutes of first medical contact."}]}', '{"type": "KFP", "topic": "Chest pain", "unit": "Cardiovascular health", "stem": "A 62-year-old man presents with 2 hours of central chest pain radiating to his jaw, sweating and nausea. He is a smoker with hypertension. Pain is 7/10. Obs: BP 155/95, HR 96, RR 20, SpO2 97%, afebrile.", "parts": [{"q": "List the FOUR most important immediate actions in the practice.", "options": ["Call 000 for emergency transfer", "ECG (already done - review) + continuous monitoring if available", "Aspirin 300 mg chewed (unless contraindicated)", "GTN sublingual if BP allows / relief of pain", "Troponin at the practice", "Oral beta blocker immediately", "Start enoxaparin", "Allow him to drive himself to hospital"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Emergency transfer, ECG review, aspirin, GTN if tolerated. Troponin at GP practice delays transfer; he must not drive."}, {"q": "The ECG shows ST elevation in V2-V4. What is the diagnosis and what happens next?", "options": ["Anterior STEMI - 000, PCI-capable hospital", "NSTEMI - admit under cardiology", "Unstable angina - serial troponin", "Pericarditis - NSAIDs", "Costochondritis - analgesia"], "correct": [0], "marks": "Anterior STEMI = emergency reperfusion. Call 000; primary PCI within 90 minutes of first medical contact."}]}', '', '', ''),
(138, 'KFP', 'Child with fever', 'Child and youth health', 'A 6-month-old boy presents with fever 38.8 for 24 hours, runny nose, slightly reduced feeding but alert and smiling. No focus on examination. Urine clean catch negative. Immunisations up to date.', '{"parts": [{"q": "This presentation is in which traffic-light risk category, and what is the appropriate management?", "options": ["Green (low risk) - home with safety-net advice and review if worsening", "Amber (intermediate) - review within 24h", "Red (high risk) - refer to ED", "Needs immediate IV antibiotics", "Needs chest X-ray"], "correct": [0], "marks": "Alert, smiling, feeding reasonably, normal hydration = green. Safety-net: what to watch for, when to return. Paracetamol for comfort, not to normalise temperature."}, {"q": "List THREE features that would change him to red/high risk requiring ED referral.", "options": ["Non-blanching rash/petechiae", "Drowsy, difficult to rouse", "Grunting, severe work of breathing, SpO2 <92%", "Fever >5 days", "Poor feeding <50% normal", "Bile-stained vomiting", "Temp 39.5 even if playful", "Signs of dehydration (dry mucosae, reduced urine)"], "correct": [0, 1, 2, 3, 4, 5, 7], "marks": "Any 3 of the serious features. High temp alone in a well child is not a red flag by itself."}]}', '{"type": "KFP", "topic": "Child with fever", "unit": "Child and youth health", "stem": "A 6-month-old boy presents with fever 38.8 for 24 hours, runny nose, slightly reduced feeding but alert and smiling. No focus on examination. Urine clean catch negative. Immunisations up to date.", "parts": [{"q": "This presentation is in which traffic-light risk category, and what is the appropriate management?", "options": ["Green (low risk) - home with safety-net advice and review if worsening", "Amber (intermediate) - review within 24h", "Red (high risk) - refer to ED", "Needs immediate IV antibiotics", "Needs chest X-ray"], "correct": [0], "marks": "Alert, smiling, feeding reasonably, normal hydration = green. Safety-net: what to watch for, when to return. Paracetamol for comfort, not to normalise temperature."}, {"q": "List THREE features that would change him to red/high risk requiring ED referral.", "options": ["Non-blanching rash/petechiae", "Drowsy, difficult to rouse", "Grunting, severe work of breathing, SpO2 <92%", "Fever >5 days", "Poor feeding <50% normal", "Bile-stained vomiting", "Temp 39.5 even if playful", "Signs of dehydration (dry mucosae, reduced urine)"], "correct": [0, 1, 2, 3, 4, 5, 7], "marks": "Any 3 of the serious features. High temp alone in a well child is not a red flag by itself."}]}', '', '', ''),
(139, 'KFP', 'Tiredness', 'General', 'A 45-year-old woman presents with 6 months of fatigue. She works full-time, has 2 children, snores, and drinks 3-4 standard drinks nightly. Heavy but regular periods. Exam: BMI 32, BP 132/84. No focal findings.', '{"parts": [{"q": "List the SIX most appropriate first-line investigations.", "options": ["FBE", "UEC", "LFT", "TSH", "Ferritin", "HbA1c or fasting glucose", "CRP", "B12/folate", "Coeliac serology", "Sleep study", "EBV serology", "CT chest"], "correct": [0, 1, 2, 3, 4, 5], "marks": "FBE, UEC, LFT, TSH, ferritin, and glucose/HbA1c cover first-line fatigue workup. CRP if inflammation suspected; B12/folate/coeliac second line; sleep study only if STOP-BANG indicates; not CT."}, {"q": "All results normal except ferritin 15. What are the TWO most likely explanations and the next step for each?", "options": ["Iron deficiency from heavy menstrual bleeding - iron therapy and review of HMB", "Iron deficiency from coeliac disease - add coeliac serology", "Anaemia of chronic disease - repeat in 3 months", "Thalassaemia trait - haemoglobinopathy studies", "Ferritin 15 is normal - no action", "Menopause transition - reassure"], "correct": [0, 1], "marks": "Ferritin 15 in a premenopausal woman with heavy periods = iron deficiency from menstrual loss (most likely); coeliac must be considered. In men and postmenopausal women, iron deficiency = GI malignancy until proven otherwise."}]}', '{"type": "KFP", "topic": "Tiredness", "unit": "General", "stem": "A 45-year-old woman presents with 6 months of fatigue. She works full-time, has 2 children, snores, and drinks 3-4 standard drinks nightly. Heavy but regular periods. Exam: BMI 32, BP 132/84. No focal findings.", "parts": [{"q": "List the SIX most appropriate first-line investigations.", "options": ["FBE", "UEC", "LFT", "TSH", "Ferritin", "HbA1c or fasting glucose", "CRP", "B12/folate", "Coeliac serology", "Sleep study", "EBV serology", "CT chest"], "correct": [0, 1, 2, 3, 4, 5], "marks": "FBE, UEC, LFT, TSH, ferritin, and glucose/HbA1c cover first-line fatigue workup. CRP if inflammation suspected; B12/folate/coeliac second line; sleep study only if STOP-BANG indicates; not CT."}, {"q": "All results normal except ferritin 15. What are the TWO most likely explanations and the next step for each?", "options": ["Iron deficiency from heavy menstrual bleeding - iron therapy and review of HMB", "Iron deficiency from coeliac disease - add coeliac serology", "Anaemia of chronic disease - repeat in 3 months", "Thalassaemia trait - haemoglobinopathy studies", "Ferritin 15 is normal - no action", "Menopause transition - reassure"], "correct": [0, 1], "marks": "Ferritin 15 in a premenopausal woman with heavy periods = iron deficiency from menstrual loss (most likely); coeliac must be considered. In men and postmenopausal women, iron deficiency = GI malignancy until proven otherwise."}]}', '', '', ''),
(140, 'KFP', 'Older person falling', 'Older persons health', 'An 82-year-old woman in a RACF has had 2 falls in 3 months. Medications: amlodipine 5, temazepam 10 nocte, omeprazole 20, paracetamol. BP 138/78 lying, 118/70 standing (asymptomatic). She uses a frame. MMSE 26/30.', '{"parts": [{"q": "List the FOUR most important interventions to reduce falls risk.", "options": ["Stop temazepam (deprescribe benzodiazepine)", "Address postural drop - review amlodipine, slow morning rises", "Physiotherapy strength and balance program", "Vitamin D level +/- supplementation if deficient", "Home/RACF environment hazard assessment", "Start a beta blocker for safety", "Restrict fluids to reduce nocturia", "Bed rest to prevent falls"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4: medication review (benzos first), postural BP management, exercise, vitamin D if deficient, environment. Beta blockers and bed rest are harmful; fluid restriction is wrong."}, {"q": "Her daughter asks if she should be on aspirin for falls prevention. Explain your reasoning.", "options": ["No - aspirin is not for falls prevention; discuss harms vs benefits of any future anticoagulant/fracture prevention individually", "Yes - low-dose aspirin prevents falls", "Only if she has AF", "Yes if DEXA is normal", "Aspirin with omeprazole"], "correct": [0], "marks": "Aspirin does not prevent falls. Falls prevention = the interventions above + bone protection if osteoporotic. A common family misconception - the KFP wants clear risk/benefit explanation."}]}', '{"type": "KFP", "topic": "Older person falling", "unit": "Older persons health", "stem": "An 82-year-old woman in a RACF has had 2 falls in 3 months. Medications: amlodipine 5, temazepam 10 nocte, omeprazole 20, paracetamol. BP 138/78 lying, 118/70 standing (asymptomatic). She uses a frame. MMSE 26/30.", "parts": [{"q": "List the FOUR most important interventions to reduce falls risk.", "options": ["Stop temazepam (deprescribe benzodiazepine)", "Address postural drop - review amlodipine, slow morning rises", "Physiotherapy strength and balance program", "Vitamin D level +/- supplementation if deficient", "Home/RACF environment hazard assessment", "Start a beta blocker for safety", "Restrict fluids to reduce nocturia", "Bed rest to prevent falls"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4: medication review (benzos first), postural BP management, exercise, vitamin D if deficient, environment. Beta blockers and bed rest are harmful; fluid restriction is wrong."}, {"q": "Her daughter asks if she should be on aspirin for falls prevention. Explain your reasoning.", "options": ["No - aspirin is not for falls prevention; discuss harms vs benefits of any future anticoagulant/fracture prevention individually", "Yes - low-dose aspirin prevents falls", "Only if she has AF", "Yes if DEXA is normal", "Aspirin with omeprazole"], "correct": [0], "marks": "Aspirin does not prevent falls. Falls prevention = the interventions above + bone protection if osteoporotic. A common family misconception - the KFP wants clear risk/benefit explanation."}]}', '', '', ''),
(141, 'KFP', 'Abnormal LFTs', 'Gastrointestinal health', 'A 52-year-old asymptomatic man has ALT 95 (ULN 40), ALP 120, GGT 150, bilirubin normal on routine testing. BMI 33, fasting glucose 6.4, lipids mildly raised. Drinks 20 g alcohol/week. No meds.', '{"parts": [{"q": "List the FOUR most appropriate next investigations.", "options": ["Repeat LFTs to confirm", "Hepatitis B and C serology", "Ferritin, transferrin saturation", "Ultrasound abdomen", "Autoimmune antibodies (ANA, ASMA, immunoglobulins)", "Urgent CT abdomen", "Liver biopsy now", "Refer immediately to gastroenterology"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4. Standard tiered MASLD workup: confirm, viral serology, iron studies, ultrasound, autoimmune screen. Biopsy and urgent referral are premature before non-invasive fibrosis staging (FIB-4/elastography)."}, {"q": "The ultrasound shows steatosis. FIB-4 score is 1.1 (low risk). What is the diagnosis and the THREE key management steps?", "options": ["Metabolic dysfunction-associated steatotic liver disease (MASLD)", "Weight loss 7-10% via diet and exercise", "Diabetes prevention - address prediabetes", "Optimise lipids and BP per absolute CVD risk", "Referral for bariatric surgery", "Long-term ursodeoxycholic acid", "Alcohol abstinence only"], "correct": [0, 1, 2, 3], "marks": "MASLD with low fibrosis risk: weight loss is the core therapy, plus metabolic risk factor management. Surgery for selected patients; UDCA not recommended; alcohol minimisation sensible but not the whole answer."}]}', '{"type": "KFP", "topic": "Abnormal LFTs", "unit": "Gastrointestinal health", "stem": "A 52-year-old asymptomatic man has ALT 95 (ULN 40), ALP 120, GGT 150, bilirubin normal on routine testing. BMI 33, fasting glucose 6.4, lipids mildly raised. Drinks 20 g alcohol/week. No meds.", "parts": [{"q": "List the FOUR most appropriate next investigations.", "options": ["Repeat LFTs to confirm", "Hepatitis B and C serology", "Ferritin, transferrin saturation", "Ultrasound abdomen", "Autoimmune antibodies (ANA, ASMA, immunoglobulins)", "Urgent CT abdomen", "Liver biopsy now", "Refer immediately to gastroenterology"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4. Standard tiered MASLD workup: confirm, viral serology, iron studies, ultrasound, autoimmune screen. Biopsy and urgent referral are premature before non-invasive fibrosis staging (FIB-4/elastography)."}, {"q": "The ultrasound shows steatosis. FIB-4 score is 1.1 (low risk). What is the diagnosis and the THREE key management steps?", "options": ["Metabolic dysfunction-associated steatotic liver disease (MASLD)", "Weight loss 7-10% via diet and exercise", "Diabetes prevention - address prediabetes", "Optimise lipids and BP per absolute CVD risk", "Referral for bariatric surgery", "Long-term ursodeoxycholic acid", "Alcohol abstinence only"], "correct": [0, 1, 2, 3], "marks": "MASLD with low fibrosis risk: weight loss is the core therapy, plus metabolic risk factor management. Surgery for selected patients; UDCA not recommended; alcohol minimisation sensible but not the whole answer."}]}', '', '', ''),
(142, 'KFP', 'Haemoptysis', 'Respiratory health', 'A 68-year-old man presents with 3 weeks of intermittent small-volume haemoptysis. 40 pack-year smoker. Weight loss 4 kg. CXR shows a 3 cm right upper lobe mass.', '{"parts": [{"q": "List the THREE most appropriate actions.", "options": ["Urgent respiratory physician referral", "CT chest", "Sputum for cytology/microbiology", "Bronchoscopy scheduling by the practice", "Reassure and repeat CXR in 6 weeks", "Treat as bronchitis with antibiotics", "Arrange D-dimer"], "correct": [0, 1, 2], "marks": "Suspected lung cancer (smoker, weight loss, haemoptysis, mass): urgent respiratory referral + CT chest. Reassurance or delayed repeat imaging = dangerous delay; D-dimer irrelevant."}, {"q": "He asks about his prognosis if it is cancer. List THREE principles of communicating this situation.", "options": ["Assess what he already knows and wants to know first", "Use clear, plain language without euphemism", "Provide information in small chunks with pauses for questions", "Give a detailed statistical survival breakdown immediately", "Refer all questions to the oncologist", "Avoid the topic until results are back"], "correct": [0, 1, 2], "marks": "Any 3: ask first, plain language, chunk and check. Acknowledge uncertainty honestly. Deflection to the oncologist leaves the GP role undone."}]}', '{"type": "KFP", "topic": "Haemoptysis", "unit": "Respiratory health", "stem": "A 68-year-old man presents with 3 weeks of intermittent small-volume haemoptysis. 40 pack-year smoker. Weight loss 4 kg. CXR shows a 3 cm right upper lobe mass.", "parts": [{"q": "List the THREE most appropriate actions.", "options": ["Urgent respiratory physician referral", "CT chest", "Sputum for cytology/microbiology", "Bronchoscopy scheduling by the practice", "Reassure and repeat CXR in 6 weeks", "Treat as bronchitis with antibiotics", "Arrange D-dimer"], "correct": [0, 1, 2], "marks": "Suspected lung cancer (smoker, weight loss, haemoptysis, mass): urgent respiratory referral + CT chest. Reassurance or delayed repeat imaging = dangerous delay; D-dimer irrelevant."}, {"q": "He asks about his prognosis if it is cancer. List THREE principles of communicating this situation.", "options": ["Assess what he already knows and wants to know first", "Use clear, plain language without euphemism", "Provide information in small chunks with pauses for questions", "Give a detailed statistical survival breakdown immediately", "Refer all questions to the oncologist", "Avoid the topic until results are back"], "correct": [0, 1, 2], "marks": "Any 3: ask first, plain language, chunk and check. Acknowledge uncertainty honestly. Deflection to the oncologist leaves the GP role undone."}]}', '', '', ''),
(143, 'KFP', 'Contraception', 'Women''s health', 'A 28-year-old woman 6 weeks postpartum, breastfeeding, not using contraception, wants effective contraception. She has migraine without aura. BP normal. BMI 27.', '{"parts": [{"q": "List the FOUR most suitable options for her situation.", "options": ["Progestogen-only pill (desogestrel or POP)", "Etonogestrel implant", "Copper IUD or LNG-IUD", "Lactational amenorrhoea alone as ongoing contraception", "Combined oral contraceptive", "DMPA injection", "Diaphragm", "Withdrawal method"], "correct": [0, 1, 2], "marks": "Any 3 of the first 3. Breastfeeding: progestogen-only methods and IUDs suitable; combined methods avoided while breastfeeding. LAM alone unreliable at 6 weeks; DMPA acceptable but discuss bone density and return of fertility."}, {"q": "She chooses the implant. List the THREE most important counselling points.", "options": ["Common side effects: irregular bleeding (most common reason for discontinuation)", "Duration of action 3 years, removable anytime", "Effective within 7 days if inserted outside day 1-5 of cycle - backup needed until then", "It protects against STIs", "It causes infertility after removal", "Insertion requires local anaesthetic only - bruising/soreness for days"], "correct": [0, 1, 2, 5], "marks": "Any 3: bleeding profile, 3-year duration, effectiveness timing, insertion expectations. It does NOT protect against STIs and does NOT cause infertility."}]}', '{"type": "KFP", "topic": "Contraception", "unit": "Women''s health", "stem": "A 28-year-old woman 6 weeks postpartum, breastfeeding, not using contraception, wants effective contraception. She has migraine without aura. BP normal. BMI 27.", "parts": [{"q": "List the FOUR most suitable options for her situation.", "options": ["Progestogen-only pill (desogestrel or POP)", "Etonogestrel implant", "Copper IUD or LNG-IUD", "Lactational amenorrhoea alone as ongoing contraception", "Combined oral contraceptive", "DMPA injection", "Diaphragm", "Withdrawal method"], "correct": [0, 1, 2], "marks": "Any 3 of the first 3. Breastfeeding: progestogen-only methods and IUDs suitable; combined methods avoided while breastfeeding. LAM alone unreliable at 6 weeks; DMPA acceptable but discuss bone density and return of fertility."}, {"q": "She chooses the implant. List the THREE most important counselling points.", "options": ["Common side effects: irregular bleeding (most common reason for discontinuation)", "Duration of action 3 years, removable anytime", "Effective within 7 days if inserted outside day 1-5 of cycle - backup needed until then", "It protects against STIs", "It causes infertility after removal", "Insertion requires local anaesthetic only - bruising/soreness for days"], "correct": [0, 1, 2, 5], "marks": "Any 3: bleeding profile, 3-year duration, effectiveness timing, insertion expectations. It does NOT protect against STIs and does NOT cause infertility."}]}', '', '', ''),
(144, 'KFP', 'Type 2 diabetes review', 'Endocrine and metabolic health', 'A 60-year-old man with T2DM for 8 years attends for review. HbA1c 8.5%. On metformin 1g bd and gliclazide 80. eGFR 62, ACR 4 mg/mmol, no retinopathy, BP 138/82, LDL 2.6. BMI 33. Smoker.', '{"parts": [{"q": "List the FOUR most important management changes today.", "options": ["Add an SGLT2 inhibitor (CKD-protective, glycaemic and weight benefit)", "Optimise BP - target generally <130/80 for diabetes with CKD; review therapy", "Address lipids - statin indicated (T2DM aged >=50)", "Smoking cessation - brief intervention + pharmacotherapy", "Add insulin now", "Increase gliclazide to max dose", "Add sitagliptin", "Refer for gastric banding today"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. SGLT2i (CKD/weight), BP control, statin (diabetes >=50), smoking cessation. Insulin not yet at HbA1c 8.5 with other options available; sitagliptin adds little."}, {"q": "He asks about driving. List the TWO key medicolegal points for a diabetic driver on sulfonylurea.", "options": ["Counsel on recognising and managing hypoglycaemia while driving (SU carries hypo risk)", "Reporting obligations to the licensing authority per Austroads if specified conditions develop (e.g., severe hypo requiring assistance)", "His licence is automatically suspended", "He must stop driving", "No restrictions apply to diabetes", "Only insulin-treated drivers need counselling"], "correct": [0, 1], "marks": "Hypoglycaemia counselling + Austroads reporting duties. Not automatic suspension; SU-treated drivers also need counselling."}]}', '{"type": "KFP", "topic": "Type 2 diabetes review", "unit": "Endocrine and metabolic health", "stem": "A 60-year-old man with T2DM for 8 years attends for review. HbA1c 8.5%. On metformin 1g bd and gliclazide 80. eGFR 62, ACR 4 mg/mmol, no retinopathy, BP 138/82, LDL 2.6. BMI 33. Smoker.", "parts": [{"q": "List the FOUR most important management changes today.", "options": ["Add an SGLT2 inhibitor (CKD-protective, glycaemic and weight benefit)", "Optimise BP - target generally <130/80 for diabetes with CKD; review therapy", "Address lipids - statin indicated (T2DM aged >=50)", "Smoking cessation - brief intervention + pharmacotherapy", "Add insulin now", "Increase gliclazide to max dose", "Add sitagliptin", "Refer for gastric banding today"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. SGLT2i (CKD/weight), BP control, statin (diabetes >=50), smoking cessation. Insulin not yet at HbA1c 8.5 with other options available; sitagliptin adds little."}, {"q": "He asks about driving. List the TWO key medicolegal points for a diabetic driver on sulfonylurea.", "options": ["Counsel on recognising and managing hypoglycaemia while driving (SU carries hypo risk)", "Reporting obligations to the licensing authority per Austroads if specified conditions develop (e.g., severe hypo requiring assistance)", "His licence is automatically suspended", "He must stop driving", "No restrictions apply to diabetes", "Only insulin-treated drivers need counselling"], "correct": [0, 1], "marks": "Hypoglycaemia counselling + Austroads reporting duties. Not automatic suspension; SU-treated drivers also need counselling."}]}', '', '', ''),
(145, 'KFP', 'Mental health crisis', 'Mental health', 'A 35-year-old woman presents with 3 months of low mood, anhedonia, insomnia, and 8 kg weight loss. PHQ-9 = 18. She has been thinking life is not worth living, but no plan or intent. She has two children aged 3 and 6 at home.', '{"parts": [{"q": "List the FOUR most important elements of your risk assessment.", "options": ["Ask directly about suicidal thoughts, plan, means, intent", "Assess protective factors (children, supports, treatment engagement)", "Review access to lethal means and safety planning", "Explore substance use and screen for psychotic features", "Contact police immediately", "Remove children from the home", "Arrange admission without assessment"], "correct": [0, 1, 2, 3], "marks": "Direct questions, protective factors, means restriction + safety plan, substance use and psychotic features. Police/child removal premature with no intent disclosed; safety planning with follow-up is the GP standard."}, {"q": "List the FOUR most appropriate management steps for moderate-severe depression with passive suicidal ideation, no plan/intent.", "options": ["Agree a safety plan (warning signs, steps, contacts)", "Same-week review or phone check; close follow-up arranged", "Start an SSRI (e.g., sertraline) with 2-week review", "Refer to a psychologist (mental health treatment plan)", "Advise alcohol reduction and sleep hygiene", "Immediate involuntary admission", "ECT referral", "Do nothing until next routine appointment"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4 of the first 5. Safety plan + follow-up + SSRI + psychological referral + lifestyle. Admission not indicated for passive SI without plan/intent; ECT not first-line."}]}', '{"type": "KFP", "topic": "Mental health crisis", "unit": "Mental health", "stem": "A 35-year-old woman presents with 3 months of low mood, anhedonia, insomnia, and 8 kg weight loss. PHQ-9 = 18. She has been thinking life is not worth living, but no plan or intent. She has two children aged 3 and 6 at home.", "parts": [{"q": "List the FOUR most important elements of your risk assessment.", "options": ["Ask directly about suicidal thoughts, plan, means, intent", "Assess protective factors (children, supports, treatment engagement)", "Review access to lethal means and safety planning", "Explore substance use and screen for psychotic features", "Contact police immediately", "Remove children from the home", "Arrange admission without assessment"], "correct": [0, 1, 2, 3], "marks": "Direct questions, protective factors, means restriction + safety plan, substance use and psychotic features. Police/child removal premature with no intent disclosed; safety planning with follow-up is the GP standard."}, {"q": "List the FOUR most appropriate management steps for moderate-severe depression with passive suicidal ideation, no plan/intent.", "options": ["Agree a safety plan (warning signs, steps, contacts)", "Same-week review or phone check; close follow-up arranged", "Start an SSRI (e.g., sertraline) with 2-week review", "Refer to a psychologist (mental health treatment plan)", "Advise alcohol reduction and sleep hygiene", "Immediate involuntary admission", "ECT referral", "Do nothing until next routine appointment"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4 of the first 5. Safety plan + follow-up + SSRI + psychological referral + lifestyle. Admission not indicated for passive SI without plan/intent; ECT not first-line."}]}', '', '', ''),
(146, 'KFP', 'Cough', 'Respiratory health', 'A 58-year-old woman presents with 8 weeks of dry cough. Never smoker. No wheeze. On ramipril for 5 years. CXR is normal. She has tried saline nasal spray without change.', '{"parts": [{"q": "List the FOUR most likely causes to consider for her chronic cough.", "options": ["Upper airway cough syndrome (post-nasal drip)", "Asthma/cough-variant asthma", "GORD-related cough", "ACE inhibitor (ramipril) cough", "Lung cancer", "Heart failure", "Whooping cough", "Tuberculosis"], "correct": [0, 1, 2, 3], "marks": "Any 4. The big three (upper airway, asthma, reflux) plus ACE-inhibitor cough, in a non-smoker with a normal CXR. Cancer/TB/heart failure are not the leading causes in this low-risk profile but are considered if the trial-of-therapy approach fails."}, {"q": "Outline the next TWO steps in management.", "options": ["Stop or switch the ramipril (e.g., to an ARB) and review in 2-4 weeks", "Sequential trial of therapy for the likely cause(s): intranasal steroid and/or asthma therapy and/or PPI, reviewed at defined intervals", "Immediate CT chest", "Bronchoscopy", "Long-term codeine linctus", "Reassurance only"], "correct": [0, 1], "marks": "ACE cessation first (up to 4 weeks to assess), then empirical sequential trials per the likely cause. Imaging if red flags appear or trials fail; opioids are not management."}]}', '{"type": "KFP", "topic": "Cough", "unit": "Respiratory health", "stem": "A 58-year-old woman presents with 8 weeks of dry cough. Never smoker. No wheeze. On ramipril for 5 years. CXR is normal. She has tried saline nasal spray without change.", "parts": [{"q": "List the FOUR most likely causes to consider for her chronic cough.", "options": ["Upper airway cough syndrome (post-nasal drip)", "Asthma/cough-variant asthma", "GORD-related cough", "ACE inhibitor (ramipril) cough", "Lung cancer", "Heart failure", "Whooping cough", "Tuberculosis"], "correct": [0, 1, 2, 3], "marks": "Any 4. The big three (upper airway, asthma, reflux) plus ACE-inhibitor cough, in a non-smoker with a normal CXR. Cancer/TB/heart failure are not the leading causes in this low-risk profile but are considered if the trial-of-therapy approach fails."}, {"q": "Outline the next TWO steps in management.", "options": ["Stop or switch the ramipril (e.g., to an ARB) and review in 2-4 weeks", "Sequential trial of therapy for the likely cause(s): intranasal steroid and/or asthma therapy and/or PPI, reviewed at defined intervals", "Immediate CT chest", "Bronchoscopy", "Long-term codeine linctus", "Reassurance only"], "correct": [0, 1], "marks": "ACE cessation first (up to 4 weeks to assess), then empirical sequential trials per the likely cause. Imaging if red flags appear or trials fail; opioids are not management."}]}', '', '', ''),
(147, 'KFP', 'Dizziness', 'Neurological presentations', 'A 72-year-old man has recurrent brief dizziness on rolling over in bed and on looking up, each lasting under a minute, with nausea. No hearing loss, no headache. Cardiovascular exam and neurology are normal.', '{"parts": [{"q": "What is the MOST likely diagnosis, and list the TWO features that best support it.", "options": ["Benign paroxysmal positional vertigo", "Brief episodes (seconds) provoked by specific head-position change", "No auditory or neurological symptoms", "Meniere disease", "Vertebrobasilar insufficiency", "Vestibular migraine"], "correct": [0, 1, 2], "marks": "BPPV: seconds-long, positionally triggered (rolling in bed, looking up), no auditory/neuro features. Meniere = hours + hearing loss; VBI = neuro signs; vestibular migraine = minutes-hours + migraine."}, {"q": "List the THREE most appropriate management steps.", "options": ["Dix-Hallpike manoeuvre to confirm (with observation for positional nystagmus)", "Epley manoeuvre (canalith repositioning) - can be performed in the practice", "Explanation and reassurance (often self-limiting)", "Long-term betahistine", "CT brain routinely", "Long-term prochlorperazine", "Referral to neurology in all cases"], "correct": [0, 1, 2], "marks": "Confirm with Dix-Hallpike, treat with Epley (often curative on the spot), reassure. Chronic suppressants (prochlorperazine) delay compensation and are not maintenance; imaging only for atypical features."}]}', '{"type": "KFP", "topic": "Dizziness", "unit": "Neurological presentations", "stem": "A 72-year-old man has recurrent brief dizziness on rolling over in bed and on looking up, each lasting under a minute, with nausea. No hearing loss, no headache. Cardiovascular exam and neurology are normal.", "parts": [{"q": "What is the MOST likely diagnosis, and list the TWO features that best support it.", "options": ["Benign paroxysmal positional vertigo", "Brief episodes (seconds) provoked by specific head-position change", "No auditory or neurological symptoms", "Meniere disease", "Vertebrobasilar insufficiency", "Vestibular migraine"], "correct": [0, 1, 2], "marks": "BPPV: seconds-long, positionally triggered (rolling in bed, looking up), no auditory/neuro features. Meniere = hours + hearing loss; VBI = neuro signs; vestibular migraine = minutes-hours + migraine."}, {"q": "List the THREE most appropriate management steps.", "options": ["Dix-Hallpike manoeuvre to confirm (with observation for positional nystagmus)", "Epley manoeuvre (canalith repositioning) - can be performed in the practice", "Explanation and reassurance (often self-limiting)", "Long-term betahistine", "CT brain routinely", "Long-term prochlorperazine", "Referral to neurology in all cases"], "correct": [0, 1, 2], "marks": "Confirm with Dix-Hallpike, treat with Epley (often curative on the spot), reassure. Chronic suppressants (prochlorperazine) delay compensation and are not maintenance; imaging only for atypical features."}]}', '', '', ''),
(148, 'KFP', 'Weight loss in the elderly', 'Older persons'' health', 'An 84-year-old woman has lost 8 kg over 6 months. She lives alone, has early dementia (MMSE 23/30), takes 8 medications, and has poor dentition. She seems cheerful but thin (BMI 19).', '{"parts": [{"q": "List the SIX most important contributors to assess.", "options": ["Dental/oral pain on chewing (dentition)", "Depression screen", "Medication side-effects (nausea, dry mouth, sedation, appetite loss)", "Swallowing assessment (aspiration, dysphagia)", "Cognitive contribution: forgetting meals, shopping, cooking", "Systemic disease screen (malignancy, thyrotoxicosis, infection, malabsorption)", "Menopause", "Eating disorder"], "correct": [0, 1, 2, 3, 4, 5], "marks": "Any 6 of the first 6. In the elderly weight loss is usually multifactorial: mechanical (teeth, swallow), psychiatric (depression), iatrogenic (drugs), functional (dementia), plus occult disease - each needs a screen. Menopause and eating disorders are not the drivers here."}, {"q": "List the FOUR most appropriate initial investigations.", "options": ["FBE", "UEC, LFT, calcium", "TSH", "ESR/CRP", "Chest X-ray", "CA-19.9 and CEA tumour markers", "Whole-body PET", "Colonoscopy for all elderly weight loss"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4. First-line systemic screen: FBE, UEC/LFT/Ca, TSH, inflammatory markers, CXR. Tumour markers are NOT screening tests (low specificity, no proven role); imaging/endoscopy is targeted by findings."}]}', '{"type": "KFP", "topic": "Weight loss in the elderly", "unit": "Older persons'' health", "stem": "An 84-year-old woman has lost 8 kg over 6 months. She lives alone, has early dementia (MMSE 23/30), takes 8 medications, and has poor dentition. She seems cheerful but thin (BMI 19).", "parts": [{"q": "List the SIX most important contributors to assess.", "options": ["Dental/oral pain on chewing (dentition)", "Depression screen", "Medication side-effects (nausea, dry mouth, sedation, appetite loss)", "Swallowing assessment (aspiration, dysphagia)", "Cognitive contribution: forgetting meals, shopping, cooking", "Systemic disease screen (malignancy, thyrotoxicosis, infection, malabsorption)", "Menopause", "Eating disorder"], "correct": [0, 1, 2, 3, 4, 5], "marks": "Any 6 of the first 6. In the elderly weight loss is usually multifactorial: mechanical (teeth, swallow), psychiatric (depression), iatrogenic (drugs), functional (dementia), plus occult disease - each needs a screen. Menopause and eating disorders are not the drivers here."}, {"q": "List the FOUR most appropriate initial investigations.", "options": ["FBE", "UEC, LFT, calcium", "TSH", "ESR/CRP", "Chest X-ray", "CA-19.9 and CEA tumour markers", "Whole-body PET", "Colonoscopy for all elderly weight loss"], "correct": [0, 1, 2, 3, 4], "marks": "Any 4. First-line systemic screen: FBE, UEC/LFT/Ca, TSH, inflammatory markers, CXR. Tumour markers are NOT screening tests (low specificity, no proven role); imaging/endoscopy is targeted by findings."}]}', '', '', ''),
(149, 'KFP', 'Preventive health check', 'Population health and the context of general practice', 'A 52-year-old man attends for a health assessment. He has not seen a GP for 5 years. Smokes 15/day, BMI 31, BP 148/92 (repeated), drinks 30 standard drinks/week. No meds. No significant family history.', '{"parts": [{"q": "List the SIX most appropriate preventive assessments/interventions for this visit.", "options": ["Absolute CVD risk assessment (45+ male)", "BP confirmation and management plan", "Smoking-cessation brief intervention", "Alcohol brief intervention (AUDIT-C was 8)", "Diabetes screening (HbA1c or fasting glucose)", "Bowel screening iFOBT offer (50-74)", "PSA test without discussion", "Annual whole-body skin checks for everyone", "Routine vitamin levels"], "correct": [0, 1, 2, 3, 4, 5], "marks": "Any 6 of the first 6. This visit packs: CVD risk (age+smoking+BP), BP management, two brief interventions (smoking, alcohol), diabetes screen (obesity), and bowel program participation. PSA is informed-choice only; whole-body checks are not recommended."}, {"q": "His absolute CVD risk returns 12% (moderate). List the FOUR management elements you discuss.", "options": ["Lifestyle plan: smoking, alcohol, diet, activity (moderate risk = aggressive lifestyle first with review)", "Reassess risk in 6-12 months", "BP management: confirm with home readings, consider therapy if sustained >=140/90 after lifestyle attempt", "Statins NOT automatic at 12% - discuss individual factors and preferences", "Start statin today regardless", "Statin never for moderate risk", "Start two antihypertensives today"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Moderate risk: intensive lifestyle with structured review; treat BP if confirmed; statin discussion is individualised (not automatic at moderate risk but considered with additional factors). Neither reflex statin nor reflex dismissal."}]}', '{"type": "KFP", "topic": "Preventive health check", "unit": "Population health and the context of general practice", "stem": "A 52-year-old man attends for a health assessment. He has not seen a GP for 5 years. Smokes 15/day, BMI 31, BP 148/92 (repeated), drinks 30 standard drinks/week. No meds. No significant family history.", "parts": [{"q": "List the SIX most appropriate preventive assessments/interventions for this visit.", "options": ["Absolute CVD risk assessment (45+ male)", "BP confirmation and management plan", "Smoking-cessation brief intervention", "Alcohol brief intervention (AUDIT-C was 8)", "Diabetes screening (HbA1c or fasting glucose)", "Bowel screening iFOBT offer (50-74)", "PSA test without discussion", "Annual whole-body skin checks for everyone", "Routine vitamin levels"], "correct": [0, 1, 2, 3, 4, 5], "marks": "Any 6 of the first 6. This visit packs: CVD risk (age+smoking+BP), BP management, two brief interventions (smoking, alcohol), diabetes screen (obesity), and bowel program participation. PSA is informed-choice only; whole-body checks are not recommended."}, {"q": "His absolute CVD risk returns 12% (moderate). List the FOUR management elements you discuss.", "options": ["Lifestyle plan: smoking, alcohol, diet, activity (moderate risk = aggressive lifestyle first with review)", "Reassess risk in 6-12 months", "BP management: confirm with home readings, consider therapy if sustained >=140/90 after lifestyle attempt", "Statins NOT automatic at 12% - discuss individual factors and preferences", "Start statin today regardless", "Statin never for moderate risk", "Start two antihypertensives today"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Moderate risk: intensive lifestyle with structured review; treat BP if confirmed; statin discussion is individualised (not automatic at moderate risk but considered with additional factors). Neither reflex statin nor reflex dismissal."}]}', '', '', ''),
(150, 'KFP', 'Antenatal booking', 'Pregnancy and reproductive health', 'A 31-year-old G1P0 at 9 weeks presents to establish antenatal care. She is well, takes folic acid, is immune to rubella, and has a normal BMI. Her partner is from a country with high hepatitis B prevalence.', '{"parts": [{"q": "List the SIX routine antenatal screening tests appropriate at booking (first trimester).", "options": ["Blood group and antibodies", "Full blood count", "Hepatitis B serology", "HIV serology", "Syphilis serology", "Midstream urine culture", "Chromosome microarray", "Amniocentesis at booking", "Routine toxoplasmosis serology in all"], "correct": [0, 1, 2, 3, 4, 5], "marks": "Any 6 of the first 6. Booking bloods: group/antibodies, FBE, hepatitis B, HIV, syphilis; plus urine MC&S. (Hep C per risk, VZV if uncertain, chlamydia per risk.) Invasive tests and toxo serology are not routine Australian booking tests."}, {"q": "List the FOUR additional assessments/actions for her specifically.", "options": ["Hepatitis C serology (partner risk)", "Chlamydia screening (per guidelines - offer to all pregnant women <30 or per risk)", "Offer NIPT/cfDNA discussion or combined first-trimester screening (11-13+6 weeks) as per her choice", "Folic acid continuation to 12 weeks; iodine supplementation advice", "CT chest", "Prenatal corticosteroids now", "Anti-D at 9 weeks"], "correct": [0, 1, 2, 3], "marks": "Any 4. Partner risk (Hep B household risk) informs additional screening; STI screen; discuss Down syndrome screening options early (window 11-13+6); folic acid/iodine. Steroids are 24-34 weeks preterm; anti-D is 28 weeks (Rh-negative only) or with sensitising events."}]}', '{"type": "KFP", "topic": "Antenatal booking", "unit": "Pregnancy and reproductive health", "stem": "A 31-year-old G1P0 at 9 weeks presents to establish antenatal care. She is well, takes folic acid, is immune to rubella, and has a normal BMI. Her partner is from a country with high hepatitis B prevalence.", "parts": [{"q": "List the SIX routine antenatal screening tests appropriate at booking (first trimester).", "options": ["Blood group and antibodies", "Full blood count", "Hepatitis B serology", "HIV serology", "Syphilis serology", "Midstream urine culture", "Chromosome microarray", "Amniocentesis at booking", "Routine toxoplasmosis serology in all"], "correct": [0, 1, 2, 3, 4, 5], "marks": "Any 6 of the first 6. Booking bloods: group/antibodies, FBE, hepatitis B, HIV, syphilis; plus urine MC&S. (Hep C per risk, VZV if uncertain, chlamydia per risk.) Invasive tests and toxo serology are not routine Australian booking tests."}, {"q": "List the FOUR additional assessments/actions for her specifically.", "options": ["Hepatitis C serology (partner risk)", "Chlamydia screening (per guidelines - offer to all pregnant women <30 or per risk)", "Offer NIPT/cfDNA discussion or combined first-trimester screening (11-13+6 weeks) as per her choice", "Folic acid continuation to 12 weeks; iodine supplementation advice", "CT chest", "Prenatal corticosteroids now", "Anti-D at 9 weeks"], "correct": [0, 1, 2, 3], "marks": "Any 4. Partner risk (Hep B household risk) informs additional screening; STI screen; discuss Down syndrome screening options early (window 11-13+6); folic acid/iodine. Steroids are 24-34 weeks preterm; anti-D is 28 weeks (Rh-negative only) or with sensitising events."}]}', '', '', '');
INSERT OR IGNORE INTO questions (id, type, topic, unit, stem, options, answers, explanation, pearl, trap) VALUES
(151, 'KFP', 'Postnatal depression', 'Pregnancy and reproductive health', 'A 33-year-old mother of a 10-week-old presents with the baby for a check. You notice she is flat, avoids eye contact, and mentions the baby ''cries all night''. Partner works away. EPDS today is 16.', '{"parts": [{"q": "List the FOUR most important components of assessment.", "options": ["Direct suicide risk assessment (thoughts, plan, means, intent)", "Assessment of bonding/attachment and any thoughts of harm to the baby", "Supports at home (partner availability, family, sleep)", "Sleep, appetite and severity of depression symptoms", "CT brain", "Thyroid function routinely", "Immediate admission for all EPDS ≥15"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. PND assessment: risk to self, risk to/bonding with baby, supports, symptom severity. (TSH if clinical suspicion only; admission is for risk/psychosis/severe impairment, not a score alone.)"}, {"q": "List the FIVE most appropriate management steps.", "options": ["Safety plan and rapid follow-up (within days)", "Referral for perinatal psychological therapy (e.g., through a perinatal mental health pathway)", "SSRI discussion if moderate-severe, with breastfeeding-compatible choices (e.g., sertraline)", "Engage partner/family supports (with consent) including practical night help", "MCH nurse/child health follow-up and GP review scheduled", "Immediate antidepressant only, no therapy", "Discontinue breastfeeding as treatment", "Benzodiazepines long-term"], "correct": [0, 1, 2, 3, 4], "marks": "Any 5 of the first 5. Multimodal: safety, therapy, medication where indicated (breastfeeding-compatible), practical/social supports, structured follow-up. Never stop breastfeeding as ''treatment''; no long-term benzos."}]}', '{"type": "KFP", "topic": "Postnatal depression", "unit": "Pregnancy and reproductive health", "stem": "A 33-year-old mother of a 10-week-old presents with the baby for a check. You notice she is flat, avoids eye contact, and mentions the baby ''cries all night''. Partner works away. EPDS today is 16.", "parts": [{"q": "List the FOUR most important components of assessment.", "options": ["Direct suicide risk assessment (thoughts, plan, means, intent)", "Assessment of bonding/attachment and any thoughts of harm to the baby", "Supports at home (partner availability, family, sleep)", "Sleep, appetite and severity of depression symptoms", "CT brain", "Thyroid function routinely", "Immediate admission for all EPDS ≥15"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. PND assessment: risk to self, risk to/bonding with baby, supports, symptom severity. (TSH if clinical suspicion only; admission is for risk/psychosis/severe impairment, not a score alone.)"}, {"q": "List the FIVE most appropriate management steps.", "options": ["Safety plan and rapid follow-up (within days)", "Referral for perinatal psychological therapy (e.g., through a perinatal mental health pathway)", "SSRI discussion if moderate-severe, with breastfeeding-compatible choices (e.g., sertraline)", "Engage partner/family supports (with consent) including practical night help", "MCH nurse/child health follow-up and GP review scheduled", "Immediate antidepressant only, no therapy", "Discontinue breastfeeding as treatment", "Benzodiazepines long-term"], "correct": [0, 1, 2, 3, 4], "marks": "Any 5 of the first 5. Multimodal: safety, therapy, medication where indicated (breastfeeding-compatible), practical/social supports, structured follow-up. Never stop breastfeeding as ''treatment''; no long-term benzos."}]}', '', '', ''),
(152, 'KFP', 'Chronic pain', 'Pain management', 'A 47-year-old man has 3 years of low back pain following an injury at work. MRI shows mild multi-level disc degeneration, no neural compression. He takes oxycodone 40 mg/day (prescribed elsewhere), reports poor sleep and low mood, and has stopped working.', '{"parts": [{"q": "List the FOUR key elements of a biopsychosocial assessment here.", "options": ["Pain behaviour and flare pattern; function (what he avoids)", "Mood, sleep, catastrophising and beliefs about pain", "Work, compensation and litigation context; social supports", "Medication review: opioid dose, effectiveness, harms, other sedatives", "Repeat MRI to assess progression", "Emergency surgery referral", "Urine drug screening for all patients as a first step"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Chronic pain assessment is biopsychosocial: function, mood/sleep/beliefs, context (work/compensation), and a structured medication review. Repeat imaging without new neurology adds nothing; urine screening is for clinical indication, not blanket first step."}, {"q": "List the FIVE most appropriate management steps.", "options": ["Gradual opioid taper plan with support (never abrupt cessation)", "Enrol in an interdisciplinary pain program (e.g., ADAPT-style) or pain psychologist", "Sleep and mood management (CBT-I principles; treat depression)", "Graded activity/exercise plan with pacing", "Address work capacity/vocational rehabilitation with insurer", "Increase oxycodone as pain persists", "Add benzodiazepine for sleep", "Spinal fusion surgery referral"], "correct": [0, 1, 2, 3, 4], "marks": "Any 5 of the first 5. Chronic pain: taper (high-dose opioids worsen outcomes), interdisciplinary program, mood/sleep, pacing and graded return to work. Escalating opioids, adding benzos, or fusion without specific indication are the classic wrong answers."}]}', '{"type": "KFP", "topic": "Chronic pain", "unit": "Pain management", "stem": "A 47-year-old man has 3 years of low back pain following an injury at work. MRI shows mild multi-level disc degeneration, no neural compression. He takes oxycodone 40 mg/day (prescribed elsewhere), reports poor sleep and low mood, and has stopped working.", "parts": [{"q": "List the FOUR key elements of a biopsychosocial assessment here.", "options": ["Pain behaviour and flare pattern; function (what he avoids)", "Mood, sleep, catastrophising and beliefs about pain", "Work, compensation and litigation context; social supports", "Medication review: opioid dose, effectiveness, harms, other sedatives", "Repeat MRI to assess progression", "Emergency surgery referral", "Urine drug screening for all patients as a first step"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Chronic pain assessment is biopsychosocial: function, mood/sleep/beliefs, context (work/compensation), and a structured medication review. Repeat imaging without new neurology adds nothing; urine screening is for clinical indication, not blanket first step."}, {"q": "List the FIVE most appropriate management steps.", "options": ["Gradual opioid taper plan with support (never abrupt cessation)", "Enrol in an interdisciplinary pain program (e.g., ADAPT-style) or pain psychologist", "Sleep and mood management (CBT-I principles; treat depression)", "Graded activity/exercise plan with pacing", "Address work capacity/vocational rehabilitation with insurer", "Increase oxycodone as pain persists", "Add benzodiazepine for sleep", "Spinal fusion surgery referral"], "correct": [0, 1, 2, 3, 4], "marks": "Any 5 of the first 5. Chronic pain: taper (high-dose opioids worsen outcomes), interdisciplinary program, mood/sleep, pacing and graded return to work. Escalating opioids, adding benzos, or fusion without specific indication are the classic wrong answers."}]}', '', '', ''),
(153, 'KFP', 'Refugee health', 'Migrant, refugee and asylum seeker health', 'A 28-year-old woman recently arrived from a refugee settlement in Africa attends for a health assessment. She speaks no English, is 14 weeks pregnant (first antenatal), and has never had bloods.', '{"parts": [{"q": "List the FOUR most important immediate system actions.", "options": ["Book a professional interpreter (TIS National) for all clinical discussions", "Establish antenatal care pathway (booking bloods, gestation dating)", "Screen for common refugee health issues: hepatitis B, HIV, syphilis, tuberculosis exposure", "Mental health screen (trauma-informed; do not force disclosure), with awareness of torture/trauma prevalence", "Ask her husband to interpret", "Deferred - wait for English proficiency", "Written pamphlets only"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Professional interpreter (never family), start antenatal care, refugee health screening bundle, and trauma-informed mental health approach. Family interpreters breach confidentiality and accuracy."}, {"q": "List the FOUR key components of the refugee health screen relevant to her.", "options": ["Hepatitis B serology (prevalence high; vaccinate if susceptible)", "HIV and syphilis serology", "Tuberculosis screen (IGRA/CXR safe in pregnancy, no live vaccines now)", "Parasite screen if eosinophilia (e.g., strongyloides serology, schistosoma if from an endemic region)", "MMR and varicella vaccines today", "Vitamin B12", "Colonoscopy"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Pregnancy-safe screening bundle: hep B, HIV/syphilis, TB (IGRA/CXR), parasites (strongyloides/schistosoma per geography, esp. Africa). Live vaccines (MMR/varicella) are CONTRAINDICATED in pregnancy - postpartum."}]}', '{"type": "KFP", "topic": "Refugee health", "unit": "Migrant, refugee and asylum seeker health", "stem": "A 28-year-old woman recently arrived from a refugee settlement in Africa attends for a health assessment. She speaks no English, is 14 weeks pregnant (first antenatal), and has never had bloods.", "parts": [{"q": "List the FOUR most important immediate system actions.", "options": ["Book a professional interpreter (TIS National) for all clinical discussions", "Establish antenatal care pathway (booking bloods, gestation dating)", "Screen for common refugee health issues: hepatitis B, HIV, syphilis, tuberculosis exposure", "Mental health screen (trauma-informed; do not force disclosure), with awareness of torture/trauma prevalence", "Ask her husband to interpret", "Deferred - wait for English proficiency", "Written pamphlets only"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Professional interpreter (never family), start antenatal care, refugee health screening bundle, and trauma-informed mental health approach. Family interpreters breach confidentiality and accuracy."}, {"q": "List the FOUR key components of the refugee health screen relevant to her.", "options": ["Hepatitis B serology (prevalence high; vaccinate if susceptible)", "HIV and syphilis serology", "Tuberculosis screen (IGRA/CXR safe in pregnancy, no live vaccines now)", "Parasite screen if eosinophilia (e.g., strongyloides serology, schistosoma if from an endemic region)", "MMR and varicella vaccines today", "Vitamin B12", "Colonoscopy"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Pregnancy-safe screening bundle: hep B, HIV/syphilis, TB (IGRA/CXR), parasites (strongyloides/schistosoma per geography, esp. Africa). Live vaccines (MMR/varicella) are CONTRAINDICATED in pregnancy - postpartum."}]}', '', '', ''),
(154, 'KFP', 'Doctor''s health', 'Doctors'' health', 'You are the GP for a 29-year-old intern who discloses 3 months of exhaustion, night-shift sleep chaos, low mood and a growing dread of work. He admits to taking zopiclone from a sample pack and drinking 6+ standard drinks to sleep. No suicidal ideation. He is terrified of anyone finding out.', '{"parts": [{"q": "List the FOUR most important elements of your management.", "options": ["Treat him as any patient: structured mental health assessment (severity, risk, alcohol review)", "Encourage registration with his own GP and the doctors'' health service (confidential, not reportable)", "Practical work plan discussion: rosters, sleep protection, speaking with DCT/supervisor if and when he consents", "Clear plan for zopiclone/alcohol: safer sleep strategy, short review interval", "Report him to AHPRA today", "Inform his training program without consent", "Refuse to treat a colleague"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Confidential care with risk assessment; doctors'' health services; consent-based workplace steps; address the sedative/alcohol spiral. Reporting is for impaired practice risking the public - not for seeking treatment (treating-doctor exemption)."}, {"q": "Which THREE principles underpin safe care for doctor-patients?", "options": ["Confidentiality equivalent to any patient", "Encourage a treating team separate from workplace (own GP, doctors'' health service)", "Early intervention prevents both patient harm and public risk", "Doctors should self-prescribe", "Colleagues should treat each other", "Sickness in doctors is rare"], "correct": [0, 1, 2], "marks": "Any 3. Same confidentiality, separate treaters, early help. Self-prescribing and informal colleague care are the twin failures of doctors'' health."}]}', '{"type": "KFP", "topic": "Doctor''s health", "unit": "Doctors'' health", "stem": "You are the GP for a 29-year-old intern who discloses 3 months of exhaustion, night-shift sleep chaos, low mood and a growing dread of work. He admits to taking zopiclone from a sample pack and drinking 6+ standard drinks to sleep. No suicidal ideation. He is terrified of anyone finding out.", "parts": [{"q": "List the FOUR most important elements of your management.", "options": ["Treat him as any patient: structured mental health assessment (severity, risk, alcohol review)", "Encourage registration with his own GP and the doctors'' health service (confidential, not reportable)", "Practical work plan discussion: rosters, sleep protection, speaking with DCT/supervisor if and when he consents", "Clear plan for zopiclone/alcohol: safer sleep strategy, short review interval", "Report him to AHPRA today", "Inform his training program without consent", "Refuse to treat a colleague"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Confidential care with risk assessment; doctors'' health services; consent-based workplace steps; address the sedative/alcohol spiral. Reporting is for impaired practice risking the public - not for seeking treatment (treating-doctor exemption)."}, {"q": "Which THREE principles underpin safe care for doctor-patients?", "options": ["Confidentiality equivalent to any patient", "Encourage a treating team separate from workplace (own GP, doctors'' health service)", "Early intervention prevents both patient harm and public risk", "Doctors should self-prescribe", "Colleagues should treat each other", "Sickness in doctors is rare"], "correct": [0, 1, 2], "marks": "Any 3. Same confidentiality, separate treaters, early help. Self-prescribing and informal colleague care are the twin failures of doctors'' health."}]}', '', '', ''),
(155, 'KFP', 'Aboriginal health consultation', 'Aboriginal and Torres Strait Islander health', 'A 52-year-old Aboriginal man attends with tiredness. He has not had a health check for years. HbA1c returns 7.2% (new diabetes). He mentions his father died of ''sugar and kidney trouble''. He is wary of hospitals after his father''s experience.', '{"parts": [{"q": "List the FOUR most important elements of today''s consultation.", "options": ["Ask how he would like his care organised (choice of services, including ATSI community-controlled options)", "Confirm diabetes diagnosis and explain it plainly, linking to family history", "715 health check to structure comprehensive care (CTG entitlements)", "Book follow-up soon with a defined plan - relationship over transaction", "Send a letter to the hospital diabetes clinic today", "Prescribe everything before discussion", "Discount his father''s experience as irrelevant"], "correct": [0, 1, 2, 3], "marks": "Any 4. Patient-led service choices; plain-language diagnosis + family history connection; 715 anchor; early follow-up builds trust (did not attend clinics reflect system failure, not patient failure). His father''s story shapes his engagement - it must be heard."}, {"q": "List the FOUR key management steps for his new type 2 diabetes.", "options": ["Explain diagnosis + confirm (repeat if asymptomatic per guidelines)", "Arrange cycle-of-care: retinal, ACR, eGFR, feet, BP, lipids", "Start metformin with lifestyle (or discuss per guidelines and preference)", "Annual flu + pneumococcal + hepatitis B vaccination review", "Start insulin now", "Daily home glucose monitoring for life", "No treatment - recheck in 2 years"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Confirm and classify; full complication screen; metformin + lifestyle as the base; vaccination review (diabetes = risk group). Insulin and lifelong SMBG are not first steps; ''wait and see'' risks complications given family history."}]}', '{"type": "KFP", "topic": "Aboriginal health consultation", "unit": "Aboriginal and Torres Strait Islander health", "stem": "A 52-year-old Aboriginal man attends with tiredness. He has not had a health check for years. HbA1c returns 7.2% (new diabetes). He mentions his father died of ''sugar and kidney trouble''. He is wary of hospitals after his father''s experience.", "parts": [{"q": "List the FOUR most important elements of today''s consultation.", "options": ["Ask how he would like his care organised (choice of services, including ATSI community-controlled options)", "Confirm diabetes diagnosis and explain it plainly, linking to family history", "715 health check to structure comprehensive care (CTG entitlements)", "Book follow-up soon with a defined plan - relationship over transaction", "Send a letter to the hospital diabetes clinic today", "Prescribe everything before discussion", "Discount his father''s experience as irrelevant"], "correct": [0, 1, 2, 3], "marks": "Any 4. Patient-led service choices; plain-language diagnosis + family history connection; 715 anchor; early follow-up builds trust (did not attend clinics reflect system failure, not patient failure). His father''s story shapes his engagement - it must be heard."}, {"q": "List the FOUR key management steps for his new type 2 diabetes.", "options": ["Explain diagnosis + confirm (repeat if asymptomatic per guidelines)", "Arrange cycle-of-care: retinal, ACR, eGFR, feet, BP, lipids", "Start metformin with lifestyle (or discuss per guidelines and preference)", "Annual flu + pneumococcal + hepatitis B vaccination review", "Start insulin now", "Daily home glucose monitoring for life", "No treatment - recheck in 2 years"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Confirm and classify; full complication screen; metformin + lifestyle as the base; vaccination review (diabetes = risk group). Insulin and lifelong SMBG are not first steps; ''wait and see'' risks complications given family history."}]}', '', '', ''),
(156, 'KFP', 'Occupational dermatitis', 'Occupational and environmental medicine', 'A 34-year-old hairdresser has 8 months of hand dermatitis: scaling, fissures and itch on both palms and fingerwebs, worse at work, marginally better on weekends. Patch testing shows allergy to a hair dye component and an irritant component from shampoos.', '{"parts": [{"q": "What is the MOST likely diagnosis and the TWO contributing mechanisms?", "options": ["Occupational contact dermatitis", "Allergic contact dermatitis (hair dye component)", "Irritant contact dermatitis (wet work/shampoo exposure)", "Psoriasis", "Scabies", "Tinea"], "correct": [0, 1, 2], "marks": "Occupational contact dermatitis with BOTH allergic (hair dye) and irritant (wet work) mechanisms - common in hairdressers. Favouring work/weekend pattern supports occupational causation."}, {"q": "List the FIVE most appropriate management steps.", "options": ["Detailed advice on allergen avoidance (dye component) and reading product labels", "Wet-work reduction: gloves, drying regime, soap substitution", "Potent topical corticosteroid for flare control then stepping down", "Emollient program (multiple daily applications)", "WorkCover notification and occupational assessment (causation has compensation implications)", "Oral prednisolone long-term", "Immediate career change advice", "Methotrexate"], "correct": [0, 1, 2, 3, 4], "marks": "Any 5 of first 5. Allergen avoidance + wet-work reduction + topical therapy + emollients + occupational notification (compensation and workplace modification). Systemic immunosuppression is not the answer; abrupt career advice ignores modification options."}]}', '{"type": "KFP", "topic": "Occupational dermatitis", "unit": "Occupational and environmental medicine", "stem": "A 34-year-old hairdresser has 8 months of hand dermatitis: scaling, fissures and itch on both palms and fingerwebs, worse at work, marginally better on weekends. Patch testing shows allergy to a hair dye component and an irritant component from shampoos.", "parts": [{"q": "What is the MOST likely diagnosis and the TWO contributing mechanisms?", "options": ["Occupational contact dermatitis", "Allergic contact dermatitis (hair dye component)", "Irritant contact dermatitis (wet work/shampoo exposure)", "Psoriasis", "Scabies", "Tinea"], "correct": [0, 1, 2], "marks": "Occupational contact dermatitis with BOTH allergic (hair dye) and irritant (wet work) mechanisms - common in hairdressers. Favouring work/weekend pattern supports occupational causation."}, {"q": "List the FIVE most appropriate management steps.", "options": ["Detailed advice on allergen avoidance (dye component) and reading product labels", "Wet-work reduction: gloves, drying regime, soap substitution", "Potent topical corticosteroid for flare control then stepping down", "Emollient program (multiple daily applications)", "WorkCover notification and occupational assessment (causation has compensation implications)", "Oral prednisolone long-term", "Immediate career change advice", "Methotrexate"], "correct": [0, 1, 2, 3, 4], "marks": "Any 5 of first 5. Allergen avoidance + wet-work reduction + topical therapy + emollients + occupational notification (compensation and workplace modification). Systemic immunosuppression is not the answer; abrupt career advice ignores modification options."}]}', '', '', ''),
(157, 'KFP', 'Sports pre-participation', 'Musculoskeletal presentations', 'A 17-year-old competitive rower attends for a sports medical before the season. He mentions one episode of near-syncope at the end of an intense session last month, and his uncle died suddenly at 40 while exercising.', '{"parts": [{"q": "List the FOUR key elements of assessment.", "options": ["Family history detail (uncle''s death circumstances, any <50 SCD) - pre-participation screen red flag", "Exertional near-syncope history: triggers, timing, symptoms", "Cardiovascular examination incl. BP, murmur (HOCM), radial/femoral pulses (coarctation)", "ECG as part of the screening pathway", "Exercise stress test in the practice", "EEG", "CT knee"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Exertional presyncope + family SCD = red flags: examine, ECG, and refer; history-taking is the highest-yield screen. In-practice stress testing is not the first move."}, {"q": "What is the MOST appropriate referral pathway and the TWO reasons?", "options": ["Urgent cardiology/sports-medicine referral before he returns to competition", "Exertional symptoms + family history of sudden death warrant specialist evaluation before clearance", "A normal ECG alone cannot exclude underlying cardiac disease", "Reassurance and full clearance", "Clearance with a beta-blocker", "Serial review by the coach"], "correct": [0, 1, 2], "marks": "Any 3. Referral pre-clearance because exertional syncope + SCD family history is a recognised red-flag combination; a normal surface ECG does not fully exclude cardiomyopathy/channelopathy - further evaluation (echo, ambulatory ECG, sometimes MRI) is specialist-led."}]}', '{"type": "KFP", "topic": "Sports pre-participation", "unit": "Musculoskeletal presentations", "stem": "A 17-year-old competitive rower attends for a sports medical before the season. He mentions one episode of near-syncope at the end of an intense session last month, and his uncle died suddenly at 40 while exercising.", "parts": [{"q": "List the FOUR key elements of assessment.", "options": ["Family history detail (uncle''s death circumstances, any <50 SCD) - pre-participation screen red flag", "Exertional near-syncope history: triggers, timing, symptoms", "Cardiovascular examination incl. BP, murmur (HOCM), radial/femoral pulses (coarctation)", "ECG as part of the screening pathway", "Exercise stress test in the practice", "EEG", "CT knee"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Exertional presyncope + family SCD = red flags: examine, ECG, and refer; history-taking is the highest-yield screen. In-practice stress testing is not the first move."}, {"q": "What is the MOST appropriate referral pathway and the TWO reasons?", "options": ["Urgent cardiology/sports-medicine referral before he returns to competition", "Exertional symptoms + family history of sudden death warrant specialist evaluation before clearance", "A normal ECG alone cannot exclude underlying cardiac disease", "Reassurance and full clearance", "Clearance with a beta-blocker", "Serial review by the coach"], "correct": [0, 1, 2], "marks": "Any 3. Referral pre-clearance because exertional syncope + SCD family history is a recognised red-flag combination; a normal surface ECG does not fully exclude cardiomyopathy/channelopathy - further evaluation (echo, ambulatory ECG, sometimes MRI) is specialist-led."}]}', '', '', ''),
(158, 'KFP', 'Sexual assault disclosure', 'Abuse and violence', 'A 22-year-old woman discloses she was sexually assaulted by an acquaintance last night. She is tearful, has not told anyone, and asks what her options are. She does not want police involvement at this stage.', '{"parts": [{"q": "List the FOUR most important immediate actions.", "options": ["Immediate medical needs: injuries assessed; emergency contraception discussion (time window)", "Acute psychological care: trauma-informed approach, belief, control back to her", "STI prophylaxis and baseline testing (with follow-up plan) - per protocols", "Forensic option explained WITHOUT pressure: sexual assault service can collect and store evidence even if she has not decided about police", "Insist she reports to police before any care", "Call the police without her consent", "Ask her to recount every detail for the record"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Care before forensics: treat, protect (EC/STI), support - and inform her the forensic window exists with a service that can store evidence while she decides. Police reporting is HER choice (reporting obligations vary by jurisdiction but care never waits)."}, {"q": "List the FOUR elements of follow-up.", "options": ["Scheduled early review (days) - trauma responses evolve", "Safety assessment: does the assailant have access; is she safe where she stays", "Psychological support pathway (counselling, 1800RESPECT)", "Clear documentation of her account in her words (may support later proceedings if she chooses)", "Daily text check-ins", "Prescription of benzodiazepines as routine", "Telling her family"], "correct": [0, 1, 2, 3], "marks": "Any 4. Early structured review, safety planning, counselling, verbatim contemporaneous documentation. Routine sedation displaces proper trauma care; involving family without consent breaches her control."}]}', '{"type": "KFP", "topic": "Sexual assault disclosure", "unit": "Abuse and violence", "stem": "A 22-year-old woman discloses she was sexually assaulted by an acquaintance last night. She is tearful, has not told anyone, and asks what her options are. She does not want police involvement at this stage.", "parts": [{"q": "List the FOUR most important immediate actions.", "options": ["Immediate medical needs: injuries assessed; emergency contraception discussion (time window)", "Acute psychological care: trauma-informed approach, belief, control back to her", "STI prophylaxis and baseline testing (with follow-up plan) - per protocols", "Forensic option explained WITHOUT pressure: sexual assault service can collect and store evidence even if she has not decided about police", "Insist she reports to police before any care", "Call the police without her consent", "Ask her to recount every detail for the record"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Care before forensics: treat, protect (EC/STI), support - and inform her the forensic window exists with a service that can store evidence while she decides. Police reporting is HER choice (reporting obligations vary by jurisdiction but care never waits)."}, {"q": "List the FOUR elements of follow-up.", "options": ["Scheduled early review (days) - trauma responses evolve", "Safety assessment: does the assailant have access; is she safe where she stays", "Psychological support pathway (counselling, 1800RESPECT)", "Clear documentation of her account in her words (may support later proceedings if she chooses)", "Daily text check-ins", "Prescription of benzodiazepines as routine", "Telling her family"], "correct": [0, 1, 2, 3], "marks": "Any 4. Early structured review, safety planning, counselling, verbatim contemporaneous documentation. Routine sedation displaces proper trauma care; involving family without consent breaches her control."}]}', '', '', ''),
(159, 'KFP', 'Opioid safe prescribing', 'Addiction medicine', 'A 45-year-old man with chronic knee pain asks you to take over his oxycodone prescribing from another practice. Records show escalating doses and early scripts over 18 months. He plays cricket and has two teenage kids.', '{"parts": [{"q": "List the FOUR most appropriate steps before any prescribing decision.", "options": ["Full pain assessment (cause, function, what has/has not helped)", "Opioid risk assessment (validated tool, aberrant behaviours) and urine drug screen where indicated", "Obtain records/releases from the previous prescriber", "A written treatment agreement with one prescriber/pharmacy and review intervals", "Prescribe the same dose immediately to maintain trust", "Refuse and discharge him from the practice", "Never ask about his prescribing history"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Before taking over opioid therapy: assess pain and risk, verify history (records, PDMP where available), set a single-prescriber agreement with review. Blanket continuation or abrupt refusal both fail the patient."}, {"q": "He asks for a dose increase because ''nothing works''. List the FOUR best responses.", "options": ["Explain opioid-induced hyperalgesia and loss of efficacy at high doses - more is not better", "Offer a structured non-opioid plan: interdisciplinary pain program, physio, mood/sleep care", "Propose a slow taper with him in control, scheduled reviews and support", "Treat what is actually driving pain behaviour (sleep, mood, function, context)", "Increase the dose to be therapeutic", "Add a second opioid for synergy", "Oxycodone IR PRN on top of his current dose"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Escalation is the trap: explain hyperalgesia, build the non-drug plan, negotiate a supported taper, treat comorbid drivers. Adjunct opioids are the wrong direction."}]}', '{"type": "KFP", "topic": "Opioid safe prescribing", "unit": "Addiction medicine", "stem": "A 45-year-old man with chronic knee pain asks you to take over his oxycodone prescribing from another practice. Records show escalating doses and early scripts over 18 months. He plays cricket and has two teenage kids.", "parts": [{"q": "List the FOUR most appropriate steps before any prescribing decision.", "options": ["Full pain assessment (cause, function, what has/has not helped)", "Opioid risk assessment (validated tool, aberrant behaviours) and urine drug screen where indicated", "Obtain records/releases from the previous prescriber", "A written treatment agreement with one prescriber/pharmacy and review intervals", "Prescribe the same dose immediately to maintain trust", "Refuse and discharge him from the practice", "Never ask about his prescribing history"], "correct": [0, 1, 2, 3], "marks": "Any 4 of first 4. Before taking over opioid therapy: assess pain and risk, verify history (records, PDMP where available), set a single-prescriber agreement with review. Blanket continuation or abrupt refusal both fail the patient."}, {"q": "He asks for a dose increase because ''nothing works''. List the FOUR best responses.", "options": ["Explain opioid-induced hyperalgesia and loss of efficacy at high doses - more is not better", "Offer a structured non-opioid plan: interdisciplinary pain program, physio, mood/sleep care", "Propose a slow taper with him in control, scheduled reviews and support", "Treat what is actually driving pain behaviour (sleep, mood, function, context)", "Increase the dose to be therapeutic", "Add a second opioid for synergy", "Oxycodone IR PRN on top of his current dose"], "correct": [0, 1, 2, 3], "marks": "Any 4 of the first 4. Escalation is the trap: explain hyperalgesia, build the non-drug plan, negotiate a supported taper, treat comorbid drivers. Adjunct opioids are the wrong direction."}]}', '', '', ''),
(160, 'KFP', 'Meningococcal prevention', 'Infectious diseases', 'Public health notifies you that a 19-year-old patient of your practice has invasive meningococcal disease (serogroup B). His 16-year-old brother is your patient and attended today asking for ''the antibiotic''.', '{"parts": [{"q": "What is the recommended prophylaxis for a close household contact, and list the TWO other key actions?", "options": ["Single-dose ciprofloxacin 500 mg oral (or per current guidelines) as soon as possible", "Provide clear safety-net advice: urgent care if fever/rash/illness in the next days", "Confirm vaccination status - Men ACWY and Men B immunisation per schedule/risk", "10-day course of amoxicillin", "No prophylaxis needed", "Isolation at home for 2 weeks", "Chest X-ray"], "correct": [0, 1, 2], "marks": "Any 3. Chemoprophylaxis ASAP (single-dose ciprofloxacin/rifampicin per guidelines), safety-netting for the incubation window, and vaccination review (Men B for serogroup B; Men ACWY per schedule). Antibiotic courses and isolation are not prophylaxis."}, {"q": "List the THREE public-health responsibilities of the practice.", "options": ["Public health manages contact identification - cooperate promptly with the notification process", "Ensure household and close contacts receive timely prophylaxis information", "Maintain accurate records to support contact tracing", "Contact the local newspaper", "Close the practice", "Prescribe prophylaxis to every patient on the books"], "correct": [0, 1, 2], "marks": "Any 3. Coordinate with public health, ensure contacts get timely prophylaxis, keep records supporting tracing. Mass prophylaxis/media/panic are not part of the response."}]}', '{"type": "KFP", "topic": "Meningococcal prevention", "unit": "Infectious diseases", "stem": "Public health notifies you that a 19-year-old patient of your practice has invasive meningococcal disease (serogroup B). His 16-year-old brother is your patient and attended today asking for ''the antibiotic''.", "parts": [{"q": "What is the recommended prophylaxis for a close household contact, and list the TWO other key actions?", "options": ["Single-dose ciprofloxacin 500 mg oral (or per current guidelines) as soon as possible", "Provide clear safety-net advice: urgent care if fever/rash/illness in the next days", "Confirm vaccination status - Men ACWY and Men B immunisation per schedule/risk", "10-day course of amoxicillin", "No prophylaxis needed", "Isolation at home for 2 weeks", "Chest X-ray"], "correct": [0, 1, 2], "marks": "Any 3. Chemoprophylaxis ASAP (single-dose ciprofloxacin/rifampicin per guidelines), safety-netting for the incubation window, and vaccination review (Men B for serogroup B; Men ACWY per schedule). Antibiotic courses and isolation are not prophylaxis."}, {"q": "List the THREE public-health responsibilities of the practice.", "options": ["Public health manages contact identification - cooperate promptly with the notification process", "Ensure household and close contacts receive timely prophylaxis information", "Maintain accurate records to support contact tracing", "Contact the local newspaper", "Close the practice", "Prescribe prophylaxis to every patient on the books"], "correct": [0, 1, 2], "marks": "Any 3. Coordinate with public health, ensure contacts get timely prophylaxis, keep records supporting tracing. Mass prophylaxis/media/panic are not part of the response."}]}', '', '', '');

-- CCE CASES
INSERT OR IGNORE INTO cce_cases (id, title, category, testing, must_hits, traps, structure, phrases, scoring) VALUES
(1, 'Angry patient - delayed referral', 'Difficult consultation', 'Professionalism, conflict de-escalation, maintaining a safe therapeutic relationship while addressing the complaint; complaints handling.', 'Acknowledge and legitimise the frustration without becoming defensive; apologise for the experience (''I am sorry this has been stressful''); stay calm and non-defensive; find out what happened from the patient''s view; identify what they want to happen now; offer clear next steps with a timeframe; offer a follow-up appointment; mention practice complaints process if unresolved.', 'Becoming defensive or justifying the system; matching the patient''s anger; dismissing the complaint; immediately blaming the specialist/hospital; over-promising; failing to acknowledge emotion before problem-solving.', 'Opening: acknowledge early (''I can see this has been really frustrating''). Information gathering: open questions about timeline and impact; screen for clinical harm (did they miss treatment windows?). Explanation: honest account of what you can and cannot control. Management: concrete plan with timeframe. Closure: check understanding, thank them for raising it, arrange review.', '''That sounds genuinely frustrating and I want to understand exactly what happened.'' / ''I am sorry you have had this experience.'' / ''What would a good outcome look like for you from here?'' / ''Here is what I can do this week, and here is what I will find out and get back to you about by Friday.''', 'Examiner marks cluster around: empathy without defensiveness, taking ownership of a system failure, converting anger into a concrete plan, safe clinical review of the underlying condition.'),
(2, 'Demanding antibiotics for a viral URTI', 'Difficult consultation', 'Antimicrobial stewardship communication, shared decision making, holding a safe line under pressure without damaging the relationship.', 'Explore ICE (ideas, concerns, expectations) - why antibiotics, what do they fear (missing work, complications, child care); acknowledge the misery of the illness; give a clear diagnosis and explanation of viral vs bacterial; explain antibiotic harms (side effects, resistance, gut effects); offer a serious alternative plan: symptom relief, safety-netting, a script to use only if deteriorating (delayed prescribing where appropriate); check understanding.', 'Prescribing to end the consultation; lecturing; dismissing expectations without exploring them; vague safety-netting; not offering alternatives.', 'Opening: agenda. Information gathering: ICE + focused history. Explanation: name the diagnosis (viral URTI/bronchitis), explain natural history timeline. Management: symptom relief options, delayed prescription, what to watch for. Closure: check questions, confirm the plan is acceptable.', '''Can I ask what you know about why this keeps happening?'' / ''Most people find the cough lasts up to three weeks and that is normal - what would make you want to be seen again?'' / ''There is a real chance this medicine would give you diarrhoea and no benefit.''', 'Marks for: exploring expectations before refusing; framing antibiotic harms concretely; delayed prescribing as a middle path; explicit safety-netting; maintaining alliance.'),
(3, 'Opioid request from a patient on repeat oxycodone', 'Difficult consultation', 'Chronic pain management, safe opioid prescribing, boundary setting with empathy, dependence recognition.', 'Full pain assessment (site, character, function, flare pattern); assess for opioid misuse red flags (early scripts, lost scripts, multiple prescribers); review PDMP/script history where available; assess function not just pain scores; explain the plan: not increasing the dose; offer a pain management review (multidisciplinary, physio, psychologist-lead pain program); consider opioid tapering discussion; safety-netting for dependence; involve a drug and alcohol service if dependence signs; document.', 'Increasing the dose to end the consultation; framing the patient as drug-seeking without assessment; abrupt cessation without support; missing dependence signs; failing to offer alternatives; being judgemental.', 'Opening: confirm the agenda (pain review + script request). Information gathering: pain story, function, sleep, mood, medication use pattern. Explanation: findings, risks of escalating doses at current levels. Management: structured plan, review interval, alternatives, what you will and will not do. Closure: written plan, follow-up date.', '''Tell me what a good day and a bad day look like now.'' / ''I want to help your pain, and increasing this medicine will not do that - it will change your risk of harm.'' / ''Let us get you into the pain program and review this together in two weeks.''', 'Marks for: assessing before deciding; clear boundary with reason; offering real alternatives; dependence awareness; structured follow-up.'),
(4, 'Vaccine hesitancy in a parent', 'Preventive medicine', 'Risk communication, addressing misinformation, maintaining the relationship, child protection awareness.', 'Non-judgemental exploration of specific concerns (which vaccine, what feared outcome, information source); correct the specific misconception with plain-language evidence (address autism myth directly if raised); strong clear recommendation (vaccination is safe and recommended); avoid dismissing; leave the door open; address the schedule; document the discussion; safety-netting if unimmunised.', 'Dismissiveness (''the science is settled''); overwhelming with data; ignoring the specific fear; ultimatums; failing to give a clear recommendation; not offering another appointment.', 'Opening: rapport. Information gathering: specific concerns. Explanation: address each concern directly; acknowledge uncertainty honestly where it exists (rare adverse events). Management: recommendation + plan; offer follow-up conversation. Closure: warm, non-conditional relationship regardless of decision today.', '''What have you read or heard that worries you most?'' / ''The measles vaccine is about 97% effective at preventing measles, and the risk of a serious reaction to the vaccine itself is far smaller than the risks of measles.'' / ''I am happy to talk more about this any time - my advice is to go ahead.''', 'Marks for: exploring the specific concern; a clear personal recommendation; not burning the relationship; a concrete plan for catch-up or follow-up.'),
(5, 'Abnormal result delivery - high PSA', 'Results and safety', 'Breaking news, risk communication, safety-netting, arranging clear follow-up, managing patient anxiety.', 'Prepare the setting; warn (a shot across the bow: ''I need to talk about a test result that needs more checking''); give the result in plain terms; pause and respond to emotion before details; explain what it may and may not mean (PSA is not a cancer diagnosis); explain the next steps (repeat test, examination, referral pathway, timeframes); check understanding; arrange a definite follow-up point (date, who, where); written information.', 'Cavalier delivery without warning; drowning in statistics before acknowledging emotion; vague ''come back if worried'' without a scheduled review; over-diagnosing (''you have cancer''); no written plan.', 'Opening: agenda + warning shot. Delivery: the headline result in one sentence. Pause: acknowledge and address the emotional response. Explanation: what this might mean, differential. Management: investigations, referrals and timeframes. Closure: summarise, check questions, next appointment.', '''I need to talk with you about a test result today - is now still a good time?'' / ''The test is abnormal, and it does not mean you have cancer - it means we need more tests to be sure.'' / ''Here is the plan and here is the date we will know more.''', 'Marks for: warning before delivering; chunking; tolerance of silence; concrete timeframe; explicit safety-netting; checking understanding.'),
(6, 'Cancer diagnosis consultation', 'Difficult consultation', 'Breaking bad news (SPIKES framework), emotional responsiveness, information structuring, appropriate GP role in the cancer pathway.', 'Setting (private, uninterrupted, support person offered); perception (''what do you know so far''); invitation (''how much detail would you like''); knowledge - warn then deliver the diagnosis in plain language; pause and acknowledge emotion (name it: ''I can see this is a shock''); strategy - treatment pathway, referral, timeframe; safety-netting (symptoms to report); offer a follow-up appointment; offer written information.', 'Delivering the diagnosis without a warning shot; rushing past emotion to logistics; excluding the support person; drowning in staging detail; not offering a next GP contact point.', 'SPIKES with GP flavour: Setting, Perception, Invitation, Knowledge, Emotions, Strategy and Summary.', '''Are you happy for me to go through everything now, or would you rather take it step by step?'' / ''I am sorry - it is cancer.'' (pause, let silence work) / ''You will not be navigating this alone - here is exactly what happens next.''', 'Marks for: following a recognisable breaking-bad-news structure; genuine emotional handling; clear timeframe; explicit GP continuity role.'),
(7, 'Domestic violence disclosure', 'Safety and ethics', 'Safety assessment, confidentiality, validated screening approach, response to disclosure, knowledge of legal duties.', 'Private enquiry (never with partner or children present); direct, normalising question; believe and validate (''this is not your fault''); immediate safety assessment: recent escalation, threats to kill, strangulation, weapons, children''s safety; risk of harm assessment; give information (1800RESPECT, DV connect) without writing it down if unsafe at home; patient-led decision making - do not force leaving; child protection assessment (QLD: witnessing FDV is a reportable harm); document carefully (legible, factual, time-stamped - records can support DVO applications); safety-planning; arrange follow-up.', 'Asking with the partner present; giving advice to leave immediately (peak danger time); breaking confidentiality by involving police without consent (unless imminent risk to life/child safety); failing to assess children; writing information on paper the partner may find.', 'Opening: alone, confidentially. Information gathering: violence pattern, safety, children. Explanation: it is not your fault; there are services. Management: safety plan, referrals, documentation, child assessment. Closure: follow-up plan.', '''Can I ask you a few personal questions? Everything here is confidential.'' / ''Nothing you have told me changes my respect for you.'' / ''Is it safe for you to go home tonight?'' / ''If you ever need it, this number can be called from a locked phone.''', 'Marks for: privacy ensured; direct questioning; validation; children assessed; safety planning; documentation; patient-led pace.'),
(8, 'Adolescent confidentiality - contraception at 15', 'Ethics and law', 'Gillick competence assessment, confidentiality and its limits, adolescent-friendly consultation, mandatory reporting awareness.', 'See the patient alone (explain why to both parent and teen); assess Gillick competence explicitly (understands treatment, benefits, risks, alternatives, consequences of refusing); confidentiality and its limits up-front (will break it if risk of serious harm to self or others); TAKE history (Time alone, Attention, Kick out parents/guardian, Establish confidentiality); contraception discussion; STI screening; mandatory reporting: sexual activity under 16 requires consideration of reportable concerns in most jurisdictions (consent laws vary by state) - know QLD rules; document.', 'Refusing contraception outright because of age; breaking confidentiality to parents without cause; failing to consider mandatory reporting when the partner is older; lecturing; not assessing coercion/exploitation.', 'Opening: contract for confidentiality. Information gathering: HEADSS assessment. Clinical: contraception + STI + safety. Legal: competence + reporting considerations. Closure: plan, follow-up, crisis contacts.', '''Whatever we discuss stays between us unless I think you or someone else is at serious risk.'' / ''Can I check what you already know about how this works?'' / ''Everything you tell me helps me look after you better.''', 'Marks for: seeing alone; explicit competence assessment; stating confidentiality limits; considering reporting duties; non-judgemental rapport.'),
(9, 'Child protection concern - suspicious injury', 'Safety and ethics', 'Recognising abuse patterns, mandatory reporting obligations (QLD), handling the consultation, documentation.', 'Recognise inconsistent injury/history (story does not fit the injury, delay in presentation, changing accounts); pattern injuries; do NOT confront or accuse the caregiver in the room; complete a full head-to-toe examination when safe; document verbatim quotes, body maps; understand QLD mandatory reporting: report to Child Safety (QLD) if you suspect a child has suffered, is suffering, or is at risk of significant harm - GP reporting is mandatory under legislation; consult paediatrics/child protection unit if unsure; safety-netting the child''s immediate situation; do not let the child leave if imminent danger (call police if needed).', 'Confronting the parent (child may be put at further risk); waiting for certainty before reporting (the threshold is reasonable suspicion, not proof); poor documentation (he said/she said without quotes); not reporting because social work ''might not do anything''; missing siblings'' safety.', 'Information gathering: history verbatim, inconsistencies noted gently. Examination: complete, documented. Decision: reporting threshold. Action: report, consult, safety plan. Documentation: exact quotes, timing, who was present.', '''Can you help me understand how this happened - tell me about that day from the beginning.'' / ''I need to make sure Tom is safe - I am going to talk with the child protection team who help us with this.''', 'Marks for: pattern recognition; threshold understanding (reasonable suspicion); not confronting; verbatim documentation; correct QLD pathway.'),
(10, 'Elderly patient with cognitive decline + driving', 'Older persons', 'Capacity vs cognitive impairment, fitness-to-drive legal duties, balancing autonomy and safety, family dynamics.', 'Differentiate dementia vs delirium vs depression; objective cognitive testing plus functional assessment (finance, meds, cooking); ask about driving directly and assess insight; legal duty: conditions likely to affect safe driving must be reported to the licensing authority (Austroads; QLD: Qld Transport) - both patient duty to notify and practitioner reporting pathway; discuss transport alternatives and the identity/financial impacts of losing the licence; involve family with consent; safety-net for getting lost, fires, financial abuse; RACF/GP management plan options.', 'Ignoring the driving issue because it is awkward; assuming capacity is absent because of the diagnosis; breaching confidentiality by reporting without discussing first where safe; focusing only on cognition score rather than function.', 'Information gathering: cognition + function + driving + insight + supports. Explanation: what is happening to memory, what must legally happen about driving. Management: reporting process with patient, alternatives, supports, safety. Closure: follow-up, family meeting.', '''How have you been finding the driving lately - any close calls?'' / ''The law says doctors must let the transport authority know about conditions that affect safe driving - I want us to do this together properly.'' / ''Losing the licence is a huge life change - let us plan how you keep your independence.''', 'Marks for: recognising the legal reporting duty; assessing insight; patient-first process; planning alternatives; distinguishing dementia/delirium/depression.'),
(11, 'Capacity assessment - refusing a needed operation', 'Ethics and law', 'Capacity assessment structure, four-component test, autonomy, escalation when capacity is impaired.', 'Capacity is decision-specific and time-specific; assess for THIS decision; four abilities: understand the information, retain it, weigh it, communicate the choice; use a structured tool where needed; look for reversible causes (delirium, infection, depression); ensure information is given in the best way (interpreter, simple language) BEFORE declaring incapacity; if capacity present: respect the refusal and document; if absent: substitute decision-maker hierarchy (QLD), emergency doctrine for urgent; second opinion for significant decisions; document the assessment itself.', 'Using MMSE as a capacity test; assuming a ''bad'' decision means no capacity; not treating reversible delirium first; skipping the attempt at supported communication; not documenting the assessment process.', 'Information gathering: cognition, delirium screen, mental state. Assessment: the four abilities with the actual decision. Outcome: capacity/no capacity; decision pathway. Documentation and follow-up.', '''I want to make sure this decision is truly yours - let me go through it again and check what matters most to you.'' / ''You have the right to refuse this operation, even if I think it is a mistake - my job is to make sure you have all the facts.''', 'Marks for: decision-specific framing; four-abilities structure; reversible causes; correct pathway if impaired; documentation.'),
(12, 'Medication error disclosure', 'Professionalism and safety', 'Open disclosure, duty of candour, incident management, clinical governance, apology without admission of legal liability (per open disclosure framework).', 'Recognise the error and its clinical impact; prioritise clinical safety of the patient first (assess harm, treat); open disclosure: honest timely communication of what happened; apologise for the harm (''I am sorry this happened to you'') - express regret for the outcome; explain what happened and what will be done; avoid speculation and blame of colleagues; report through the practice incident system; reflect on prevention (system change); document the conversation; offer follow-up and questions; support for the doctor involved (doctors'' health).', 'Concealment or minimising; blaming a colleague or the system (''the nurse''s fault''); promising no consequences; legalese refusal to discuss; failing to treat the clinical consequences first.', 'Immediate: clinical assessment of the patient. Then: open disclosure conversation. Then: incident report, practice learning, documentation, follow-up.', '''I need to tell you about something that should not have happened.'' / ''I am sorry - this should not have happened, and here is what we are doing about it now.'' / ''Here is how we will prevent this happening to someone else.''', 'Marks for: clinical safety first; genuine apology for harm; no blame-shifting; incident reporting; prevention thinking; documentation.'),
(13, 'Colleague impairment concern', 'Professionalism and safety', 'Professional obligation to protect patients, doctors'' health pathways, non-judgemental handling, escalation ladder.', 'Obligation: patient safety comes first - you cannot ignore impairment concerns; approach the colleague directly with concern (health and behaviour observations only, not accusations); strongly encourage the doctor to contact the doctors'' health service (QLD Doctors'' Health Programme) or their own GP; escalate: if they refuse and risk persists - notify the practice principal, Medical Board (mandatory notification for impairment risk, intoxication while practising, or significant departure from standards - ''mandatory notification'' applies to treating practitioners rarely but colleagues have an obligation); not anonymous gossip; documentation.', 'Doing nothing; diagnosing the colleague; going straight to AHPRA without addressing first where safe; gossiping with other staff; taking over their patient load without addressing the cause.', 'Observation: specific, factual concerns. Conversation: concerned, private, supportive. Pathway: own GP / Doctors'' Health. Escalation: if refusal + risk. Documentation.', '''I am worried about you - I have noticed X, and I would want someone to say it to me. Can I help you get some support?'' / ''My first obligation is to patients - I cannot un-see this if nothing changes.''', 'Marks for: patient-safety-first framing; direct supportive approach; knowing doctors'' health services; knowing the escalation duty; avoiding diagnosis/gossip.'),
(14, 'Cultural safety - Aboriginal or Torres Strait Islander patient', 'Cultural safety', 'Cultural safety (not mere awareness), communication, health system navigation, CTG PBS/close the gap items, racism-aware practice.', 'Ask (don''t assume) how the patient identifies and what they prefer (''do you identify as Aboriginal or Torres Strait Islander?'') - asking respectfully supports access to CTG benefits; build understanding of family/community context for decisions; check preferred way of receiving information; use interpreters when needed (Torres Strait Creole etc); offer/flag 715 health check and CTG PBS prescriptions; acknowledge Country where appropriate to the practice context; be aware of institutional barriers past and present (Stolen Generations, stolen wages) and their effect on trust; refer to Aboriginal Community Controlled Health Organisations where the patient prefers; do not treat the person as a spokesperson for their community.', 'Assuming identification from appearance; ignoring CTG entitlements; cultural ''competence'' performance (tokenism); treating culture as a checklist; missing specific clinical risks (e.g. CVD risk assessment from age 30).', 'Opening: rapport, ask about preferences. Information gathering: family, community, social circumstances, holistic health. Clinical: high-priority conditions (diabetes, CVD from 30, kidney). Management: 715 check, CTG scripts, preferred services. Closure: clear follow-up.', '''Can I ask - do you identify as Aboriginal or Torres Strait Islander? It helps me make sure you get everything you are entitled to.'' / ''Who else in your family would you like involved in these decisions?''', 'Marks for: respectful enquiry; CTG items knowledge; family/community context; avoiding stereotypes; genuine two-way communication.'),
(15, 'Interpreter use with a newly arrived patient', 'Migrant and refugee health', 'Working with interpreters, health literacy, refugee health basics, cost barriers, Medicare access.', 'Book a professional interpreter (TIS National - free for GPs for Medicare-eligible patients; document language and dialect); speak to the patient, not the interpreter; short sentences, one idea at a time; teach-back to confirm understanding; be alert to refugee health issues (torture/trauma awareness - do not force disclosure; screening for TB, hepatitis B, parasites, vitamin D, iron); check Medicare/visa status implications for care; cultural mediators where needed; written information in language where possible.', 'Using family members (especially children) as interpreters - breaches confidentiality and accuracy; speaking to the interpreter instead of the patient; assuming English proficiency from a few phrases; missing health-care-access barriers (cost, transport, visa); over-focusing on exotic disease and missing common problems.', 'Opening: introduce via interpreter, confirm language/dialect. Information gathering: presenting complaint + targeted refugee screen when appropriate/consented. Explanation: teach-back. Management: access arrangements, interpreters for future visits. Closure: confirm plan in-language.', '''I will get an interpreter so we can be sure we understand each other properly.'' / ''Just so I know I explained it well - can you tell me in your own words what we will do?''', 'Marks for: professional interpreter; direct address; teach-back; refugee health awareness; access solutions.'),
(16, 'Suicidal patient consultation', 'Mental health', 'Risk assessment depth, safety planning, escalation, documentation, GP confidence with psychiatric emergencies.', 'Direct, calm questioning: thoughts, plan, means access, intent, timeframe, past attempts, substances; risk formulation: acute vs chronic risk; protective factors; means restriction (medication supply, weapons); safety plan (warning signs, coping steps, who to contact, crisis lines); involve supports with consent; decide: community management vs urgent psychiatric assessment vs ED; know when to use the Mental Health Act; document the assessment and plan; follow-up arranged (within days, not weeks); give written crisis numbers.', 'Relying on ''no-suicide contracts''; asking only ''are you thinking of harming yourself?'' without plan/means/intent; missing intoxication; prescribing lethal quantities without a plan; vague ''come back next week''.', 'Opening: direct, unhurried. Assessment: thoughts/plan/means/intent/timeline, past history, substances, protective factors. Formulation: level of risk. Management: safety plan, means restriction, supports, follow-up, escalation if needed. Documentation.', '''When you say you do not want to wake up - do you have thoughts of ending your life?'' / ''Have you thought about how you would do it? Do you have access to that?'' / ''Here is our plan if things get worse this week - who will you call first?''', 'Marks for: depth and directness of assessment; means restriction; safety planning (not contracts); appropriate escalation; concrete follow-up.'),
(17, 'Chronic disease review - GP chronic disease management', 'Chronic disease', 'Structured chronic disease review, GP management plan items (MBS 721/723/725 for chronic condition + complex), team care coordination, self-management support, multimorbidity prioritisation.', 'Structured review of each condition (T2DM, HTN, lipids) with targets reviewed; lifestyle as foundation (exercise, diet, smoking, alcohol); medication review and simplification; complication screening (eyes, feet, kidneys - the annual cycle); GP management plan + team care arrangements when eligible (MBS items); self-management goals with the patient (SMART goals); prioritise what matters most to the patient where multimorbidity competes; coordinate team (dietitian, diabetes educator, podiatry); follow-up interval clear.', 'Glycaemic tunnel vision (ignoring BP/lipids/smoking which often kill more); prescribing without review; not using MBS items to fund team care; excluding the patient from priorities; vague lifestyle advice (''eat better, move more'').', 'Opening: agenda + what matters to the patient. Assessment: targets, complications, function. Management: medication changes, team care, plan items, self-management goals. Closure: written plan, next review.', '''Of everything we manage today - what matters most to you?'' / ''Your blood pressure is what lowers your risk of stroke most - let us start there.'' / ''I will organise the plan that lets the dietitian and diabetes educator be bulk-billed for you.''', 'Marks for: structured comprehensive review; multimorbidity prioritisation; team coordination; patient-centred goals; MBS item knowledge.'),
(18, 'Perimenopause symptom counselling', 'Women''s health', 'Menopause management, MHT risk-benefit communication, individualised care, lifestyle, non-hormonal options.', 'Symptom assessment (VMS, sleep, mood, GSM); frame menopause as normal life stage with a treatment decision, not a disease; MHT: most effective for VMS; discuss type (oestrogen + progestogen if uterus intact), timing hypothesis (start <60y or within 10 years of menopause for favourable risk-benefit), contraindications (hormone-dependent cancer, VTE history, CVD risks); non-hormonal options (SSRIs/SNRIs, clonidine, gabapentin); vaginal oestrogen for GSM (minimal systemic absorption, long-term ok); bone health; lifestyle (weight, exercise, alcohol, smoking); review plan.', 'Either/or thinking (MHT or nothing); treating everyone with MHT; ignoring contraception in perimenopause (still needed 12 months post LMP or age 50-55 rules); forgetting GSM treatment; outdated absolute risk framing (WHI-era blanket fear).', 'Opening: symptom inventory + goals. Information gathering: bleeding pattern, risk factors, family history. Explanation: what is happening; treatment options with risks/benefits. Management: shared decision - MHT type or alternatives, lifestyle. Closure: review in 6-8 weeks, when to report bleeding.', '''There is no right answer for everyone - let us weigh your symptoms against your personal risks.'' / ''The hottest data we have says starting MHT within 10 years of menopause has a favourable safety profile for most women.'' / ''You still need contraception in perimenopause even if periods are irregular.''', 'Marks for: individualised risk-benefit framing; timing hypothesis knowledge; non-hormonal options; GSM addressed; contraception not forgotten.'),
(19, 'Pregnancy counselling - unintended pregnancy', 'Sexual and reproductive health', 'Options counselling (parenting, adoption, termination), non-directiveness, legal knowledge (QLD termination to 22 weeks; >22 weeks specific criteria), signposting, contraception follow-through.', 'Confirm pregnancy dating (dates, ultrasound); non-directive counselling: all three options (continue + parent, continue + adoption, termination) explored without steering; QLD law: termination available on request up to 22 weeks gestation; beyond 22 weeks requires two doctors agreeing specific grounds; provide referral information for whichever option chosen (termination services, antenatal care, perinatal mental health); discuss contraception plan regardless of choice; check for coercion (partner/family pressure either way); screen mental health; document; safety-net (ectopic symptoms).', 'Directiveness (subtle or overt) toward any option; misinformation about termination legality; assuming the partner''s view is hers; forgetting contraception and mental health; missing coercion.', 'Opening: agenda + non-judgemental contract. Information gathering: circumstances, supports, coercion screen, health. Information: options with pathways and timeframes (time-critical). Decision: patient-led. Plan: referral, contraception, follow-up within days. Safety-net.', '''There are three paths from here and I will walk any of them with you - what are you leaning toward?'' / ''Whatever you choose, we will sort out contraception so this does not happen again unless you want it to.''', 'Marks for: genuine non-directiveness; accurate QLD law; time-sensitivity awareness; coercion screen; contraception and follow-up.'),
(20, 'Lifestyle counselling - motivational interviewing', 'Preventive medicine', 'Brief behaviour-change intervention, motivational interviewing technique, avoiding the expert trap, SMART goals.', 'Permission to discuss (''would it be ok if we talked about weight/smoking?''); explore importance (''why is this a 6 and not a 2 for you?''); explore confidence (''what would make it easier?''); reflective listening over advice-giving; elicit change talk; avoid the righting reflex; one behaviour at a time; SMART goal agreed; arrange follow-up; know pharmacotherapy/program options to offer when ready.', 'The righting reflex (arguing for change); vague advice; targeting everything at once; judgement; no follow-up arranged.', 'Opening: permission. MI: importance and confidence rulers, reflective listening. Planning: SMART goal, supports. Closure: follow-up date.', '''Would you mind if we talked about your drinking today?'' / ''You said it is a 6 - why a 6 and not a 2?'' / ''What would need to be different for that to feel possible?''', 'Marks for: permission seeking; MI technique (rulers, reflections, change talk); one SMART goal; follow-up.');

-- GUIDELINES
INSERT OR IGNORE INTO guidelines (id, tier, title, publisher, year, url, key_points, thresholds, exam_relevance) VALUES
(1, 1, 'Guidelines for preventive activities in general practice (Red Book), 10th edition', 'RACGP', '2024', 'https://www.racgp.org.au/clinical-resources/clinical-guidelines/key-racgp-guidelines/view-all-guidelines/red-book', 'The reference for what to screen, when, and what NOT to screen. GRADE-based recommendations; expanded women''s health across the reproductive lifespan.', 'Cervical 25-74 5-yearly HPV; bowel 45-74 2-yearly iFOBT; breast 50-74 2-yearly (40+ eligible); BP checks at every visit; CVD risk 45-74 (30+ ATSI); T2DM screening by risk (every 3 years from 40, or 18 in high-risk groups).', 'AKT asks screening intervals/thresholds directly; KFP builds screening-consultation cases; CCE uses screening conversations.'),
(2, 1, 'Australian Asthma Handbook', 'National Asthma Council Australia', 'Current (living)', 'https://www.nationalasthma.org.au/australian-asthma-handbook/complete-handbook', 'SABA-only treatment is out; ICS-formoterol reliever/maintenance (AIR) for most; assessment of severity/control; written action plans.', 'Reliever use >2x/week = poor control; preventer indicated.', 'Recurring AKT topic and common KFP scenario (the SABA-overuser).'),
(3, 1, 'Therapeutic Guidelines (eTG complete)', 'Therapeutic Guidelines Ltd', 'Living/updated', 'https://tgldcdp-tg-org-au.ezproxy.library.uq.edu.au/ (or https://tg.org.au)', 'The antibiotic reference for Australian GP: first-line choices for common infections, durations, and allergy alternatives.', 'Antibiotic choices, durations, and when not to treat.', 'Directly examinable: first-line antibiotic choices for UTI, cellulitis, pneumonia, sore throat.'),
(4, 1, 'Australian Immunisation Handbook', 'Australian Government Dept Health / ATAGI', 'Living (major updates June 2026)', 'https://immunisationhandbook.health.gov.au/', '21vPCV replaced 13vPCV/23vPPV in adult schedule (2026); RSV program expansion; MenB (with paracetamol prophylaxis); catch-up rules.', 'NIP schedule ages; valid contraindications; minimum intervals.', 'AKT favourite: schedule ages, contraindications, catch-up logic.'),
(5, 1, '2023 Australian Guideline for assessing and managing cardiovascular disease risk', 'Heart Foundation', '2023', 'https://www.heartfoundation.org.au/for-professionals/clinical-resources/cardiovascular-disease-risk-assessment', 'Absolute risk approach using Aus CVD Risk Calculator; assess from 45 (30 ATSI); statin decisions by risk band not LDL alone.', 'Low <10%, moderate 10-15%, high >15% (5-year). High risk: treat. Diabetes >=50, established CVD, CKD, FH = treat regardless.', 'Core AKT/KFP territory: who gets a statin.'),
(6, 1, 'Australian Clinical Guidelines for Diagnosis and Management of Atrial Fibrillation', 'Heart Foundation + CSANZ', '2018 (current)', 'https://www.heartfoundation.org.au/for-professionals/clinical-resources/atrial-fibrillation-resources', 'CHA2DS2-VA (no sex category - Australian change); opportunistic screening pulse/ECG >65; rate vs rhythm.', 'Anticoagulate CHA2DS2-VA >=2 (>=1 in some higher-risk contexts).', 'AKT: anticoagulation threshold and DOAC choice; KFP: AF review cases.'),
(7, 1, 'COPD-X (Australian and New Zealand guidelines for COPD)', 'Lung Foundation Australia', 'Current', 'https://copdx.org.au/copd-x-plan/', 'Confirm with spirometry; smoking cessation changes trajectory; pulmonary rehab; inhaler step-up by exacerbations/eosinophils.', 'Post-bronchodilator FEV1/FVC <0.7 = diagnosis; ICS if eos >=0.3 or >=2 exacerbations.', 'AKT: step-up logic. KFP: the frequent exacerbator.'),
(8, 1, 'Australian STI Management Guidelines for Use in Primary Care', 'ASHM', 'Living', 'http://sti.guidelines.org.au/', 'Site-specific NAAT testing, first-line treatments (as per eTG align), partner notification duties.', 'Screening intervals by risk; test of cure intervals.', 'AKT: STI treatment choices; CCE: sexual history technique.'),
(9, 1, 'National Cervical Screening Program: Guidelines for the management of screen-detected abnormalities', 'Cancer Council Australia / Dept Health', '2016 (updated Dec 2020; current)', 'https://screening.cancer.org.au/cervical/', 'HPV-based screening; self-collection equality; intermediate/higher-risk pathways; exit testing 70-74.', '25-74, 5-yearly; self-collected samples with HPV (not 16/18) require return for LBC.', 'AKT: program intervals; KFP: the overdue/anxious screener.'),
(10, 2, 'Comprehensive Australian Clinical Guideline for ACS (2025)', 'Heart Foundation + CSANZ', '2025', 'https://www.heartfoundation.org.au/for-professionals/clinical-resources/acute-coronary-syndromes', 'New 2025 guideline: ACS pathways, DAPT duration choices, secondary prevention bundle, DOAC+antiplatelet strategies in AF+ACS.', 'DAPT duration by bleeding/ischaemic risk; step-down strategies.', 'AKT: post-ACS medication bundles.'),
(11, 2, 'Guideline for diagnosis and management of hypertension in adults (2016)', 'Heart Foundation', '2016 (2026 guideline in development - Q4 2026)', 'https://www.heartfoundation.org.au/for-professionals/clinical-resources/hypertension', 'Confirm before treating; out-of-office measurement; absolute risk context; new 2026 guideline due Q4 2026 - watch for changes.', 'Diagnosis generally >=140/90 clinic confirmed; management by absolute risk.', 'AKT: who to treat; KFP: white-coat scenario.'),
(12, 2, 'Australian guideline for MASLD (fatty liver)', 'Various (consensus-based)', '2023-2025', '', 'FIB-4 first-line fibrosis staging; 7-10% weight loss core therapy; cardiovascular risk is the main driver of mortality in MASLD.', 'FIB-4 <1.3 low risk (age <65); elastography if intermediate.', 'KFP: abnormal LFT cases; AKT: diagnosis pattern.'),
(13, 2, 'RACGP Silver Book - Medical care of older persons in residential aged care facilities', 'RACGP', 'Current edition', 'https://www.racgp.org.au/clinical-resources/clinical-guidelines/key-racgp-guidelines/view-all-guidelines/silver-book', 'RACF-specific: advance care planning, deprescribing, falls, palliative, behaviour management (avoid chemical restraint).', 'Frailty-aware targets; restrictive practice minimisation.', 'CCE loves RACF scenarios; KFP older-person cases.'),
(14, 2, 'Austroads Assessing Fitness to Drive', 'Austroads', '2024 (current)', 'https://austroads.com.au/drivers-and-vehicles/driver-health/assessing-fitness-to-drive', 'Standards for medical conditions and driving: dementia, epilepsy, diabetes, sleep apnoea, CVD, alcohol. Both patient and practitioner notification duties.', 'Private vs commercial standards differ; e.g., diabetes on insulin: 5-yearly review.', 'AKT/CCE: the driving conversation is high-yield CCE.'),
(15, 2, 'RANZCOG pregnancy care guidelines / antenatal care', 'RANZCOG / Dept Health', 'Current', 'https://www.health.gov.au/our-work/clinical-practice-guidelines-pregnancy-care', 'Antenatal visit schedule, screening tests each trimester, medication safety in pregnancy.', 'First visit by 10-12 weeks; GTT 24-28 weeks; anti-D timings.', 'AKT: antenatal schedule/test timing.'),
(16, 2, 'Type 2 diabetes management in general practice', 'RACGP/Diabetes Australia', '2020 (update in development)', 'https://www.racgp.org.au/clinical-resources/clinical-guidelines/key-racgp-guidelines/view-all-guidelines/type-2-diabetes', 'ADD-STEP comorbidity-based agent selection; annual cycle of care; individualised targets.', 'HbA1c generally <=7%; retinal/foot/ACR annually.', 'Core of multiple AKT questions and KFP reviews.'),
(17, 2, 'Kidney Health Australia - CKD management in primary care', 'Kidney Health Australia', 'Current', 'https://kidney.org.au/health-professionals/chronic-kidney-disease-management-in-primary-care', 'eGFR + ACR staging; RAAS blockade with albuminuria; SGLT2i; nephrology referral criteria.', 'Refer if eGFR <30, ACR >60, rapid decline, or haematuria + proteinuria.', 'KFP: CKD review case; AKT: referral thresholds.'),
(18, 2, 'Voluntary Assisted Dying (QLD)', 'Queensland Health', '2023 (in force)', 'https://www.health.qld.gov.au/__data/assets/pdf_file/0032/1143366/vad-guidance-for-health-practitioners.pdf', 'VAD legal in QLD since Jan 2023: eligibility (adult, resident, decision-capable, intolerable suffering from advanced condition), first/second request process, coordinating practitioner role, conscientious objection rights for doctors.', 'Eligibility is assessed - not all requests proceed; process is strictly legal.', 'CCE ethics stations; AKT legal questions.'),
(19, 3, 'eTG Palliative Care / Therapeutic Guidelines Palliative Care', 'TG Ltd', 'Current', 'https://tg.org.au', 'Anticipatory prescribing sets, terminal care pathways, symptom algorithms.', 'Dosing conversions opioid routes.', 'KFP palliative cases; AKT symptom drug choices.'),
(20, 3, 'RCH Clinical Practice Guidelines (Paediatrics)', 'Royal Children''s Hospital Melbourne', 'Living', 'https://www.rch.org.au/clinicalguide/', 'Practical paediatric protocols: fever, bronchiolitis, croup, gastro, asthma, head injury, analgesia dosing.', 'Weight-based dosing; referral criteria.', 'AKT paediatric dosing and criteria; KFP child cases.'),
(21, 3, 'RACGP Green Book - Putting prevention into practice', 'RACGP', 'Current', 'https://www.racgp.org.au/clinical-resources/clinical-guidelines/key-racgp-guidelines/view-all-guidelines/green-book', 'How to build prevention into practice systems rather than individual willpower.', 'Practice-level recall and reminder systems.', 'Occasional AKT on practice systems.'),
(22, 3, 'White Book - Abuse and violence: working with our patients', 'RACGP', 'Current', 'https://www.racgp.org.au/clinical-resources/clinical-guidelines/key-racgp-guidelines/view-all-guidelines/white-book', 'How to ask, respond, safety-assess, document, and refer for FDV; practice-level safety.', 'Strangulation = high risk marker.', 'CCE FDV station is common; KFP documentation/management questions.');

